use serde::Serialize;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize)]
pub struct JavaScriptSyntaxMetrics {
    pub bytes: usize,
    pub tokens: usize,
    pub ast_nodes: usize,
    pub max_nesting: usize,
    pub functions: usize,
    pub calls: usize,
    pub branches: usize,
    pub loops: usize,
    pub parse_cost: u64,
    pub compile_cost: u64,
    pub estimated_memory_bytes: u64,
}

impl JavaScriptSyntaxMetrics {
    pub fn startup_score(self, parse_weight: u32, compile_weight: u32, memory_weight: u32) -> u64 {
        self.parse_cost
            .saturating_mul(u64::from(parse_weight))
            .saturating_add(self.compile_cost.saturating_mul(u64::from(compile_weight)))
            .saturating_add(
                self.estimated_memory_bytes
                    .saturating_mul(u64::from(memory_weight)),
            )
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PeepholeResult {
    pub code: String,
    pub metrics: JavaScriptSyntaxMetrics,
    pub rewrites: usize,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct JavaScriptParseError {
    offset: usize,
    message: &'static str,
}

impl JavaScriptParseError {
    pub const fn offset(&self) -> usize {
        self.offset
    }
}

impl std::fmt::Display for JavaScriptParseError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            formatter,
            "{} at generated byte {}",
            self.message, self.offset
        )
    }
}

impl std::error::Error for JavaScriptParseError {}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TokenKind {
    Identifier,
    Number,
    String,
    Template,
    Keyword,
    Punct,
    Regex,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Token<'src> {
    kind: TokenKind,
    text: &'src str,
    start: usize,
    end: usize,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Expression<'src> {
    Identifier(&'src str),
    Literal,
    Unary {
        operand: Box<Self>,
    },
    Binary {
        operator: &'src str,
        lhs: Box<Self>,
        rhs: Box<Self>,
    },
    Assignment {
        operator: &'src str,
        lhs: Box<Self>,
        rhs: Box<Self>,
    },
    Conditional {
        condition: Box<Self>,
        then_value: Box<Self>,
        else_value: Box<Self>,
    },
    Call {
        callee: Box<Self>,
        arguments: Vec<Self>,
    },
    Member {
        object: Box<Self>,
        property: Box<Self>,
    },
    Array(Vec<Self>),
    Sequence(Vec<Self>),
}

impl Expression<'_> {
    fn node_count(&self) -> usize {
        match self {
            Self::Identifier(_) | Self::Literal => 1,
            Self::Unary { operand } => 1 + operand.node_count(),
            Self::Binary { lhs, rhs, .. } | Self::Assignment { lhs, rhs, .. } => {
                1 + lhs.node_count() + rhs.node_count()
            }
            Self::Conditional {
                condition,
                then_value,
                else_value,
            } => 1 + condition.node_count() + then_value.node_count() + else_value.node_count(),
            Self::Call { callee, arguments } => {
                1 + callee.node_count() + arguments.iter().map(Self::node_count).sum::<usize>()
            }
            Self::Member { object, property } => 1 + object.node_count() + property.node_count(),
            Self::Array(values) | Self::Sequence(values) => {
                1 + values.iter().map(Self::node_count).sum::<usize>()
            }
        }
    }

    fn max_depth(&self) -> usize {
        match self {
            Self::Identifier(_) | Self::Literal => 1,
            Self::Unary { operand } => 1 + operand.max_depth(),
            Self::Binary { lhs, rhs, .. } | Self::Assignment { lhs, rhs, .. } => {
                1 + lhs.max_depth().max(rhs.max_depth())
            }
            Self::Conditional {
                condition,
                then_value,
                else_value,
            } => {
                1 + condition
                    .max_depth()
                    .max(then_value.max_depth())
                    .max(else_value.max_depth())
            }
            Self::Call { callee, arguments } => {
                1 + arguments
                    .iter()
                    .map(Self::max_depth)
                    .fold(callee.max_depth(), usize::max)
            }
            Self::Member { object, property } => 1 + object.max_depth().max(property.max_depth()),
            Self::Array(values) | Self::Sequence(values) => {
                1 + values.iter().map(Self::max_depth).max().unwrap_or(0)
            }
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Rewrite {
    start: usize,
    end: usize,
    rhs_start: usize,
    rhs_end: usize,
    identifier_start: usize,
    identifier_end: usize,
    operator: &'static str,
}

/// Parses generated JavaScript, applies semantics-preserving local rewrites,
/// and derives deterministic engine-startup proxies from the parsed program.
///
/// The parser is deliberately conservative. Unsupported expressions still
/// contribute to token metrics but are never rewritten.
pub fn optimize_generated_javascript(source: &str) -> Result<PeepholeResult, JavaScriptParseError> {
    let tokens = lex(source)?;
    validate_delimiters(&tokens)?;
    let parsed = parse_expression_regions(&tokens);
    let mut rewrites = parsed
        .iter()
        .filter_map(|region| compound_assignment_rewrite(&tokens, region))
        .collect::<Vec<_>>();
    rewrites.sort_unstable_by_key(|rewrite| (rewrite.start, rewrite.end));
    rewrites.dedup_by_key(|rewrite| (rewrite.start, rewrite.end));
    rewrites = non_overlapping_rewrites(rewrites);

    let code = apply_rewrites(source, &rewrites);
    let (code, rotated_loops) = rotate_proven_initial_true_loops(&code)?;
    let (code, reused_binding) = reuse_dead_var_binding(&code)?;
    let (code, removed_declarations) = remove_unused_standalone_vars(&code)?;
    let (code, merged_declarations) = merge_adjacent_declarations(&code)?;
    let (code, folded_assignment_guards) = fold_assignment_guards(&code)?;
    let (code, folded_index_postfixes) = fold_index_postfix_updates(&code)?;
    let (code, folded_singleton_arrays) = fold_conditional_singleton_arrays(&code)?;
    let (code, folded_and_addends) = fold_guarded_and_addends(&code)?;
    let (code, folded_unit_updates) = fold_unit_counter_updates(&code)?;
    let mut folded_ident_copies = 0usize;
    let mut code = code;
    for _ in 0..8 {
        let (next, count) = fold_identifier_copies(&code)?;
        folded_ident_copies += count;
        code = next;
        if count == 0 {
            break;
        }
    }
    let (code, folded_cached_lengths) = fold_cached_length_conditions(&code)?;
    let (code, folded_cached_members) = fold_cached_member_reads(&code)?;
    let (code, stripped_copy_decls) = strip_unused_simple_declarators(&code)?;
    let (code, folded_literal_aliases) = fold_single_use_literal_bindings(&code)?;
    let (code, folded_proto_tostrings) = fold_prototype_tostring_aliases(&code)?;
    let (code, folded_temp_keys) = fold_temp_index_keys(&code)?;
    let (code, folded_or_returns) = fold_coalesced_or_returns(&code)?;
    let (code, flattened_concats) = flatten_associative_string_concats(&code)?;
    let (code, folded_for_breaks) = fold_for_false_breaks(&code)?;
    let (code, folded_index_walks) = fold_nullish_index_walks(&code)?;
    let (code, folded_trailing_incs) = fold_for_trailing_increments(&code)?;
    let (code, stripped_for_inits) = strip_unused_for_init_vars(&code)?;
    let (code, folded_ident_assigns) = fold_chained_identifier_assigns(&code)?;
    let (code, folded_prefix_incs) = fold_prefix_increment_for_bounds(&code)?;
    let (code, folded_infinite_incs) = fold_increment_infinite_for_bounds(&code)?;
    let (code, folded_dead_inits) = fold_dead_initializer_reassigns(&code)?;
    let (code, folded_void_reassigns) = fold_void_then_reassign(&code)?;
    let (code, folded_index_temps) = fold_single_use_index_temps(&code)?;
    let (code, folded_assigned_indexes) = fold_assigned_index_for_conditions(&code)?;
    let (code, folded_index_scans) = fold_index_scan_for_headers(&code)?;
    let (code, folded_or_assigns) = fold_statement_or_assigns(&code)?;
    let (code, folded_negated_ors) = fold_statement_negated_ors(&code)?;
    let (code, folded_comma_chains) = fold_chained_comma_assigns(&code)?;
    let (code, mut folded_expr_stmts) = fold_adjacent_expression_statements(&code)?;
    let mut folded_loop_braces = 0usize;
    let mut code = code;
    for _ in 0..4 {
        let (next, count) = fold_redundant_loop_body_braces(&code)?;
        folded_loop_braces += count;
        code = next;
        if count == 0 {
            break;
        }
    }
    let (code, folded_for_inits) = fold_prior_assign_into_for_init(&code)?;
    let (code, folded_bool_nots) = fold_boolean_context_double_not(&code)?;
    let (code, flipped_false_eq) = flip_false_equalities(&code)?;
    let (code, folded_single_props) = fold_single_property_objects(&code)?;
    let (code, folded_member_chains) = fold_repeated_member_assigns(&code)?;
    let (code, folded_expression_branches) = fold_expression_branches(&code)?;
    let (code, folded_assigned_ors) = fold_assigned_truthy_ternaries(&code)?;
    let (code, folded_console_logs) = fold_console_log_conditionals(&code)?;
    let (code, folded_guard_returns) = fold_arrow_guard_returns(&code)?;
    let (code, folded_return_tails) = fold_conditional_return_tails(&code)?;
    let (code, folded_return_this) = fold_trailing_return_this(&code)?;
    let (mut code, folded_arrow_bodies) = fold_single_return_arrow_bodies(&code)?;
    let (next, count) = fold_adjacent_expression_statements(&code)?;
    folded_expr_stmts += count;
    code = next;
    for _ in 0..4 {
        let (next, count) = fold_redundant_loop_body_braces(&code)?;
        folded_loop_braces += count;
        code = next;
        if count == 0 {
            break;
        }
    }
    let (next, count) = fold_adjacent_expression_statements(&code)?;
    folded_expr_stmts += count;
    code = next;
    let (code, folded_void_prefix) = fold_void_prefix_updates(&code)?;
    let (code, folded_negated_equalities) = fold_negated_equalities(&code)?;
    let (code, reordered_var_declarators) = reorder_uninitialized_var_declarators(&code)?;
    let (code, canonicalized_leaf_syntax) = canonicalize_leaf_syntax(&code)?;
    let (code, elided_keyword_spaces) = elide_separating_keyword_spaces(&code)?;
    let final_tokens = if rewrites.is_empty()
        && rotated_loops == 0
        && !reused_binding
        && removed_declarations == 0
        && merged_declarations == 0
        && folded_assignment_guards == 0
        && folded_index_postfixes == 0
        && folded_singleton_arrays == 0
        && folded_and_addends == 0
        && folded_unit_updates == 0
        && folded_ident_copies == 0
        && stripped_copy_decls == 0
        && folded_literal_aliases == 0
        && folded_proto_tostrings == 0
        && folded_temp_keys == 0
        && folded_or_returns == 0
        && flattened_concats == 0
        && folded_for_breaks == 0
        && folded_index_walks == 0
        && folded_cached_lengths == 0
        && folded_cached_members == 0
        && folded_trailing_incs == 0
        && stripped_for_inits == 0
        && folded_ident_assigns == 0
        && folded_prefix_incs == 0
        && folded_infinite_incs == 0
        && folded_dead_inits == 0
        && folded_void_reassigns == 0
        && folded_index_temps == 0
        && folded_assigned_indexes == 0
        && folded_index_scans == 0
        && folded_or_assigns == 0
        && folded_void_prefix == 0
        && folded_negated_ors == 0
        && folded_comma_chains == 0
        && folded_expr_stmts == 0
        && folded_loop_braces == 0
        && folded_for_inits == 0
        && folded_bool_nots == 0
        && flipped_false_eq == 0
        && folded_single_props == 0
        && folded_member_chains == 0
        && folded_expression_branches == 0
        && folded_assigned_ors == 0
        && folded_console_logs == 0
        && folded_guard_returns == 0
        && folded_return_tails == 0
        && folded_return_this == 0
        && folded_arrow_bodies == 0
        && folded_negated_equalities == 0
        && reordered_var_declarators == 0
        && canonicalized_leaf_syntax == 0
        && elided_keyword_spaces == 0
    {
        tokens
    } else {
        lex(&code)?
    };
    let final_nesting = validate_delimiters(&final_tokens)?;
    let final_parsed = parse_expression_regions(&final_tokens);
    let metrics = syntax_metrics(&code, &final_tokens, &final_parsed, final_nesting);
    Ok(PeepholeResult {
        code,
        metrics,
        rewrites: rewrites.len()
            + rotated_loops
            + usize::from(reused_binding)
            + removed_declarations
            + merged_declarations
            + folded_assignment_guards
            + folded_index_postfixes
            + folded_singleton_arrays
            + folded_and_addends
            + folded_unit_updates
            + folded_ident_copies
            + stripped_copy_decls
            + folded_literal_aliases
            + folded_proto_tostrings
            + folded_temp_keys
            + folded_or_returns
            + flattened_concats
            + folded_for_breaks
            + folded_index_walks
            + folded_cached_lengths
            + folded_cached_members
            + folded_trailing_incs
            + stripped_for_inits
            + folded_ident_assigns
            + folded_prefix_incs
            + folded_infinite_incs
            + folded_dead_inits
            + folded_void_reassigns
            + folded_index_temps
            + folded_assigned_indexes
            + folded_index_scans
            + folded_or_assigns
            + folded_void_prefix
            + folded_negated_ors
            + folded_comma_chains
            + folded_expr_stmts
            + folded_loop_braces
            + folded_for_inits
            + folded_bool_nots
            + flipped_false_eq
            + folded_single_props
            + folded_member_chains
            + folded_expression_branches
            + folded_assigned_ors
            + folded_console_logs
            + folded_guard_returns
            + folded_return_tails
            + folded_return_this
            + folded_arrow_bodies
            + folded_negated_equalities
            + reordered_var_declarators
            + canonicalized_leaf_syntax
            + elided_keyword_spaces,
    })
}

/// Move declaration-only function-local `var` bindings before the initialized
/// bindings in the same declaration while retaining initializer order.
///
/// ECMAScript instantiates every `var` binding as `undefined` before executing
/// any initializer. An uninitialized declarator therefore performs no runtime
/// operation at its textual position, including in a `for` initializer. This
/// reorder preserves initializer order, suspension, exceptions, closure and
/// direct-eval visibility, but can give gzip and Brotli a better declaration
/// layout. Top-level declarations are excluded because script-mode `var` can
/// create global-object properties in source order. The untouched artifact
/// remains the other exact-codec leaf.
///
/// This deliberately refuses `let`/`const` (TDZ ordering is observable),
/// destructuring, `for-in`/`for-of`, ASI-dependent boundaries, and comments in
/// the separators whose association would otherwise move. The compact lexer
/// cannot distinguish regex punctuation, so callers must provide the same
/// emitter proof used by the other generated-syntax canonicalizations.
fn reorder_uninitialized_var_declarators(
    source: &str,
) -> Result<(String, usize), JavaScriptParseError> {
    if source.contains(['\u{2028}', '\u{2029}']) {
        // ECMAScript treats both Unicode separators as line terminators. The
        // compact lexer deliberately keeps them as punctuation, so fail
        // closed instead of risking an ASI boundary.
        return Ok((source.to_string(), 0));
    }
    let Some(tokens) = lex_certainly(source)? else {
        return Ok((source.to_string(), 0));
    };
    let matching_close = matching_closers(&tokens);
    let mut matching_open = vec![None; tokens.len()];
    for (open, close) in matching_close.iter().enumerate() {
        if let Some(close) = close {
            matching_open[*close] = Some(open);
        }
    }
    let function_bodies = (0..tokens.len())
        .filter(|index| tokens[*index].text == "{")
        .filter_map(|body| {
            let end = matching_close[body]?;
            if body
                .checked_sub(1)
                .is_some_and(|previous| tokens[previous].text == "=>")
            {
                return Some((body, end));
            }
            let close_params = body.checked_sub(1)?;
            if tokens[close_params].text != ")" {
                return None;
            }
            let open_params = matching_open[close_params]?;
            function_header_precedes_parameters(&tokens, open_params).then_some((body, end))
        })
        .collect::<Vec<_>>();
    let mut replacements = Vec::<(usize, usize, String)>::new();

    for var_index in 0..tokens.len() {
        if tokens[var_index].text != "var"
            || !tokens
                .get(var_index + 1)
                .is_some_and(|token| token.kind == TokenKind::Identifier)
            // Top-level script `var` bindings can create global-object
            // properties in declaration order. Function-local `var`
            // bindings have no corresponding property-order observation.
            || !function_bodies
                .iter()
                .any(|(start, end)| *start < var_index && var_index < *end)
        {
            continue;
        }

        let mut delimiters = Vec::<&str>::new();
        let mut segment_start = var_index + 1;
        let mut segments = Vec::<(usize, usize, bool)>::new();
        let mut separator_commas = Vec::<usize>::new();
        let mut cursor = segment_start;
        let mut complete = false;
        while cursor < tokens.len() {
            if delimiters.is_empty()
                && cursor > segment_start
                && source[tokens[cursor - 1].end..tokens[cursor].start]
                    .bytes()
                    .any(|byte| matches!(byte, b'\n' | b'\r'))
            {
                // A line terminator can end the declaration through ASI. Do
                // not consume a following comma expression while searching
                // for a later explicit semicolon.
                break;
            }
            match tokens[cursor].text {
                "(" | "[" | "{" => delimiters.push(tokens[cursor].text),
                ")" | "]" | "}" if !delimiters.is_empty() => {
                    delimiters.pop();
                }
                "," if delimiters.is_empty() => {
                    let Some(initialized) = simple_var_declarator(&tokens, segment_start, cursor)
                    else {
                        break;
                    };
                    segments.push((segment_start, cursor, initialized));
                    separator_commas.push(cursor);
                    segment_start = cursor + 1;
                }
                ";" if delimiters.is_empty() => {
                    let Some(initialized) = simple_var_declarator(&tokens, segment_start, cursor)
                    else {
                        break;
                    };
                    segments.push((segment_start, cursor, initialized));
                    complete = true;
                    break;
                }
                // A multi-binding declaration cannot be a valid for-in/of
                // initializer. Refusing here also prevents treating the
                // iterable expression as part of a declarator.
                "in" | "of" if delimiters.is_empty() => break,
                // The generated candidate normally includes a semicolon.
                // Do not infer line-sensitive ASI boundaries from token gaps.
                ")" | "]" | "}" if delimiters.is_empty() => break,
                _ => {}
            }
            cursor += 1;
        }
        if !complete || segments.len() < 2 {
            continue;
        }

        let declaration_prefix = &source[tokens[var_index].end..tokens[segments[0].0].start];
        if !declaration_prefix
            .bytes()
            .all(|byte| byte.is_ascii_whitespace())
        {
            continue;
        }
        let clean_separators = separator_commas.iter().enumerate().all(|(index, comma)| {
            let left_end = tokens[segments[index].1 - 1].end;
            let right_start = tokens[segments[index + 1].0].start;
            tokens[*comma].start >= left_end
                && tokens[*comma].end <= right_start
                && source[left_end..right_start]
                    .bytes()
                    .all(|byte| byte == b',' || byte.is_ascii_whitespace())
        });
        if !clean_separators {
            continue;
        }

        let first_initialized = segments.iter().position(|segment| segment.2);
        let last_uninitialized = segments.iter().rposition(|segment| !segment.2);
        if !first_initialized
            .zip(last_uninitialized)
            .is_some_and(|(initialized, uninitialized)| initialized < uninitialized)
        {
            continue;
        }

        let ordered = segments
            .iter()
            .filter(|segment| !segment.2)
            .chain(segments.iter().filter(|segment| segment.2));
        let replacement = ordered
            .map(|(start, end, _)| &source[tokens[*start].start..tokens[*end - 1].end])
            .collect::<Vec<_>>()
            .join(",");
        replacements.push((
            tokens[segments[0].0].start,
            tokens[segments.last().expect("multiple segments").1 - 1].end,
            replacement,
        ));
    }

    if replacements.is_empty() {
        return Ok((source.to_string(), 0));
    }
    replacements.sort_unstable_by_key(|(start, end, _)| (*start, *end));
    let mut retained = Vec::with_capacity(replacements.len());
    let mut last_end = 0usize;
    for replacement in replacements {
        if replacement.0 >= last_end {
            last_end = replacement.1;
            retained.push(replacement);
        }
    }
    let count = retained.len();
    let mut output = source.to_string();
    for (start, end, replacement) in retained.into_iter().rev() {
        output.replace_range(start..end, &replacement);
    }
    Ok((output, count))
}

fn function_header_precedes_parameters(tokens: &[Token<'_>], open_params: usize) -> bool {
    let Some(before_params) = open_params.checked_sub(1) else {
        return false;
    };
    let function = if tokens[before_params].text == "function" {
        // Anonymous ordinary functions and methods literally named
        // `function` both introduce a function-local `var` scope.
        Some(before_params)
    } else if tokens[before_params].text == "*" {
        before_params
            .checked_sub(1)
            .filter(|index| tokens[*index].text == "function")
    } else if tokens[before_params].kind == TokenKind::Identifier {
        let before_name = before_params.checked_sub(1);
        before_name.and_then(|index| {
            if tokens[index].text == "function" {
                Some(index)
            } else if tokens[index].text == "*" {
                index
                    .checked_sub(1)
                    .filter(|function| tokens[*function].text == "function")
            } else {
                Some(before_params)
            }
        })
        .or(Some(before_params))
    } else {
        None
    };
    function.is_some_and(|index| {
        !index
            .checked_sub(1)
            .is_some_and(|previous| matches!(tokens[previous].text, "." | "?." | "#"))
    })
}

fn simple_var_declarator(tokens: &[Token<'_>], start: usize, end: usize) -> Option<bool> {
    if start >= end || tokens[start].kind != TokenKind::Identifier {
        return None;
    }
    match end - start {
        1 => Some(false),
        _ if tokens[start + 1].text == "=" => Some(true),
        _ => None,
    }
}

/// Canonicalize two grammar-local spellings emitted by the IR backend:
/// `typeof(identifier)` and `object["IdentifierName"]`. The compact lexer does
/// not distinguish division from regular-expression literals, so callers must
/// prove that regex literals are absent before entering this pass. Quoted
/// strings and templates are single tokens and exact byte-adjacency checks keep
/// comments and escaped property keys outside every replacement.
fn canonicalize_leaf_syntax(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let Some(tokens) = lex_certainly(source)? else {
        return Ok((source.to_string(), 0));
    };
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();

    for index in 0..tokens.len() {
        if tokens[index].text == "typeof"
            && tokens.get(index + 1).map(|token| token.text) == Some("(")
            && matching_close[index + 1] == Some(index + 3)
            && tokens
                .get(index + 2)
                .is_some_and(|token| token.kind == TokenKind::Identifier)
            && tokens[index].end == tokens[index + 1].start
            && tokens[index + 1].end == tokens[index + 2].start
            && tokens[index + 2].end == tokens[index + 3].start
            && !parenthesized_expression_has_postfix_continuation(&tokens, index + 3)
        {
            let mut replacement = format!("typeof {}", tokens[index + 2].text);
            if tokens.get(index + 4).is_some_and(|next| {
                next.start == tokens[index + 3].end
                    && matches!(
                        next.kind,
                        TokenKind::Identifier | TokenKind::Keyword | TokenKind::Number
                    )
            }) {
                replacement.push(' ');
            }
            replacements.push((tokens[index].start, tokens[index + 3].end, replacement));
        }

        if tokens[index].text != "["
            || tokens.get(index + 1).map(|token| token.kind) != Some(TokenKind::String)
            || tokens.get(index + 2).map(|token| token.text) != Some("]")
            || tokens[index].end != tokens[index + 1].start
            || tokens[index + 1].end != tokens[index + 2].start
            || tokens.get(index.wrapping_sub(1)).map(|token| token.end) != Some(tokens[index].start)
            || !tokens
                .get(index.wrapping_sub(1))
                .is_some_and(member_object_can_end_with)
        {
            continue;
        }
        let Some(property) = ascii_identifier_name_string(tokens[index + 1].text) else {
            continue;
        };
        let mut replacement = format!(".{property}");
        if tokens.get(index + 3).is_some_and(|next| {
            next.start == tokens[index + 2].end
                && matches!(
                    next.kind,
                    TokenKind::Identifier | TokenKind::Keyword | TokenKind::Number
                )
        }) {
            replacement.push(' ');
        }
        replacements.push((tokens[index].start, tokens[index + 2].end, replacement));
    }

    if replacements.is_empty() {
        return Ok((source.to_string(), 0));
    }
    replacements.sort_unstable_by_key(|(start, end, _)| (*start, *end));
    replacements.dedup_by(|left, right| left.0 == right.0 && left.1 == right.1);
    let count = replacements.len();
    let mut output = source.to_string();
    for (start, end, replacement) in replacements.into_iter().rev() {
        output.replace_range(start..end, &replacement);
    }
    Ok((output, count))
}

fn member_object_can_end_with(token: &Token<'_>) -> bool {
    token.kind == TokenKind::Identifier
        || (token.kind == TokenKind::Keyword && matches!(token.text, "this" | "super"))
}

fn ascii_identifier_name_string(literal: &str) -> Option<&str> {
    let bytes = literal.as_bytes();
    if bytes.len() < 3
        || !matches!(bytes[0], b'\'' | b'"')
        || bytes.last().copied() != Some(bytes[0])
    {
        return None;
    }
    let identifier = &bytes[1..bytes.len() - 1];
    if !is_identifier_start(identifier[0])
        || !identifier[1..].iter().copied().all(is_identifier_continue)
    {
        return None;
    }
    Some(&literal[1..literal.len() - 1])
}

/// Fold a braced `if`/`else` whose arms contain only expression statements
/// into a conditional expression. Comma grouping preserves the sequencing in
/// multi-statement arms. The untouched artifact remains a final codec-scored
/// candidate, so this raw-byte rewrite is never forced when gzip or Brotli
/// prefers the structured spelling.
fn fold_expression_branches(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut matching_close = vec![None; tokens.len()];
    let mut stack = Vec::<usize>::new();
    for (index, token) in tokens.iter().enumerate() {
        match token.text {
            "(" | "[" | "{" => stack.push(index),
            ")" | "]" | "}" => {
                let Some(open) = stack.pop() else {
                    continue;
                };
                matching_close[open] = Some(index);
            }
            _ => {}
        }
    }

    let mut replacements = Vec::<(usize, usize, String)>::new();
    for if_index in 0..tokens.len() {
        if tokens[if_index].text != "if"
            || tokens.get(if_index + 1).map(|token| token.text) != Some("(")
        {
            continue;
        }
        let condition_open = if_index + 1;
        let Some(condition_close) = matching_close[condition_open] else {
            continue;
        };
        let then_open = condition_close + 1;
        if tokens.get(then_open).map(|token| token.text) != Some("{") {
            continue;
        }
        let Some(then_close) = matching_close[then_open] else {
            continue;
        };
        if tokens.get(then_close + 1).map(|token| token.text) != Some("else") {
            continue;
        }
        let else_open = then_close + 2;
        if tokens.get(else_open).map(|token| token.text) != Some("{") {
            continue;
        }
        let Some(else_close) = matching_close[else_open] else {
            continue;
        };
        let Some(then_value) =
            expression_statement_sequence(source, &tokens, then_open + 1, then_close)
        else {
            continue;
        };
        let Some(else_value) =
            expression_statement_sequence(source, &tokens, else_open + 1, else_close)
        else {
            continue;
        };
        let condition = &source[tokens[condition_open].end..tokens[condition_close].start];
        let condition =
            if conditional_test_needs_grouping(&tokens[condition_open + 1..condition_close]) {
                format!("({condition})")
            } else {
                condition.to_string()
            };
        let mut end = tokens[else_close].end;
        if tokens.get(else_close + 1).map(|token| token.text) == Some(";") {
            end = tokens[else_close + 1].end;
        }
        let replacement = if let (Some(then_arg), Some(else_arg)) = (
            single_console_log_argument(&then_value),
            single_console_log_argument(&else_value),
        ) {
            format!("console.log({condition}?{then_arg}:{else_arg});")
        } else {
            format!("{condition}?{then_value}:{else_value};")
        };
        if replacement.len() < end - tokens[if_index].start {
            replacements.push((tokens[if_index].start, end, replacement));
        }
    }
    if replacements.is_empty() {
        return Ok((source.to_string(), 0));
    }
    replacements.sort_unstable_by_key(|(start, end, _)| (*start, *end));
    let mut retained = Vec::new();
    let mut last_end = 0;
    for replacement in replacements {
        if replacement.0 >= last_end {
            last_end = replacement.1;
            retained.push(replacement);
        }
    }
    let count = retained.len();
    let mut output = source.to_string();
    for (start, end, replacement) in retained.into_iter().rev() {
        output.replace_range(start..end, &replacement);
    }
    Ok((output, count))
}

fn expression_statement_sequence(
    source: &str,
    tokens: &[Token<'_>],
    start: usize,
    end: usize,
) -> Option<String> {
    let mut cursor = start;
    let mut expressions = Vec::<String>::new();
    while cursor < end {
        while cursor < end && tokens[cursor].text == ";" {
            cursor += 1;
        }
        if cursor == end {
            break;
        }
        let mut depth = 0usize;
        let mut statement_end = end;
        for (index, token) in tokens.iter().enumerate().take(end).skip(cursor) {
            match token.text {
                "(" | "[" | "{" => depth += 1,
                ")" | "]" | "}" => depth = depth.saturating_sub(1),
                ";" if depth == 0 => {
                    statement_end = index;
                    break;
                }
                _ => {}
            }
        }
        if statement_end == cursor {
            cursor += 1;
            continue;
        }
        let mut parser = ExpressionParser::new(&tokens[cursor..statement_end]);
        let expression = parser.parse_complete()?;
        let rendered = source[tokens[cursor].start..tokens[statement_end - 1].end].to_string();
        expressions.push(if matches!(expression, Expression::Sequence(_)) {
            format!("({rendered})")
        } else {
            rendered
        });
        cursor = statement_end + usize::from(statement_end < end);
    }
    match expressions.len() {
        0 => None,
        1 => expressions.pop(),
        _ => Some(format!("({})", expressions.join(","))),
    }
}

fn single_console_log_argument(expression: &str) -> Option<&str> {
    const PREFIX: &str = "console.log(";
    if !expression.starts_with(PREFIX) || !expression.ends_with(')') {
        return None;
    }
    let inner = &expression[PREFIX.len()..expression.len() - 1];
    if inner.is_empty() {
        return None;
    }
    let mut depth = 0i32;
    for ch in inner.chars() {
        match ch {
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => depth -= 1,
            ',' if depth == 0 => return None,
            _ => {}
        }
        if depth < 0 {
            return None;
        }
    }
    (depth == 0).then_some(inner)
}

fn matching_closers(tokens: &[Token<'_>]) -> Vec<Option<usize>> {
    let mut matching_close = vec![None; tokens.len()];
    let mut stack = Vec::<usize>::new();
    for (index, token) in tokens.iter().enumerate() {
        match token.text {
            "(" | "[" | "{" => stack.push(index),
            ")" | "]" | "}" => {
                let Some(open) = stack.pop() else {
                    continue;
                };
                matching_close[open] = Some(index);
            }
            _ => {}
        }
    }
    matching_close
}

/// Replace `!(left == right)` with `left != right` (and the strict/inverse
/// forms) without changing operand evaluation. JavaScript defines both
/// inequality operators as the logical inverse of their matching equality
/// operation, so coercion, side effects, exceptions, and left-to-right order
/// are identical. The surrounding candidate without this spelling remains in
/// the compiler's exact-codec frontier.
fn fold_negated_equalities(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let Some(tokens) = lex_certainly(source)? else {
        return Ok((source.to_string(), 0));
    };
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut index = 0usize;

    while index + 3 < tokens.len() {
        if tokens[index].text != "!" || tokens[index + 1].text != "(" {
            index += 1;
            continue;
        }
        let open = index + 1;
        let Some(close) = matching_close[open] else {
            index += 1;
            continue;
        };
        if close <= open + 2 {
            index += 1;
            continue;
        }
        if parenthesized_expression_has_postfix_continuation(&tokens, close)
            || tokens
                .get(index.wrapping_sub(1))
                .is_some_and(|token| token.text == "new")
            || matches!(tokens[open + 1].text, "{" | "function" | "class" | "async")
        {
            index += 1;
            continue;
        }
        // The compact lexer deliberately does not distinguish division from
        // regular-expression literals. A regex body may itself contain an
        // equality token, so refuse the whole local rewrite rather than risk
        // selecting an operator from inside `/.../`.
        if tokens[open + 1..close]
            .iter()
            .any(|token| matches!(token.text, "/" | "/="))
        {
            index += 1;
            continue;
        }
        let Some((operator_index, inverse)) = root_equality_inverse(&tokens[open + 1..close])
        else {
            index += 1;
            continue;
        };
        let operator_index = open + 1 + operator_index;
        let inner_start = tokens[open + 1].start;
        let inner_end = tokens[close - 1].end;
        let mut inverse_expression = String::with_capacity(inner_end - inner_start);
        inverse_expression.push_str(&source[inner_start..tokens[operator_index].start]);
        inverse_expression.push_str(inverse);
        inverse_expression.push_str(&source[tokens[operator_index].end..inner_end]);
        if equality_replacement_requires_grouping(&tokens, index, close) {
            inverse_expression = format!("({inverse_expression})");
        }
        replacements.push((tokens[index].start, tokens[close].end, inverse_expression));
        index = close + 1;
    }

    if replacements.is_empty() {
        return Ok((source.to_string(), 0));
    }
    let count = replacements.len();
    let mut output = source.to_string();
    for (start, end, replacement) in replacements.into_iter().rev() {
        output.replace_range(start..end, &replacement);
    }
    Ok((output, count))
}

/// Find the root equality operator of a parenthesized expression. Operators
/// with lower precedence prove that equality is only a child, while equal
/// precedence is left-associative and therefore makes the last equality token
/// the root.
fn root_equality_inverse(tokens: &[Token<'_>]) -> Option<(usize, &'static str)> {
    let mut depth = 0usize;
    let mut root = None;
    for (index, token) in tokens.iter().enumerate() {
        match token.text {
            "(" | "[" | "{" => {
                depth += 1;
                continue;
            }
            ")" | "]" | "}" => {
                depth = depth.checked_sub(1)?;
                continue;
            }
            _ if depth != 0 => continue,
            _ => {}
        }

        let inverse = match token.text {
            "==" => Some("!="),
            "!=" => Some("=="),
            "===" => Some("!=="),
            "!==" => Some("==="),
            _ => None,
        };
        if let Some(inverse) = inverse {
            root = Some((index, inverse));
            continue;
        }
        if matches!(token.text, "?" | ":" | "=>" | "yield")
            || infix_precedence(token.text).is_some_and(|(precedence, _, _)| precedence < 10)
        {
            return None;
        }
    }
    (depth == 0).then_some(root).flatten()
}

fn parenthesized_expression_has_postfix_continuation(tokens: &[Token<'_>], close: usize) -> bool {
    tokens.get(close + 1).is_some_and(|token| {
        matches!(token.text, "(" | "[" | "." | "++" | "--" | "**")
            || token.kind == TokenKind::Template
            || (token.text == "?" && tokens.get(close + 2).is_some_and(|token| token.text == "."))
    })
}

fn equality_replacement_requires_grouping(tokens: &[Token<'_>], bang: usize, close: usize) -> bool {
    let tighter_or_equal = |token: &Token<'_>| {
        infix_precedence(token.text).is_some_and(|(precedence, _, _)| precedence >= 10)
    };
    let prefix_parent = tokens.get(bang.wrapping_sub(1)).is_some_and(|token| {
        matches!(
            token.text,
            "!" | "~" | "+" | "-" | "." | "typeof" | "void" | "delete" | "await" | "new"
        ) || tighter_or_equal(token)
    });
    let postfix_parent = tokens
        .get(close + 1)
        .is_some_and(|token| tighter_or_equal(token));
    prefix_parent || postfix_parent
}

/// Returns a codec candidate that spells function-body-leading generated
/// declarations with `let` instead of `var`.
///
/// LilScript's IR emitter places a function's local declaration before every
/// executable body operation, assigns every emitted local name uniquely, and
/// cannot emit direct `eval` or `with`. Within that generated subset, the
/// leading function block and the function's `var` scope are equivalent when
/// the declaration has no initializer or only literal initializers. The
/// spellings can still interact quite differently with a surrounding gzip or
/// Brotli dictionary, so the compiler scores both complete programs.
///
/// This is intentionally a lexical, additive variant rather than a peephole
/// rewrite. Strings, templates, and comments are never inspected, parameter
/// lists must use the emitter's simple identifier form, declarations with a
/// hoisting-sensitive initializer or later `var` are rejected, and callers
/// always retain the original source as a candidate.
pub(crate) fn function_leading_declaration_variant(source: &str) -> Option<String> {
    let tokens = lex(source).ok()?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize)>::new();

    for (function_index, token) in tokens.iter().enumerate() {
        if token.text != "function" {
            continue;
        }

        let mut cursor = function_index + 1;
        if tokens.get(cursor).map(|token| token.text) == Some("*") {
            cursor += 1;
        }
        if tokens.get(cursor).map(|token| token.kind) == Some(TokenKind::Identifier) {
            cursor += 1;
        }
        if tokens.get(cursor).map(|token| token.text) != Some("(") {
            continue;
        }
        let parameters_open = cursor;
        let Some(parameters_close) = matching_close[parameters_open] else {
            continue;
        };
        let simple_parameters = tokens[parameters_open + 1..parameters_close]
            .iter()
            .enumerate()
            .all(|(index, token)| {
                if index % 2 == 0 {
                    token.kind == TokenKind::Identifier
                } else {
                    token.text == ","
                }
            });
        if !simple_parameters {
            continue;
        }

        let body_open = parameters_close + 1;
        if tokens.get(body_open).map(|token| token.text) != Some("{") {
            continue;
        }
        let Some(body_close) = matching_close[body_open] else {
            continue;
        };
        let declaration_index = body_open + 1;
        if declaration_index >= body_close || tokens[declaration_index].text != "var" {
            continue;
        }

        let mut declaration_cursor = declaration_index + 1;
        let mut declared_names = Vec::<&str>::new();
        let mut declaration_end = None;
        while declaration_cursor < body_close {
            let Some(name) = tokens.get(declaration_cursor) else {
                break;
            };
            if name.kind != TokenKind::Identifier
                || declared_names.contains(&name.text)
                || tokens[parameters_open + 1..parameters_close]
                    .iter()
                    .any(|parameter| parameter.text == name.text)
            {
                break;
            }
            declared_names.push(name.text);
            declaration_cursor += 1;

            if tokens.get(declaration_cursor).map(|token| token.text) == Some("=") {
                declaration_cursor += 1;
                let initializer_start = declaration_cursor;
                while declaration_cursor < body_close
                    && !matches!(tokens[declaration_cursor].text, "," | ";")
                {
                    declaration_cursor += 1;
                }
                if !is_hoist_independent_literal_initializer(
                    &tokens[initializer_start..declaration_cursor],
                ) {
                    break;
                }
            }

            match tokens.get(declaration_cursor).map(|token| token.text) {
                Some(",") => declaration_cursor += 1,
                Some(";") => {
                    declaration_end = Some(declaration_cursor);
                    break;
                }
                _ => break,
            }
        }
        let Some(declaration_end) = declaration_end else {
            continue;
        };
        if tokens[declaration_end + 1..body_close]
            .iter()
            .any(|token| token.text == "var")
        {
            continue;
        }
        // A following function/class declaration can legally merge with a
        // `var` binding but conflicts with the lexical candidate. Generated
        // code normally has neither here; rejecting the whole uncommon shape
        // keeps the proof independent of declaration-instantiation rules.
        if tokens[declaration_end + 1..body_close]
            .iter()
            .any(|token| matches!(token.text, "function" | "class"))
        {
            continue;
        }

        let replacement = (
            tokens[declaration_index].start,
            tokens[declaration_index].end,
        );
        if !replacements.contains(&replacement) {
            replacements.push(replacement);
        }
    }

    if replacements.is_empty() {
        return None;
    }
    let mut variant = source.to_string();
    for (start, end) in replacements.into_iter().rev() {
        variant.replace_range(start..end, "let");
    }
    Some(variant)
}

fn is_hoist_independent_literal_initializer(tokens: &[Token<'_>]) -> bool {
    match tokens {
        [literal]
            if matches!(literal.kind, TokenKind::Number | TokenKind::String)
                || matches!(literal.text, "true" | "false" | "null") =>
        {
            true
        }
        [operator, literal]
            if matches!(operator.text, "+" | "-") && literal.kind == TokenKind::Number =>
        {
            true
        }
        _ => false,
    }
}

fn is_console_log_open(tokens: &[Token<'_>], index: usize) -> bool {
    tokens.get(index).map(|token| token.text) == Some("console")
        && tokens.get(index + 1).map(|token| token.text) == Some(".")
        && tokens.get(index + 2).map(|token| token.text) == Some("log")
        && tokens.get(index + 3).map(|token| token.text) == Some("(")
}

fn fold_console_log_conditionals(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut index = 0usize;
    while index + 8 < tokens.len() {
        if tokens[index].text != "?" || !is_console_log_open(&tokens, index + 1) {
            index += 1;
            continue;
        }
        let then_open = index + 4;
        let Some(then_close) = matching_close[then_open] else {
            index += 1;
            continue;
        };
        if tokens.get(then_close + 1).map(|token| token.text) != Some(":")
            || !is_console_log_open(&tokens, then_close + 2)
        {
            index += 1;
            continue;
        }
        let else_open = then_close + 5;
        let Some(else_close) = matching_close[else_open] else {
            index += 1;
            continue;
        };
        let next = tokens.get(else_close + 1).map(|token| token.text);
        if next.is_some_and(|token| !matches!(token, ";" | "}" | "{")) {
            index += 1;
            continue;
        }
        let then_arg = source[tokens[then_open].end..tokens[then_close].start].to_string();
        let else_arg = source[tokens[else_open].end..tokens[else_close].start].to_string();
        if single_console_log_argument(&format!("console.log({then_arg})")).is_none()
            || single_console_log_argument(&format!("console.log({else_arg})")).is_none()
        {
            index += 1;
            continue;
        }
        let mut cond_start = 0usize;
        let mut depth = 0i32;
        let mut statement = true;
        for token_index in (0..index).rev() {
            match tokens[token_index].text {
                ")" | "]" | "}" => depth += 1,
                "(" | "[" | "{" => {
                    if depth == 0 {
                        if tokens[token_index].text != "{" {
                            statement = false;
                        }
                        cond_start = token_index + 1;
                        break;
                    }
                    depth -= 1;
                }
                ";" if depth == 0 => {
                    cond_start = token_index + 1;
                    break;
                }
                "," | ":" | "?" if depth == 0 => {
                    statement = false;
                    break;
                }
                _ => {}
            }
        }
        if !statement {
            index += 1;
            continue;
        }
        let condition = source[tokens[cond_start].start..tokens[index].start].trim();
        if condition.is_empty() {
            index += 1;
            continue;
        }
        let mut end = tokens[else_close].end;
        if tokens.get(else_close + 1).map(|token| token.text) == Some(";") {
            end = tokens[else_close + 1].end;
        }
        let replacement = format!("console.log({condition}?{then_arg}:{else_arg});");
        if replacement.len() < end - tokens[cond_start].start {
            replacements.push((tokens[cond_start].start, end, replacement));
        }
        index = else_close + 1;
    }
    if replacements.is_empty() {
        return Ok((source.to_string(), 0));
    }
    replacements.sort_unstable_by_key(|(start, end, _)| (*start, *end));
    let mut retained = Vec::new();
    let mut last_end = 0;
    for replacement in replacements {
        if replacement.0 >= last_end {
            last_end = replacement.1;
            retained.push(replacement);
        }
    }
    let count = retained.len();
    let mut output = source.to_string();
    for (start, end, replacement) in retained.into_iter().rev() {
        output.replace_range(start..end, &replacement);
    }
    Ok((output, count))
}

/// Fold `value=expression;if(value){...}` into
/// `if(value=expression){...}`. The assignment result already undergoes the
/// same JavaScript truthiness conversion in both forms, and the binding keeps
/// the same value on both the taken and untaken paths.
fn fold_assignment_guards(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let is_statement_start =
        |index: usize| index == 0 || matches!(tokens[index - 1].text, "{" | "}" | ";");
    let mut start = 0usize;
    while start + 6 < tokens.len() {
        if tokens[start].kind != TokenKind::Identifier
            || tokens[start + 1].text != "="
            || !is_statement_start(start)
        {
            start += 1;
            continue;
        }
        let name = tokens[start].text;
        let mut depth = 0i32;
        let mut semicolon = None;
        for (index, token) in tokens.iter().enumerate().skip(start + 2) {
            match token.text {
                "(" | "[" | "{" => depth += 1,
                ")" | "]" | "}" => depth -= 1,
                ";" if depth == 0 => {
                    semicolon = Some(index);
                    break;
                }
                _ => {}
            }
            if depth < 0 {
                break;
            }
        }
        let Some(semi) = semicolon else {
            start += 1;
            continue;
        };
        if tokens.get(semi + 1).map(|token| token.text) != Some("if")
            || tokens.get(semi + 2).map(|token| token.text) != Some("(")
            || tokens.get(semi + 3).map(|token| (token.kind, token.text))
                != Some((TokenKind::Identifier, name))
            || tokens.get(semi + 4).map(|token| token.text) != Some(")")
        {
            start += 1;
            continue;
        }
        replacements.push((
            tokens[start].start,
            tokens[semi + 4].end,
            format!("if({})", &source[tokens[start].start..tokens[semi].start]),
        ));
        start = semi + 5;
    }
    if replacements.is_empty() {
        return Ok((source.to_string(), 0));
    }
    let count = replacements.len();
    let mut output = source.to_string();
    // Reverse order keeps all earlier source offsets stable.
    for (start, end, replacement) in replacements.into_iter().rev() {
        output.replace_range(start..end, &replacement);
    }
    Ok((output, count))
}

fn paren_depth_at(tokens: &[Token<'_>]) -> Vec<i32> {
    let mut depths = vec![0; tokens.len()];
    let mut depth = 0i32;
    for (index, token) in tokens.iter().enumerate() {
        depths[index] = depth;
        match token.text {
            "(" => depth += 1,
            ")" => depth -= 1,
            _ => {}
        }
    }
    depths
}

fn identifier_occurs(tokens: &[Token<'_>], start: usize, end: usize, name: &str) -> bool {
    if start >= end || end > tokens.len() {
        return false;
    }
    tokens[start..end]
        .iter()
        .any(|token| token.kind == TokenKind::Identifier && token.text == name)
}

fn top_level_stop(tokens: &[Token<'_>], start: usize, stops: &[&str]) -> Option<usize> {
    let mut depth = 0i32;
    for (index, token) in tokens.iter().enumerate().skip(start) {
        if depth == 0 && stops.contains(&token.text) {
            return Some(index);
        }
        match token.text {
            "(" | "[" | "{" => depth += 1,
            ")" | "]" | "}" => {
                depth -= 1;
                if depth < 0 {
                    return None;
                }
            }
            _ => {}
        }
    }
    None
}

fn apply_token_rewrites(
    source: &str,
    mut replacements: Vec<(usize, usize, String)>,
) -> (String, usize) {
    if replacements.is_empty() {
        return (source.to_string(), 0);
    }
    replacements.sort_unstable_by_key(|(start, end, _)| (*start, *end));
    let mut retained = Vec::new();
    let mut last_end = 0;
    for replacement in replacements {
        if replacement.0 >= last_end {
            last_end = replacement.1;
            retained.push(replacement);
        }
    }
    let count = retained.len();
    let mut output = source.to_string();
    for (start, end, replacement) in retained.into_iter().rev() {
        output.replace_range(start..end, &replacement);
    }
    (output, count)
}

fn fold_index_postfix_updates(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let depths = paren_depth_at(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 6 < tokens.len() {
        if depths[cursor] != 0 || tokens[cursor].kind != TokenKind::Identifier {
            cursor += 1;
            continue;
        }
        if tokens.get(cursor + 1).map(|token| token.text) == Some("[")
            && tokens.get(cursor + 2).is_some_and(|token| token.kind == TokenKind::Identifier)
            && tokens.get(cursor + 3).map(|token| token.text) == Some("]")
            && tokens.get(cursor + 4).map(|token| token.text) == Some("=")
        {
            let index = tokens[cursor + 2].text;
            let Some(stop) = top_level_stop(&tokens, cursor + 5, &[",", ";"]) else {
                cursor += 1;
                continue;
            };
            if identifier_occurs(&tokens, cursor + 5, stop, index) {
                cursor += 1;
                continue;
            }
            if tokens.get(stop + 1).map(|token| token.text) == Some(index)
                && tokens.get(stop + 2).map(|token| token.text) == Some("++")
            {
                let rhs = &source[tokens[cursor + 5].start..tokens[stop].start];
                let end = tokens[stop + 2].end;
                replacements.push((
                    tokens[cursor].start,
                    end,
                    format!("{}[{index}++]={rhs}", tokens[cursor].text),
                ));
                cursor = stop + 3;
                continue;
            }
        }
        if tokens.get(cursor + 1).map(|token| token.text) == Some("=")
            && tokens.get(cursor + 2).is_some_and(|token| {
                token.kind == TokenKind::Identifier || token.kind == TokenKind::Number
            })
            && tokens.get(cursor + 3).map(|token| token.text) == Some("+")
            && tokens.get(cursor + 4).map(|token| token.text) == Some("1")
            && tokens.get(cursor + 5).map(|token| token.text) == Some(";")
            && tokens.get(cursor + 2).map(|token| token.text)
                != Some(tokens[cursor].text)
        {
            let temp = tokens[cursor].text;
            let index = tokens[cursor + 2].text;
            if tokens.get(cursor + 6).is_some_and(|token| token.kind == TokenKind::Identifier)
                && tokens.get(cursor + 7).map(|token| token.text) == Some("[")
                && tokens.get(cursor + 8).map(|token| token.text) == Some(index)
                && tokens.get(cursor + 9).map(|token| token.text) == Some("]")
                && tokens.get(cursor + 10).map(|token| token.text) == Some("=")
            {
                if let Some(stop) = top_level_stop(&tokens, cursor + 11, &[";"]) {
                    if !identifier_occurs(&tokens, cursor + 11, stop, index)
                        && !identifier_occurs(&tokens, cursor + 11, stop, temp)
                    {
                        let mut restore = stop + 1;
                        if tokens.get(restore).is_some_and(|token| token.kind == TokenKind::Identifier)
                            && tokens.get(restore).map(|token| token.text) != Some(index)
                            && tokens.get(restore).map(|token| token.text) != Some(temp)
                            && matches!(
                                tokens.get(restore + 1).map(|token| token.text),
                                Some("++") | Some("+=")
                            )
                        {
                            restore = if tokens.get(restore + 1).map(|token| token.text) == Some("++")
                            {
                                restore + 3
                            } else if tokens.get(restore + 2).map(|token| token.text) == Some("1")
                                && tokens.get(restore + 3).map(|token| token.text) == Some(";")
                            {
                                restore + 4
                            } else {
                                restore
                            };
                        }
                        if tokens.get(restore).map(|token| token.text) == Some(index)
                            && tokens.get(restore + 1).map(|token| token.text) == Some("=")
                            && tokens.get(restore + 2).map(|token| token.text) == Some(temp)
                        {
                            let object = tokens[cursor + 6].text;
                            let rhs = &source[tokens[cursor + 11].start..tokens[stop].start];
                            let between = if restore > stop + 1 {
                                &source[tokens[stop + 1].start..tokens[restore].start]
                            } else {
                                ""
                            };
                            replacements.push((
                                tokens[cursor].start,
                                tokens[restore + 2].end,
                                format!("{object}[{index}++]={rhs};{between}"),
                            ));
                            cursor = restore + 3;
                            continue;
                        }
                    }
                }
            }
        }
        if tokens.get(cursor + 1).map(|token| token.text) == Some("=")
            && tokens.get(cursor + 2).is_some_and(|token| token.kind == TokenKind::Identifier)
            && tokens.get(cursor + 3).map(|token| token.text) == Some("[")
            && tokens.get(cursor + 4).is_some_and(|token| token.kind == TokenKind::Identifier)
            && tokens.get(cursor + 5).map(|token| token.text) == Some("]")
        {
            let index = tokens[cursor + 4].text;
            let Some(stop) = top_level_stop(&tokens, cursor + 6, &[",", ";"]) else {
                cursor += 1;
                continue;
            };
            if stop != cursor + 6 {
                cursor += 1;
                continue;
            }
            if tokens.get(stop + 1).map(|token| token.text) == Some(index)
                && tokens.get(stop + 2).map(|token| token.text) == Some("++")
            {
                let end = tokens[stop + 2].end;
                replacements.push((
                    tokens[cursor].start,
                    end,
                    format!(
                        "{}={}[{index}++]",
                        tokens[cursor].text, tokens[cursor + 2].text
                    ),
                ));
                cursor = stop + 3;
                continue;
            }
        }
        cursor += 1;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_conditional_singleton_arrays(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 12 < tokens.len() {
        let binding_start = cursor;
        let name_index = if matches!(tokens[cursor].text, "var" | "let" | "const") {
            cursor + 1
        } else {
            cursor
        };
        if tokens.get(name_index).is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(name_index + 1).map(|token| token.text) != Some("=")
            || tokens.get(name_index + 2).map(|token| token.text) != Some("[")
            || tokens.get(name_index + 3).map(|token| token.text) != Some("]")
            || tokens.get(name_index + 4).map(|token| token.text) != Some(";")
        {
            cursor += 1;
            continue;
        }
        let name = tokens[name_index].text;
        let comma_declarator = name_index
            .checked_sub(1)
            .is_some_and(|index| tokens[index].text == ",");
        let cond_start = name_index + 5;
        let Some(and) = tokens
            .iter()
            .enumerate()
            .skip(cond_start)
            .find_map(|(index, token)| {
                (token.text == "&&"
                    && tokens.get(index + 1).map(|next| next.text) == Some(name)
                    && tokens.get(index + 2).map(|next| next.text) == Some(".")
                    && tokens.get(index + 3).map(|next| next.text) == Some("push")
                    && tokens.get(index + 4).map(|next| next.text) == Some("("))
                .then_some(index)
            })
        else {
            cursor += 1;
            continue;
        };
        if identifier_occurs(&tokens, cond_start, and, name)
            || tokens[cond_start..and]
                .iter()
                .any(|token| matches!(token.text, ";" | "{" | "}"))
        {
            cursor += 1;
            continue;
        }
        let Some(push_close) = matching_close.get(and + 4).copied().flatten() else {
            cursor += 1;
            continue;
        };
        if tokens.get(push_close + 1).map(|token| token.text) != Some(";")
            || tokens.get(push_close + 2).map(|token| token.text) != Some("return")
        {
            cursor += 1;
            continue;
        }
        let elem = &source[tokens[and + 5].start..tokens[push_close].start];
        if identifier_occurs(&tokens, and + 5, push_close, name) || elem.is_empty() {
            cursor += 1;
            continue;
        }
        let cond = &source[tokens[cond_start].start..tokens[and].start];
        let return_at = push_close + 2;
        let replace_from = if comma_declarator {
            tokens[name_index - 1].start
        } else {
            tokens[binding_start].start
        };
        let prefix = if comma_declarator { ";" } else { "" };
        let replacement = if tokens.get(return_at + 1).map(|token| token.text) == Some(name)
            && matches!(
                tokens.get(return_at + 2).map(|token| token.text),
                Some(";") | Some("}") | None
            )
        {
            let end = tokens
                .get(return_at + 2)
                .filter(|token| token.text == ";")
                .map(|token| token.end)
                .unwrap_or(tokens[return_at + 1].end);
            (
                replace_from,
                end,
                format!("{prefix}return {cond}?[{elem}]:[]"),
            )
        } else if tokens.get(return_at + 1).is_some_and(|token| {
            token.kind == TokenKind::Identifier || token.text == "this"
        }) && tokens.get(return_at + 2).map(|token| token.text) == Some(".")
            && tokens
                .get(return_at + 3)
                .is_some_and(|token| token.kind == TokenKind::Identifier)
            && tokens.get(return_at + 4).map(|token| token.text) == Some("(")
            && tokens.get(return_at + 5).map(|token| token.text) == Some(name)
            && tokens.get(return_at + 6).map(|token| token.text) == Some(")")
        {
            let end = tokens
                .get(return_at + 7)
                .filter(|token| token.text == ";")
                .map(|token| token.end)
                .unwrap_or(tokens[return_at + 6].end);
            let callee = &source[tokens[return_at + 1].start..tokens[return_at + 4].start];
            (
                replace_from,
                end,
                format!("{prefix}return {callee}({cond}?[{elem}]:[])"),
            )
        } else {
            cursor += 1;
            continue;
        };
        replacements.push(replacement);
        cursor = push_close + 3;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_guarded_and_addends(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 12 < tokens.len() {
        if tokens[cursor].text == "!"
            && tokens
                .get(cursor + 1)
                .is_some_and(|token| token.kind == TokenKind::Identifier)
            && tokens.get(cursor + 2).map(|token| token.text) == Some("||")
            && tokens.get(cursor + 3).map(|token| token.text) == Some("(")
            && tokens.get(cursor + 4).map(|token| token.text) == Some(tokens[cursor + 1].text)
            && tokens.get(cursor + 5).map(|token| token.text) == Some("=")
        {
            let name = tokens[cursor + 1].text;
            if let Some(assign_close) = top_level_stop(&tokens, cursor + 6, &[")"]) {
                if tokens.get(assign_close + 1).map(|token| token.text) == Some(";")
                    && tokens
                        .get(assign_close + 2)
                        .is_some_and(|token| token.kind == TokenKind::Identifier)
                    && tokens.get(assign_close + 3).map(|token| token.text) == Some(".")
                    && tokens
                        .get(assign_close + 4)
                        .is_some_and(|token| token.kind == TokenKind::Identifier)
                    && tokens.get(assign_close + 5).map(|token| token.text) == Some("=")
                    && tokens.get(assign_close + 6).map(|token| token.text) == Some(name)
                {
                    let value = &source[tokens[cursor + 6].start..tokens[assign_close].start];
                    replacements.push((
                        tokens[cursor].start,
                        tokens[assign_close + 6].end,
                        format!(
                            "{}.{}={name}&&{value}",
                            tokens[assign_close + 2].text, tokens[assign_close + 4].text
                        ),
                    ));
                    cursor = assign_close + 7;
                    continue;
                }
            }
        }
        let name_index = if matches!(tokens[cursor].text, "var" | "let") {
            cursor + 1
        } else {
            cursor
        };
        if tokens.get(name_index).is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(name_index + 1).map(|token| token.text) != Some("=")
        {
            cursor += 1;
            continue;
        }
        let name = tokens[name_index].text;
        let Some(first_semi) = top_level_stop(&tokens, name_index + 2, &[";"]) else {
            cursor += 1;
            continue;
        };
        if tokens.get(first_semi + 1).map(|token| token.text) != Some("!")
            || tokens.get(first_semi + 2).map(|token| token.text) != Some(name)
            || tokens.get(first_semi + 3).map(|token| token.text) != Some("||")
            || tokens.get(first_semi + 4).map(|token| token.text) != Some("(")
            || tokens.get(first_semi + 5).map(|token| token.text) != Some(name)
            || tokens.get(first_semi + 6).map(|token| token.text) != Some("=")
        {
            cursor += 1;
            continue;
        }
        let Some(assign_close) = top_level_stop(&tokens, first_semi + 7, &[")"]) else {
            cursor += 1;
            continue;
        };
        if tokens.get(assign_close + 1).map(|token| token.text) != Some(";") {
            cursor += 1;
            continue;
        }
        let target_at = assign_close + 2;
        let Some(target) = tokens
            .get(target_at)
            .filter(|token| token.kind == TokenKind::Identifier)
            .map(|token| token.text)
        else {
            cursor += 1;
            continue;
        };
        if target == name {
            cursor += 1;
            continue;
        }
        let cond = &source[tokens[name_index + 2].start..tokens[first_semi].start];
        let value = &source[tokens[first_semi + 7].start..tokens[assign_close].start];
        if identifier_occurs(&tokens, name_index + 2, first_semi, name)
            || identifier_occurs(&tokens, first_semi + 7, assign_close, name)
        {
            cursor += 1;
            continue;
        }
        let comma_declarator = name_index
            .checked_sub(1)
            .is_some_and(|index| tokens[index].text == ",");
        let replace_from = if comma_declarator {
            tokens[name_index - 1].start
        } else {
            tokens[cursor].start
        };
        let prefix = if comma_declarator { ";" } else { "" };
        let replacement = if tokens.get(target_at + 1).map(|token| token.text) == Some("+=")
            && tokens.get(target_at + 2).map(|token| token.text) == Some(name)
        {
            Some((
                replace_from,
                tokens[target_at + 2].end,
                format!("{prefix}{target}+={cond}&&{value}"),
            ))
        } else if tokens.get(target_at + 1).map(|token| token.text) == Some(".")
            && tokens
                .get(target_at + 2)
                .is_some_and(|token| token.kind == TokenKind::Identifier)
            && tokens.get(target_at + 3).map(|token| token.text) == Some("=")
            && tokens.get(target_at + 4).map(|token| token.text) == Some(name)
        {
            Some((
                replace_from,
                tokens[target_at + 4].end,
                format!(
                    "{prefix}{target}.{}={cond}&&{value}",
                    tokens[target_at + 2].text
                ),
            ))
        } else if tokens.get(target_at + 1).map(|token| token.text) == Some("=")
            && tokens.get(target_at + 2).map(|token| token.text) == Some(target)
            && tokens.get(target_at + 3).map(|token| token.text) == Some("+")
            && tokens.get(target_at + 4).map(|token| token.text) == Some(name)
        {
            Some((
                replace_from,
                tokens[target_at + 4].end,
                format!("{prefix}{target}={target}+({cond}&&{value})"),
            ))
        } else {
            None
        };
        let Some(replacement) = replacement else {
            cursor += 1;
            continue;
        };
        replacements.push(replacement);
        cursor = target_at + 3;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_unit_counter_updates(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 3 < tokens.len() {
        let statement_update = tokens[cursor].kind == TokenKind::Identifier
            && matches!(
                cursor
                    .checked_sub(1)
                    .map(|index| tokens[index].text)
                    .unwrap_or(";"),
                ";" | "{" | "}" | ")" | ","
            )
            && matches!(
                tokens.get(cursor + 3).map(|token| token.text),
                Some(";") | Some("}") | Some(")") | Some(",") | None
            );
        if statement_update
            && tokens.get(cursor + 1).map(|token| token.text) == Some("+=")
            && tokens.get(cursor + 2).map(|token| token.text) == Some("1")
        {
            replacements.push((
                tokens[cursor].start,
                tokens[cursor + 2].end,
                format!("{}++", tokens[cursor].text),
            ));
            cursor += 3;
            continue;
        }
        if statement_update
            && tokens.get(cursor + 1).map(|token| token.text) == Some("-=")
            && tokens.get(cursor + 2).map(|token| token.text) == Some("1")
        {
            replacements.push((
                tokens[cursor].start,
                tokens[cursor + 2].end,
                format!("{}--", tokens[cursor].text),
            ));
            cursor += 3;
            continue;
        }
        let self_update = tokens[cursor].kind == TokenKind::Identifier
            && matches!(
                cursor
                    .checked_sub(1)
                    .map(|index| tokens[index].text)
                    .unwrap_or(";"),
                ";" | "{" | "}" | ")" | ","
            )
            && tokens.get(cursor + 1).map(|token| token.text) == Some("=")
            && tokens.get(cursor + 2).map(|token| token.text) == Some(tokens[cursor].text)
            && matches!(tokens.get(cursor + 3).map(|token| token.text), Some("+") | Some("-"))
            && tokens.get(cursor + 4).map(|token| token.text) == Some("1")
            && matches!(
                tokens.get(cursor + 5).map(|token| token.text),
                Some(";") | Some("}") | Some(")") | Some(",") | None
            );
        if self_update {
            let op = if tokens[cursor + 3].text == "+" { "++" } else { "--" };
            replacements.push((
                tokens[cursor].start,
                tokens[cursor + 4].end,
                format!("{}{op}", tokens[cursor].text),
            ));
            cursor += 5;
            continue;
        }
        cursor += 1;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_identifier_copies(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 3 < tokens.len() {
        if tokens[cursor].kind != TokenKind::Identifier
            || tokens.get(cursor + 1).map(|token| token.text) != Some("=")
            || tokens
                .get(cursor + 2)
                .is_none_or(|token| token.kind != TokenKind::Identifier)
            || !matches!(
                cursor
                    .checked_sub(1)
                    .map(|index| tokens[index].text)
                    .unwrap_or(";"),
                ";" | "{" | "}" | "let" | "var" | "const" | ","
            )
        {
            cursor += 1;
            continue;
        }
        let name = tokens[cursor].text;
        let (rhs, rhs_end) = if tokens.get(cursor + 3).map(|token| token.text) == Some(".")
            && tokens
                .get(cursor + 4)
                .is_some_and(|token| token.kind == TokenKind::Identifier)
            && matches!(
                tokens.get(cursor + 5).map(|token| token.text),
                Some(";") | Some(",") | Some("}") | None
            )
        {
            (
                source[tokens[cursor + 2].start..tokens[cursor + 4].end].to_string(),
                cursor + 4,
            )
        } else if matches!(
            tokens.get(cursor + 3).map(|token| token.text),
            Some(";") | Some(",") | Some("}") | None
        ) {
            (tokens[cursor + 2].text.to_string(), cursor + 2)
        } else {
            cursor += 1;
            continue;
        };
        if rhs == name {
            cursor += 1;
            continue;
        }
        let scope_end = enclosing_block_end(&matching_close, cursor).unwrap_or(tokens.len());
        let mut reads = Vec::new();
        let mut scan = rhs_end + 1;
        if tokens.get(scan).map(|token| token.text) == Some(";")
            || tokens.get(scan).map(|token| token.text) == Some(",")
        {
            scan += 1;
        }
        while scan < scope_end {
            if let Some(close) = nested_function_end(&tokens, &matching_close, scan) {
                scan = close + 1;
                continue;
            }
            if tokens[scan].kind == TokenKind::Identifier && tokens[scan].text == name {
                if tokens.get(scan + 1).map(|token| token.text) == Some("=")
                    && tokens.get(scan + 2).map(|token| token.text) != Some("=")
                {
                    break;
                }
                if matches!(
                    tokens.get(scan + 1).map(|token| token.text),
                    Some("++") | Some("--")
                ) || matches!(
                    tokens.get(scan.wrapping_sub(1)).map(|token| token.text),
                    Some("++") | Some("--") | Some("[")
                ) {
                    break;
                }
                reads.push(scan);
            }
            if rhs_end == cursor + 2
                && tokens[scan].kind == TokenKind::Identifier
                && tokens[scan].text == tokens[cursor + 2].text
                && tokens.get(scan + 1).map(|token| token.text) == Some("=")
                && tokens.get(scan + 2).map(|token| token.text) != Some("=")
            {
                break;
            }
            scan += 1;
        }
        if reads.is_empty() {
            cursor += 1;
            continue;
        }
        if rhs_end != cursor + 2 && reads.len() != 1 {
            cursor += 1;
            continue;
        }
        let prev = cursor
            .checked_sub(1)
            .map(|index| tokens[index].text)
            .unwrap_or(";");
        if matches!(prev, "let" | "var" | "const" | ",") {
            for read in reads {
                replacements.push((tokens[read].start, tokens[read].end, rhs.clone()));
            }
        } else {
            let (from, to) = assignment_span_to_remove(&tokens, cursor, rhs_end);
            replacements.push((from, to, String::new()));
            for read in reads {
                replacements.push((tokens[read].start, tokens[read].end, rhs.clone()));
            }
        }
        cursor = rhs_end + 1;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count / 2 + count % 2))
}

fn nested_function_end(
    tokens: &[Token<'_>],
    matching_close: &[Option<usize>],
    scan: usize,
) -> Option<usize> {
    if tokens[scan].text == "function" {
        let mut index = scan + 1;
        if tokens
            .get(index)
            .is_some_and(|token| token.kind == TokenKind::Identifier)
        {
            index += 1;
        }
        if tokens.get(index).map(|token| token.text) != Some("(") {
            return None;
        }
        let close_paren = matching_close.get(index).copied().flatten()?;
        if tokens.get(close_paren + 1).map(|token| token.text) != Some("{") {
            return None;
        }
        return matching_close.get(close_paren + 1).copied().flatten();
    }
    if tokens[scan].text == "=>" && tokens.get(scan + 1).map(|token| token.text) == Some("{") {
        return matching_close.get(scan + 1).copied().flatten();
    }
    if tokens[scan].kind == TokenKind::Identifier
        && tokens.get(scan + 1).map(|token| token.text) == Some("(")
    {
        let close_paren = matching_close.get(scan + 1).copied().flatten()?;
        if tokens.get(close_paren + 1).map(|token| token.text) == Some("{") {
            return matching_close.get(close_paren + 1).copied().flatten();
        }
    }
    None
}

fn enclosing_block_end(matching_close: &[Option<usize>], at: usize) -> Option<usize> {
    matching_close
        .iter()
        .enumerate()
        .filter_map(|(open, close)| {
            let close = (*close)?;
            (open < at && at < close).then_some(close)
        })
        .min()
}

fn enclosing_block_start(matching_close: &[Option<usize>], at: usize) -> Option<usize> {
    matching_close
        .iter()
        .enumerate()
        .filter_map(|(open, close)| {
            let close = (*close)?;
            (open < at && at < close).then_some(open)
        })
        .max()
}

fn name_is_used_in_scope(
    tokens: &[Token<'_>],
    matching_close: &[Option<usize>],
    name_at: usize,
    after: usize,
    name: &str,
) -> bool {
    let scope_start = enclosing_block_start(matching_close, name_at)
        .map(|open| open + 1)
        .unwrap_or(0);
    let scope_end = enclosing_block_end(matching_close, name_at).unwrap_or(tokens.len());
    identifier_occurs(tokens, scope_start, name_at, name)
        || identifier_occurs(tokens, after, scope_end, name)
}

fn assignment_span_to_remove(tokens: &[Token<'_>], name_at: usize, rhs_end: usize) -> (usize, usize) {
    let after = rhs_end + 1;
    let prev = name_at.checked_sub(1).map(|index| tokens[index].text);
    if matches!(prev, Some("let") | Some("var") | Some("const")) {
        if tokens.get(after).map(|token| token.text) == Some(",") {
            return (tokens[name_at].start, tokens[after].end);
        }
        if tokens.get(after).map(|token| token.text) == Some(";") {
            return (tokens[name_at - 1].start, tokens[after].end);
        }
    }
    if prev == Some(",") && tokens.get(after).map(|token| token.text) == Some(",") {
        return (tokens[name_at - 1].start, tokens[after].end);
    }
    if prev == Some(",") {
        let end = if tokens.get(after).map(|token| token.text) == Some(";") {
            tokens[after].end
        } else {
            tokens[rhs_end].end
        };
        return (tokens[name_at - 1].start, end);
    }
    let end = if tokens.get(after).map(|token| token.text) == Some(";") {
        tokens[after].end
    } else {
        tokens[rhs_end].end
    };
    (tokens[name_at].start, end)
}

fn cheap_literal_end(
    tokens: &[Token<'_>],
    matching_close: &[Option<usize>],
    rhs: usize,
) -> Option<usize> {
    if tokens.get(rhs).map(|token| token.kind) == Some(TokenKind::Regex) {
        return Some(rhs);
    }
    if tokens.get(rhs).map(|token| token.text) == Some("(")
        && tokens.get(rhs + 1).map(|token| token.text) == Some(")")
        && tokens.get(rhs + 2).map(|token| token.text) == Some("=>")
        && tokens.get(rhs + 3).map(|token| token.text) == Some("{")
    {
        let close = matching_close.get(rhs + 3).copied().flatten()?;
        return (close == rhs + 4).then_some(close);
    }
    if tokens.get(rhs).map(|token| token.text) == Some("function")
        && tokens.get(rhs + 1).map(|token| token.text) == Some("(")
        && tokens.get(rhs + 2).map(|token| token.text) == Some(")")
        && tokens.get(rhs + 3).map(|token| token.text) == Some("{")
    {
        let close = matching_close.get(rhs + 3).copied().flatten()?;
        return (close == rhs + 4).then_some(close);
    }
    None
}

fn rematerialized_literal_needs_grouping(tokens: &[Token<'_>], use_at: usize, kind: TokenKind) -> bool {
    if kind == TokenKind::Regex {
        return false;
    }
    !matches!(
        use_at
            .checked_sub(1)
            .map(|index| tokens[index].text)
            .unwrap_or(";"),
        "(" | "[" | "{" | "," | ";" | ":" | "=" | "return" | "throw" | "void" | "typeof"
            | "delete" | "await" | "yield" | "!" | "~"
    )
}

fn name_use_is_mutated(tokens: &[Token<'_>], use_at: usize) -> bool {
    matches!(
        tokens.get(use_at + 1).map(|token| token.text),
        Some("=") | Some("++") | Some("--") | Some("+=") | Some("-=")
    ) && tokens.get(use_at + 2).map(|token| token.text) != Some("=")
        || matches!(
            use_at
                .checked_sub(1)
                .map(|index| tokens[index].text),
            Some("++") | Some("--") | Some("new")
        )
}

fn collect_same_scope_name_uses(
    tokens: &[Token<'_>],
    matching_close: &[Option<usize>],
    name: &str,
    start: usize,
    end: usize,
    skip: usize,
) -> (Vec<usize>, bool) {
    let mut uses = Vec::new();
    let mut nested_use = false;
    let mut scan = start;
    while scan < end {
        if scan != skip {
            if let Some(close) = nested_function_end(tokens, matching_close, scan) {
                if identifier_occurs(tokens, scan, close + 1, name) {
                    nested_use = true;
                }
                scan = close + 1;
                continue;
            }
            if tokens[scan].text == "=>" && tokens.get(scan + 1).map(|token| token.text) != Some("{")
            {
                let body_end = top_level_stop(tokens, scan + 1, &[",", ";", ")", "]", "}"])
                    .unwrap_or(end);
                if identifier_occurs(tokens, scan + 1, body_end, name) {
                    nested_use = true;
                }
                scan = body_end;
                continue;
            }
        }
        if scan != skip && tokens[scan].kind == TokenKind::Identifier && tokens[scan].text == name {
            uses.push(scan);
        }
        scan += 1;
    }
    (uses, nested_use)
}

fn fold_single_use_literal_bindings(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor < tokens.len() {
        if !matches!(tokens[cursor].text, "let" | "var" | "const") {
            cursor += 1;
            continue;
        }
        let mut name_at = cursor + 1;
        loop {
            if tokens
                .get(name_at)
                .is_none_or(|token| token.kind != TokenKind::Identifier)
                || tokens.get(name_at + 1).map(|token| token.text) != Some("=")
            {
                break;
            }
            let Some(literal_end) = cheap_literal_end(&tokens, &matching_close, name_at + 2) else {
                let Some(stop) = top_level_stop(&tokens, name_at, &[",", ";"]) else {
                    break;
                };
                if tokens[stop].text == ";" {
                    break;
                }
                name_at = stop + 1;
                continue;
            };
            if !matches!(
                tokens.get(literal_end + 1).map(|token| token.text),
                Some(",") | Some(";")
            ) {
                let Some(stop) = top_level_stop(&tokens, name_at, &[",", ";"]) else {
                    break;
                };
                if tokens[stop].text == ";" {
                    break;
                }
                name_at = stop + 1;
                continue;
            }
            let name = tokens[name_at].text;
            let stop = literal_end + 1;
            let scope_start = enclosing_block_start(&matching_close, name_at)
                .map(|open| open + 1)
                .unwrap_or(0);
            let scope_end = enclosing_block_end(&matching_close, name_at).unwrap_or(tokens.len());
            if identifier_occurs(&tokens, scope_start, name_at, name) {
                if tokens[stop].text == ";" {
                    break;
                }
                name_at = stop + 1;
                continue;
            }
            let (uses, nested_use) = collect_same_scope_name_uses(
                &tokens,
                &matching_close,
                name,
                stop + 1,
                scope_end,
                name_at,
            );
            if !nested_use
                && uses.len() == 1
                && !name_use_is_mutated(&tokens, uses[0])
            {
                let use_at = uses[0];
                let literal = &source[tokens[name_at + 2].start..tokens[literal_end].end];
                let rendered = if rematerialized_literal_needs_grouping(
                    &tokens,
                    use_at,
                    tokens[name_at + 2].kind,
                ) {
                    format!("({literal})")
                } else {
                    literal.to_string()
                };
                replacements.push((tokens[use_at].start, tokens[use_at].end, rendered));
                let (from, to) = assignment_span_to_remove(&tokens, name_at, literal_end);
                replacements.push((from, to, String::new()));
            }
            if tokens[stop].text == ";" {
                break;
            }
            name_at = stop + 1;
        }
        cursor += 1;
    }
    Ok(apply_token_rewrites(source, replacements))
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum PrototypeToStringKind {
    Object,
    Function,
}

fn prototype_tostring_call(
    tokens: &[Token<'_>],
    matching_close: &[Option<usize>],
    at: usize,
) -> Option<(PrototypeToStringKind, usize)> {
    let kind = match tokens.get(at).map(|token| token.text) {
        Some("Object") => PrototypeToStringKind::Object,
        Some("Function") => PrototypeToStringKind::Function,
        _ => return None,
    };
    if tokens.get(at + 1).map(|token| token.text) != Some(".")
        || tokens.get(at + 2).map(|token| token.text) != Some("prototype")
        || tokens.get(at + 3).map(|token| token.text) != Some(".")
        || tokens.get(at + 4).map(|token| token.text) != Some("toString")
        || tokens.get(at + 5).map(|token| token.text) != Some(".")
        || tokens.get(at + 6).map(|token| token.text) != Some("call")
        || tokens.get(at + 7).map(|token| token.text) != Some("(")
    {
        return None;
    }
    let close = matching_close.get(at + 7).copied().flatten()?;
    Some((kind, close))
}

fn collect_prototype_tostring_aliases<'src>(
    tokens: &[Token<'src>],
    matching_close: &[Option<usize>],
) -> (Option<&'src str>, Option<&'src str>) {
    let mut empty_objects = std::collections::HashSet::<&str>::new();
    let mut functions = std::collections::HashSet::<&str>::new();
    for index in 0..tokens.len() {
        if tokens[index].kind != TokenKind::Identifier
            || tokens.get(index + 1).map(|token| token.text) != Some("=")
        {
            continue;
        }
        if tokens.get(index + 2).map(|token| token.text) == Some("{")
            && matching_close.get(index + 2).copied().flatten() == Some(index + 3)
        {
            empty_objects.insert(tokens[index].text);
        }
        if tokens.get(index + 2).is_some_and(|token| token.kind == TokenKind::Identifier)
            && tokens.get(index + 3).map(|token| token.text) == Some(".")
            && tokens.get(index + 4).map(|token| token.text) == Some("hasOwnProperty")
            && matches!(
                tokens.get(index + 5).map(|token| token.text),
                Some(",") | Some(";") | None
            )
        {
            functions.insert(tokens[index].text);
        }
    }
    let mut object_alias = None;
    let mut function_alias = None;
    for index in 0..tokens.len() {
        if tokens[index].kind != TokenKind::Identifier
            || tokens.get(index + 1).map(|token| token.text) != Some("=")
            || tokens
                .get(index + 2)
                .is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(index + 3).map(|token| token.text) != Some(".")
            || tokens.get(index + 4).map(|token| token.text) != Some("toString")
            || !matches!(
                tokens.get(index + 5).map(|token| token.text),
                Some(",") | Some(";") | None
            )
        {
            continue;
        }
        let ident = tokens[index + 2].text;
        let alias = tokens[index].text;
        if empty_objects.contains(ident) {
            object_alias = Some(alias);
        }
        if functions.contains(ident) {
            function_alias = Some(alias);
        }
    }
    (object_alias, function_alias)
}

fn fold_prototype_tostring_aliases(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let (object_alias, function_alias) =
        collect_prototype_tostring_aliases(&tokens, &matching_close);
    if object_alias.is_none() && function_alias.is_none() {
        return Ok((source.to_string(), 0));
    }
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor < tokens.len() {
        let Some((kind, close)) = prototype_tostring_call(&tokens, &matching_close, cursor) else {
            cursor += 1;
            continue;
        };
        let alias = match kind {
            PrototypeToStringKind::Object => object_alias,
            PrototypeToStringKind::Function => function_alias,
        };
        let Some(alias) = alias else {
            cursor += 1;
            continue;
        };
        let args = &source[tokens[cursor + 8].start..tokens[close].start];
        let rendered = format!("{alias}.call({args})");
        if kind == PrototypeToStringKind::Function
            && tokens.get(cursor.wrapping_sub(1)).map(|token| token.text) == Some("=")
            && cursor >= 2
            && tokens[cursor - 2].kind == TokenKind::Identifier
            && matches!(
                cursor
                    .checked_sub(3)
                    .map(|index| tokens[index].text)
                    .unwrap_or(";"),
                "let" | "var" | "const" | ","
            )
        {
            let name_at = cursor - 2;
            let name = tokens[name_at].text;
            let uses = (0..tokens.len())
                .filter(|&index| {
                    index != name_at
                        && tokens[index].kind == TokenKind::Identifier
                        && tokens[index].text == name
                })
                .collect::<Vec<_>>();
            if uses.len() == 1 && !name_use_is_mutated(&tokens, uses[0]) {
                replacements.push((tokens[uses[0]].start, tokens[uses[0]].end, rendered));
                let (from, to) = assignment_span_to_remove(&tokens, name_at, close);
                replacements.push((from, to, String::new()));
                cursor = close + 1;
                continue;
            }
        }
        replacements.push((tokens[cursor].start, tokens[close].end, rendered));
        cursor = close + 1;
    }
    Ok(apply_token_rewrites(source, replacements))
}

fn strip_unused_simple_declarators(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 4 < tokens.len() {
        if !matches!(tokens[cursor].text, "let" | "var") {
            cursor += 1;
            continue;
        }
        let mut name_at = cursor + 1;
        let mut kept = Vec::<(usize, usize)>::new();
        let mut any_removed = false;
        loop {
            if tokens.get(name_at).is_none_or(|token| token.kind != TokenKind::Identifier)
                || tokens.get(name_at + 1).map(|token| token.text) != Some("=")
                || tokens
                    .get(name_at + 2)
                    .is_none_or(|token| token.kind != TokenKind::Identifier)
            {
                let Some(stop) = top_level_stop(&tokens, name_at, &[",", ";"]) else {
                    break;
                };
                kept.push((name_at, stop));
                if tokens[stop].text == ";" {
                    break;
                }
                name_at = stop + 1;
                continue;
            }
            if tokens.get(name_at + 3).map(|token| token.text) == Some(".")
                && tokens
                    .get(name_at + 4)
                    .is_some_and(|token| token.kind == TokenKind::Identifier)
                && matches!(
                    tokens.get(name_at + 5).map(|token| token.text),
                    Some(",") | Some(";")
                )
            {
                let name = tokens[name_at].text;
                let stop = name_at + 5;
                if name_is_used_in_scope(&tokens, &matching_close, name_at, stop + 1, name) {
                    kept.push((name_at, stop));
                } else {
                    any_removed = true;
                }
                if tokens[stop].text == ";" {
                    break;
                }
                name_at = stop + 1;
                continue;
            }
            if tokens.get(name_at + 3).map(|token| token.text) == Some("[")
                && tokens.get(name_at + 4).is_some_and(|token| {
                    token.kind == TokenKind::Identifier || token.kind == TokenKind::Number
                })
                && tokens.get(name_at + 5).map(|token| token.text) == Some("]")
                && matches!(
                    tokens.get(name_at + 6).map(|token| token.text),
                    Some(",") | Some(";")
                )
            {
                let name = tokens[name_at].text;
                let stop = name_at + 6;
                if name_is_used_in_scope(&tokens, &matching_close, name_at, stop + 1, name) {
                    kept.push((name_at, stop));
                } else {
                    any_removed = true;
                }
                if tokens[stop].text == ";" {
                    break;
                }
                name_at = stop + 1;
                continue;
            }
            if tokens.get(name_at + 3).map(|token| token.text) == Some(".") {
                let Some(stop) = top_level_stop(&tokens, name_at, &[",", ";"]) else {
                    break;
                };
                kept.push((name_at, stop));
                if tokens[stop].text == ";" {
                    break;
                }
                name_at = stop + 1;
                continue;
            }
            let rhs_end = name_at + 2;
            if !matches!(tokens.get(rhs_end + 1).map(|token| token.text), Some(",") | Some(";")) {
                let Some(stop) = top_level_stop(&tokens, name_at, &[",", ";"]) else {
                    break;
                };
                kept.push((name_at, stop));
                if tokens[stop].text == ";" {
                    break;
                }
                name_at = stop + 1;
                continue;
            }
            let name = tokens[name_at].text;
            let stop = rhs_end + 1;
            if name_is_used_in_scope(&tokens, &matching_close, name_at, stop + 1, name) {
                kept.push((name_at, stop));
            } else {
                any_removed = true;
            }
            if tokens[stop].text == ";" {
                break;
            }
            name_at = stop + 1;
        }
        if any_removed {
            let Some(semi) = tokens
                .iter()
                .enumerate()
                .skip(cursor)
                .find(|(_, token)| token.text == ";")
                .map(|(index, _)| index)
            else {
                cursor += 1;
                continue;
            };
            let replacement = if kept.is_empty() {
                String::new()
            } else {
                let decls = kept
                    .iter()
                    .map(|(start, end)| source[tokens[*start].start..tokens[*end].start].to_string())
                    .collect::<Vec<_>>()
                    .join(",");
                format!("{} {decls};", tokens[cursor].text)
            };
            replacements.push((tokens[cursor].start, tokens[semi].end, replacement));
            cursor = semi + 1;
            continue;
        }
        cursor += 1;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_temp_index_keys(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 8 < tokens.len() {
        let name_at = if matches!(tokens[cursor].text, "var" | "let") {
            cursor + 1
        } else {
            cursor
        };
        if tokens.get(name_at).is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(name_at + 1).map(|token| token.text) != Some("=")
        {
            cursor += 1;
            continue;
        }
        let Some(semi) = top_level_stop(&tokens, name_at + 2, &[";"]) else {
            cursor += 1;
            continue;
        };
        let name = tokens[name_at].text;
        if tokens
            .get(semi + 1)
            .is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(semi + 2).map(|token| token.text) != Some("[")
            || tokens.get(semi + 3).map(|token| token.text) != Some(name)
            || tokens.get(semi + 4).map(|token| token.text) != Some("]")
            || tokens.get(semi + 5).map(|token| token.text) != Some("=")
        {
            cursor += 1;
            continue;
        }
        let Some(assign_end) = top_level_stop(&tokens, semi + 6, &[";", "}"]) else {
            cursor += 1;
            continue;
        };
        let scope_end = enclosing_block_end(&matching_closers(&tokens), name_at).unwrap_or(tokens.len());
        if identifier_occurs(&tokens, name_at + 2, semi, name)
            || identifier_occurs(&tokens, semi + 6, assign_end, name)
            || identifier_occurs(&tokens, assign_end + 1, scope_end, name)
        {
            cursor += 1;
            continue;
        }
        let key = &source[tokens[name_at + 2].start..tokens[semi].start];
        let object = tokens[semi + 1].text;
        let value = &source[tokens[semi + 6].start..tokens[assign_end].start];
        let from = if name_at
            .checked_sub(1)
            .is_some_and(|index| tokens[index].text == ",")
        {
            tokens[name_at - 1].start
        } else {
            tokens[cursor].start
        };
        let replace_end = if tokens[assign_end].text == "}" {
            tokens[assign_end].start
        } else {
            tokens[assign_end].end
        };
        replacements.push((
            from,
            replace_end,
            format!("{object}[{key}]={value};"),
        ));
        cursor = assign_end + 1;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_coalesced_or_returns(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 12 < tokens.len() {
        let name_index = if matches!(tokens[cursor].text, "var" | "let") {
            cursor + 1
        } else {
            cursor
        };
        if tokens.get(name_index).is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(name_index + 1).map(|token| token.text) != Some("=")
        {
            cursor += 1;
            continue;
        }
        let name = tokens[name_index].text;
        let Some(first_semi) = top_level_stop(&tokens, name_index + 2, &[";"]) else {
            cursor += 1;
            continue;
        };
        if tokens.get(first_semi + 1).map(|token| token.text) != Some("!")
            || tokens.get(first_semi + 2).map(|token| token.text) != Some(name)
            || tokens.get(first_semi + 3).map(|token| token.text) != Some("&&")
            || tokens.get(first_semi + 4).map(|token| token.text) != Some("(")
            || tokens.get(first_semi + 5).map(|token| token.text) != Some(name)
            || tokens.get(first_semi + 6).map(|token| token.text) != Some("=")
        {
            cursor += 1;
            continue;
        }
        let Some(assign_close) = top_level_stop(&tokens, first_semi + 7, &[")"]) else {
            cursor += 1;
            continue;
        };
        if tokens.get(assign_close + 1).map(|token| token.text) != Some(";")
            || tokens.get(assign_close + 2).map(|token| token.text) != Some("return")
        {
            cursor += 1;
            continue;
        }
        if identifier_occurs(&tokens, first_semi + 7, assign_close, name) {
            cursor += 1;
            continue;
        }
        let left = &source[tokens[name_index + 2].start..tokens[first_semi].start];
        let right = &source[tokens[first_semi + 7].start..tokens[assign_close].start];
        let value = format!("{left}||{right}");
        let return_at = assign_close + 2;
        let comma_declarator = name_index
            .checked_sub(1)
            .is_some_and(|index| tokens[index].text == ",");
        let replace_from = if comma_declarator {
            tokens[name_index - 1].start
        } else {
            tokens[cursor].start
        };
        let prefix = if comma_declarator { ";" } else { "" };
        let replacement = if tokens.get(return_at + 1).map(|token| token.text) == Some(name) {
            let after_name = return_at + 2;
            if tokens.get(after_name).map(|token| token.text) == Some(".")
                && tokens
                    .get(after_name + 1)
                    .is_some_and(|token| token.kind == TokenKind::Identifier)
                && tokens.get(after_name + 2).map(|token| token.text) == Some("(")
            {
                let Some(call_close) = matching_close.get(after_name + 2).copied().flatten() else {
                    cursor += 1;
                    continue;
                };
                if identifier_occurs(&tokens, after_name + 3, call_close, name) {
                    cursor += 1;
                    continue;
                }
                let end = tokens
                    .get(call_close + 1)
                    .filter(|token| token.text == ";")
                    .map(|token| token.end)
                    .unwrap_or(tokens[call_close].end);
                let suffix = &source[tokens[after_name].start..tokens[call_close].end];
                (
                    replace_from,
                    end,
                    format!("{prefix}return ({value}){suffix}"),
                )
            } else {
                let end = tokens
                    .get(after_name)
                    .filter(|token| token.text == ";")
                    .map(|token| token.end)
                    .unwrap_or(tokens[return_at + 1].end);
                (replace_from, end, format!("{prefix}return {value}"))
            }
        } else if tokens.get(return_at + 1).map(|token| token.text) == Some("!")
            && tokens
                .get(return_at + 2)
                .is_some_and(|token| token.kind == TokenKind::Identifier)
            && tokens.get(return_at + 3).map(|token| token.text) == Some(".")
            && tokens.get(return_at + 4).map(|token| token.text) == Some("test")
            && tokens.get(return_at + 5).map(|token| token.text) == Some("(")
            && tokens.get(return_at + 6).map(|token| token.text) == Some(name)
            && tokens.get(return_at + 7).map(|token| token.text) == Some(")")
        {
            let end = tokens
                .get(return_at + 8)
                .filter(|token| token.text == ";")
                .map(|token| token.end)
                .unwrap_or(tokens[return_at + 7].end);
            (
                replace_from,
                end,
                format!("{prefix}return!{}.test({value})", tokens[return_at + 2].text),
            )
        } else {
            cursor += 1;
            continue;
        };
        replacements.push(replacement);
        cursor = return_at + 4;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn flatten_associative_string_concats(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 6 < tokens.len() {
        if tokens[cursor].kind == TokenKind::String
            && tokens.get(cursor + 1).map(|token| token.text) == Some("+")
            && tokens.get(cursor + 2).map(|token| token.text) == Some("(")
            && tokens
                .get(cursor + 3)
                .is_some_and(|token| token.kind == TokenKind::Identifier)
            && tokens.get(cursor + 4).map(|token| token.text) == Some("+")
            && tokens.get(cursor + 5).map(|token| token.kind) == Some(TokenKind::String)
            && tokens.get(cursor + 6).map(|token| token.text) == Some(")")
        {
            replacements.push((
                tokens[cursor].start,
                tokens[cursor + 6].end,
                format!(
                    "{}+{}+{}",
                    tokens[cursor].text, tokens[cursor + 3].text, tokens[cursor + 5].text
                ),
            ));
            cursor += 7;
            continue;
        }
        cursor += 1;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_for_false_breaks(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    for for_at in 0..tokens.len() {
        if tokens[for_at].text != "for" || tokens.get(for_at + 1).map(|token| token.text) != Some("(")
        {
            continue;
        }
        let Some(header_close) = matching_close.get(for_at + 1).copied().flatten() else {
            continue;
        };
        let mut semis = Vec::new();
        let mut depth = 0i32;
        for (index, token) in tokens.iter().enumerate().take(header_close).skip(for_at + 2) {
            match token.text {
                "(" | "[" | "{" => depth += 1,
                ")" | "]" | "}" => depth -= 1,
                ";" if depth == 0 => semis.push(index),
                _ => {}
            }
        }
        if semis.len() != 2 {
            continue;
        }
        let cond = &source[tokens[semis[0]].end..tokens[semis[1]].start];
        let inc = &source[tokens[semis[1]].end..tokens[header_close].start];
        let init = &source[tokens[for_at + 1].end..tokens[semis[0]].start];
        let body_at = header_close + 1;
        let (test_start, test_end, body_end) = if tokens.get(body_at).map(|token| token.text)
            == Some("{")
        {
            let Some(body_close) = matching_close.get(body_at).copied().flatten() else {
                continue;
            };
            let Some((test_start, test_end, after_break)) =
                exclusive_if_break(&tokens, &matching_close, body_at + 1)
            else {
                continue;
            };
            if after_break != body_close {
                continue;
            }
            (test_start, test_end, tokens[body_close].end)
        } else {
            let Some((test_start, test_end, after_break)) =
                exclusive_if_break(&tokens, &matching_close, body_at)
            else {
                continue;
            };
            let end = tokens
                .get(after_break)
                .filter(|token| token.text == ";")
                .map(|token| token.end)
                .unwrap_or(tokens[after_break - 1].end);
            (test_start, test_end, end)
        };
        let Some(cond_extra) = false_equality_condition(source, &tokens, test_start, test_end) else {
            continue;
        };
        let new_cond = if cond.trim().is_empty() {
            cond_extra
        } else {
            format!("{cond}&&{cond_extra}")
        };
        replacements.push((
            tokens[for_at].start,
            body_end,
            format!("for({init};{new_cond};{inc});"),
        ));
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn exclusive_if_break(
    tokens: &[Token<'_>],
    matching_close: &[Option<usize>],
    if_at: usize,
) -> Option<(usize, usize, usize)> {
    if tokens.get(if_at).map(|token| token.text) != Some("if")
        || tokens.get(if_at + 1).map(|token| token.text) != Some("(")
    {
        return None;
    }
    let if_close = matching_close.get(if_at + 1).copied().flatten()?;
    let after_break = if tokens.get(if_close + 1).map(|token| token.text) == Some("break") {
        if tokens.get(if_close + 2).map(|token| token.text) == Some(";") {
            if_close + 3
        } else {
            if_close + 2
        }
    } else if tokens.get(if_close + 1).map(|token| token.text) == Some("{") {
        let block_close = matching_close.get(if_close + 1).copied().flatten()?;
        if tokens.get(if_close + 2).map(|token| token.text) != Some("break") {
            return None;
        }
        let after_inner = if tokens.get(if_close + 3).map(|token| token.text) == Some(";") {
            if_close + 4
        } else {
            if_close + 3
        };
        if after_inner != block_close {
            return None;
        }
        block_close + 1
    } else {
        return None;
    };
    Some((if_at + 2, if_close, after_break))
}

fn false_equality_condition(
    source: &str,
    tokens: &[Token<'_>],
    test_open: usize,
    test_close: usize,
) -> Option<String> {
    let test = &tokens[test_open..test_close];
    let eq_at = if test.len() >= 3
        && test[test.len() - 1].text == "1"
        && test[test.len() - 2].text == "!"
        && matches!(test[test.len() - 3].text, "===" | "==")
    {
        test.len() - 3
    } else if test.len() >= 2
        && matches!(test[test.len() - 1].text, "false" | "!1")
        && matches!(test[test.len() - 2].text, "===" | "==")
    {
        test.len() - 2
    } else {
        return None;
    };
    let left = &source[test[0].start..test[eq_at].start];
    Some(format!("!1!=={left}"))
}

fn fold_nullish_index_walks(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    for for_at in 0..tokens.len() {
        if tokens[for_at].text != "for" || tokens.get(for_at + 1).map(|token| token.text) != Some("(")
        {
            continue;
        }
        let Some(header_close) = matching_close.get(for_at + 1).copied().flatten() else {
            continue;
        };
        let header = &source[tokens[for_at + 1].end..tokens[header_close].start];
        if header != ";!0;" && header != ";;" {
            continue;
        }
        let body_open = header_close + 1;
        if tokens.get(body_open).map(|token| token.text) != Some("{") {
            continue;
        }
        let Some(body_close) = matching_close.get(body_open).copied().flatten() else {
            continue;
        };
        if let Some(folded) =
            fold_index_walk_from_tokens(source, &tokens, body_open, body_close)
        {
            replacements.push((tokens[for_at].start, tokens[body_close].end, folded));
        }
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_index_walk_from_tokens(
    source: &str,
    tokens: &[Token<'_>],
    body_open: usize,
    body_close: usize,
) -> Option<String> {
    let start = body_open + 1;
    if let Some(folded) = fold_postfix_index_walk(source, tokens, start, body_close) {
        return Some(folded);
    }
    fold_temp_index_walk(source, tokens, start, body_close)
}

fn consume_falsy_break(tokens: &[Token<'_>], at: usize, name: &str) -> Option<usize> {
    if tokens.get(at).map(|token| token.text) != Some("if")
        || tokens.get(at + 1).map(|token| token.text) != Some("(")
    {
        return None;
    }
    let after_test = if tokens.get(at + 2).map(|token| token.text) == Some("!")
        && tokens.get(at + 3).map(|token| token.text) == Some(name)
        && tokens.get(at + 4).map(|token| token.text) == Some(")")
    {
        at + 5
    } else if tokens.get(at + 2).map(|token| token.text) == Some(name)
        && matches!(tokens.get(at + 3).map(|token| token.text), Some("==") | Some("==="))
        && tokens.get(at + 4).map(|token| token.text) == Some("null")
        && tokens.get(at + 5).map(|token| token.text) == Some(")")
    {
        at + 6
    } else {
        return None;
    };
    if tokens.get(after_test).map(|token| token.text) != Some("break") {
        return None;
    }
    Some(if tokens.get(after_test + 1).map(|token| token.text) == Some(";") {
        after_test + 2
    } else {
        after_test + 1
    })
}

fn fold_postfix_index_walk(
    source: &str,
    tokens: &[Token<'_>],
    start: usize,
    body_close: usize,
) -> Option<String> {
    if tokens.get(start).is_none_or(|token| token.kind != TokenKind::Identifier)
        || tokens.get(start + 1).map(|token| token.text) != Some("=")
        || tokens
            .get(start + 2)
            .is_none_or(|token| token.kind != TokenKind::Identifier)
        || tokens.get(start + 3).map(|token| token.text) != Some("[")
        || tokens
            .get(start + 4)
            .is_none_or(|token| token.kind != TokenKind::Identifier)
        || tokens.get(start + 5).map(|token| token.text) != Some("++")
        || tokens.get(start + 6).map(|token| token.text) != Some("]")
        || tokens.get(start + 7).map(|token| token.text) != Some(";")
    {
        return None;
    }
    let node = tokens[start].text;
    let array = tokens[start + 2].text;
    let index = tokens[start + 4].text;
    let body_start = consume_falsy_break(tokens, start + 8, node)?;
    if body_start >= body_close {
        return None;
    }
    let body = source[tokens[body_start].start..tokens[body_close].start].trim_end_matches(';');
    Some(format!("for(;{node}={array}[{index}++];){body};"))
}

fn fold_temp_index_walk(
    source: &str,
    tokens: &[Token<'_>],
    start: usize,
    body_close: usize,
) -> Option<String> {
    if tokens.get(start).is_none_or(|token| token.kind != TokenKind::Identifier)
        || tokens.get(start + 1).map(|token| token.text) != Some("=")
        || tokens
            .get(start + 2)
            .is_none_or(|token| token.kind != TokenKind::Identifier)
        || tokens.get(start + 3).map(|token| token.text) != Some("+")
        || tokens.get(start + 4).map(|token| token.text) != Some("1")
        || tokens.get(start + 5).map(|token| token.text) != Some(";")
    {
        return None;
    }
    let temp = tokens[start].text;
    let index = tokens[start + 2].text;
    if temp == index {
        return None;
    }
    let read_at = start + 6;
    if tokens.get(read_at).is_none_or(|token| token.kind != TokenKind::Identifier)
        || tokens.get(read_at + 1).map(|token| token.text) != Some("=")
        || tokens
            .get(read_at + 2)
            .is_none_or(|token| token.kind != TokenKind::Identifier)
        || tokens.get(read_at + 3).map(|token| token.text) != Some("[")
        || tokens.get(read_at + 4).map(|token| token.text) != Some(index)
        || tokens.get(read_at + 5).map(|token| token.text) != Some("]")
        || tokens.get(read_at + 6).map(|token| token.text) != Some(";")
    {
        return None;
    }
    let node = tokens[read_at].text;
    let array = tokens[read_at + 2].text;
    let body_start = consume_falsy_break(tokens, read_at + 7, node)?;
    if body_start >= body_close {
        return None;
    }
    let restore_at = if tokens.get(body_close - 1).map(|token| token.text) == Some(";") {
        body_close - 4
    } else {
        body_close - 3
    };
    if tokens.get(restore_at).map(|token| token.text) != Some(index)
        || tokens.get(restore_at + 1).map(|token| token.text) != Some("=")
        || tokens.get(restore_at + 2).map(|token| token.text) != Some(temp)
    {
        return None;
    }
    if identifier_occurs(tokens, body_start, restore_at, temp) {
        return None;
    }
    if node == index {
        let body = rewrite_identifier_span(source, tokens, body_start, restore_at, node, temp)
            .trim_end_matches(';')
            .to_string();
        Some(format!("for(;{temp}={array}[{index}++];){body};"))
    } else if identifier_occurs(tokens, body_start, restore_at, index) {
        None
    } else {
        let body = source[tokens[body_start].start..tokens[restore_at].start].trim_end_matches(';');
        Some(format!("for(;{node}={array}[{index}++];){body};"))
    }
}

fn rewrite_identifier_span(
    source: &str,
    tokens: &[Token<'_>],
    start: usize,
    end: usize,
    from: &str,
    to: &str,
) -> String {
    if start >= end {
        return String::new();
    }
    let mut output = String::new();
    let mut cursor = tokens[start].start;
    for token in &tokens[start..end] {
        output.push_str(&source[cursor..token.start]);
        if token.kind == TokenKind::Identifier && token.text == from {
            output.push_str(to);
        } else {
            output.push_str(token.text);
        }
        cursor = token.end;
    }
    output
}

fn fold_assigned_truthy_ternaries(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    for open in 0..tokens.len() {
        if tokens[open].text != "("
            || tokens
                .get(open + 1)
                .is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(open + 2).map(|token| token.text) != Some("=")
        {
            continue;
        }
        let Some(close) = matching_close.get(open).copied().flatten() else {
            continue;
        };
        let name = tokens[open + 1].text;
        if tokens.get(close + 1).map(|token| token.text) != Some("?")
            || tokens.get(close + 2).map(|token| token.text) != Some(name)
            || tokens.get(close + 3).map(|token| token.text) != Some(":")
        {
            continue;
        }
        let fallback_at = close + 4;
        let Some(fallback_end) = complete_primary_end(&tokens, fallback_at) else {
            continue;
        };
        if identifier_occurs(&tokens, fallback_at, fallback_end + 1, name)
            || name_is_read_after_statement(&tokens, fallback_end + 1, name)
        {
            continue;
        }
        let expr = &source[tokens[open + 3].start..tokens[close].start];
        let fallback = &source[tokens[fallback_at].start..tokens[fallback_end].end];
        replacements.push((
            tokens[open].start,
            tokens[fallback_end].end,
            format!("{expr}||{fallback}"),
        ));
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn complete_primary_end(tokens: &[Token<'_>], start: usize) -> Option<usize> {
    let token = tokens.get(start)?;
    if matches!(
        token.kind,
        TokenKind::String | TokenKind::Number | TokenKind::Keyword | TokenKind::Identifier
    ) {
        return Some(start);
    }
    if token.text == "(" || token.text == "[" {
        return matching_closers(tokens).get(start).copied().flatten();
    }
    None
}

fn name_is_read_after_statement(tokens: &[Token<'_>], start: usize, name: &str) -> bool {
    let mut index = start;
    while index < tokens.len() && matches!(tokens[index].text, ":" | ")" | "," | ";" | "?" | "&&" | "||")
    {
        if tokens[index].text == ";" {
            index += 1;
            break;
        }
        index += 1;
    }
    let mut depth = 0i32;
    while index < tokens.len() {
        match tokens[index].text {
            "{" => depth += 1,
            "}" if depth == 0 => return false,
            "}" => depth -= 1,
            "function" if depth == 0 => return false,
            _ if tokens[index].kind == TokenKind::Identifier && tokens[index].text == name => {
                return true;
            }
            _ => {}
        }
        index += 1;
    }
    false
}

fn is_object_name(token: &Token<'_>) -> bool {
    token.kind == TokenKind::Identifier || token.text == "this"
}

fn length_binding<'a>(tokens: &[Token<'a>], name_at: usize) -> Option<(&'a str, &'a str, usize)> {
    if tokens.get(name_at)?.kind != TokenKind::Identifier || tokens.get(name_at + 1)?.text != "=" {
        return None;
    }
    let object_at = if tokens.get(name_at + 2)?.text == "+"
        && is_object_name(tokens.get(name_at + 3)?)
        && tokens.get(name_at + 4)?.text == "."
        && tokens.get(name_at + 5)?.text == "length"
    {
        name_at + 3
    } else if is_object_name(tokens.get(name_at + 2)?)
        && tokens.get(name_at + 3)?.text == "."
        && tokens.get(name_at + 4)?.text == "length"
    {
        name_at + 2
    } else {
        return None;
    };
    Some((tokens[name_at].text, tokens[object_at].text, object_at + 2))
}

fn collect_length_bindings<'a>(
    tokens: &[Token<'a>],
    start: usize,
    end: usize,
    out: &mut Vec<(&'a str, &'a str)>,
) {
    let mut index = start;
    while index < end {
        if matches!(tokens[index].text, "var" | "let" | "const" | ",") {
            index += 1;
            continue;
        }
        if let Some((name, object, length_at)) = length_binding(tokens, index) {
            let after = length_at + 1;
            if after < end && !matches!(tokens[after].text, ",") {
                index += 1;
                continue;
            }
            out.retain(|(existing, _)| *existing != name);
            out.push((name, object));
            index = after;
            continue;
        }
        index += 1;
    }
}

fn previous_statement_range(tokens: &[Token<'_>], for_at: usize) -> Option<(usize, usize)> {
    let semi = for_at.checked_sub(1)?;
    if tokens[semi].text != ";" {
        return None;
    }
    let mut depth = 0i32;
    let mut index = semi;
    while index > 0 {
        index -= 1;
        match tokens[index].text {
            ")" | "]" | "}" => depth += 1,
            "(" | "[" | "{" => {
                if depth == 0 {
                    return Some((index + 1, semi));
                }
                depth -= 1;
            }
            ";" if depth == 0 => return Some((index + 1, semi)),
            _ => {}
        }
    }
    (depth == 0).then_some((0, semi))
}

fn fold_cached_length_conditions(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    for for_at in 0..tokens.len() {
        if tokens[for_at].text != "for" || tokens.get(for_at + 1).map(|token| token.text) != Some("(")
        {
            continue;
        }
        let Some(header_close) = matching_close.get(for_at + 1).copied().flatten() else {
            continue;
        };
        let mut semis = Vec::new();
        let mut depth = 0i32;
        for (index, token) in tokens.iter().enumerate().take(header_close).skip(for_at + 2) {
            match token.text {
                "(" | "[" | "{" => depth += 1,
                ")" | "]" | "}" => depth -= 1,
                ";" if depth == 0 => semis.push(index),
                _ => {}
            }
        }
        if semis.len() != 2 {
            continue;
        }
        let mut bindings = Vec::<(&str, &str)>::new();
        collect_length_bindings(&tokens, for_at + 2, semis[0], &mut bindings);
        if let Some((start, end)) = previous_statement_range(&tokens, for_at) {
            collect_length_bindings(&tokens, start, end, &mut bindings);
        }
        if bindings.is_empty() {
            continue;
        }
        let mut index = semis[0] + 1;
        while index + 2 < semis[1] {
            if is_object_name(&tokens[index])
                && tokens[index + 1].text == "."
                && tokens[index + 2].text == "length"
                && tokens.get(index + 3).map(|token| token.text) != Some("=")
            {
                let object = tokens[index].text;
                if let Some((name, _)) = bindings.iter().rev().find(|(_, obj)| *obj == object) {
                    replacements.push((
                        tokens[index].start,
                        tokens[index + 2].end,
                        (*name).to_string(),
                    ));
                    index += 3;
                    continue;
                }
            }
            index += 1;
        }
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_cached_member_reads(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 4 < tokens.len() {
        let name_at = if matches!(tokens[cursor].text, "var" | "let") {
            cursor + 1
        } else {
            cursor
        };
        if tokens.get(name_at).is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(name_at + 1).map(|token| token.text) != Some("=")
            || !tokens.get(name_at + 2).is_some_and(is_object_name)
            || tokens.get(name_at + 3).map(|token| token.text) != Some(".")
            || tokens
                .get(name_at + 4)
                .is_none_or(|token| token.kind != TokenKind::Identifier)
            || !matches!(
                tokens.get(name_at + 5).map(|token| token.text),
                Some(",") | Some(";") | Some("}") | None
            )
        {
            cursor += 1;
            continue;
        }
        let name = tokens[name_at].text;
        let object = tokens[name_at + 2].text;
        let prop = tokens[name_at + 4].text;
        let scope_end = enclosing_block_end(&matching_close, name_at).unwrap_or(tokens.len());
        let mut scan = name_at + 5;
        if matches!(tokens.get(scan).map(|token| token.text), Some(",") | Some(";")) {
            scan += 1;
        }
        while scan + 2 < scope_end {
            if let Some(close) = nested_function_end(&tokens, &matching_close, scan) {
                scan = close + 1;
                continue;
            }
            if tokens[scan].kind == TokenKind::Identifier && tokens[scan].text == name {
                if tokens.get(scan + 1).map(|token| token.text) == Some("=")
                    && tokens.get(scan + 2).map(|token| token.text) != Some("=")
                {
                    break;
                }
            }
            let prev = scan
                .checked_sub(1)
                .map(|index| tokens[index].text)
                .unwrap_or(";");
            if is_object_name(&tokens[scan])
                && tokens[scan].text == object
                && tokens.get(scan + 1).map(|token| token.text) == Some(".")
                && tokens.get(scan + 2).map(|token| token.text) == Some(prop)
                && tokens.get(scan + 3).map(|token| token.text) != Some("=")
                && prev != ":"
            {
                replacements.push((tokens[scan].start, tokens[scan + 2].end, name.to_string()));
                scan += 3;
                continue;
            }
            scan += 1;
        }
        cursor = name_at + 1;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_repeated_member_assigns(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 10 < tokens.len() {
        let prev = cursor
            .checked_sub(1)
            .map(|index| tokens[index].text)
            .unwrap_or(";");
        if !matches!(prev, ";" | "{" | "}")
            || !is_object_name(&tokens[cursor])
            || tokens.get(cursor + 1).map(|token| token.text) != Some(".")
            || tokens
                .get(cursor + 2)
                .is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(cursor + 3).map(|token| token.text) != Some("=")
            || tokens
                .get(cursor + 4)
                .is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(cursor + 5).map(|token| token.text) != Some(";")
            || tokens.get(cursor + 6).map(|token| token.text) != Some(tokens[cursor].text)
            || tokens.get(cursor + 7).map(|token| token.text) != Some(".")
            || tokens
                .get(cursor + 8)
                .is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens[cursor + 8].text == tokens[cursor + 2].text
            || tokens.get(cursor + 9).map(|token| token.text) != Some("=")
            || tokens.get(cursor + 10).map(|token| token.text) != Some(tokens[cursor + 4].text)
        {
            cursor += 1;
            continue;
        }
        replacements.push((
            tokens[cursor].start,
            tokens[cursor + 10].end,
            format!(
                "{}.{}={}.{}={}",
                tokens[cursor].text,
                tokens[cursor + 2].text,
                tokens[cursor].text,
                tokens[cursor + 8].text,
                tokens[cursor + 4].text
            ),
        ));
        cursor += 11;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn skip_nested_loop_or_function(
    tokens: &[Token<'_>],
    matching_close: &[Option<usize>],
    scan: usize,
) -> Option<usize> {
    if let Some(close) = nested_function_end(tokens, matching_close, scan) {
        return Some(close);
    }
    if matches!(tokens[scan].text, "for" | "while")
        && tokens.get(scan + 1).map(|token| token.text) == Some("(")
    {
        let header_close = matching_close.get(scan + 1).copied().flatten()?;
        let after = header_close + 1;
        if tokens.get(after).map(|token| token.text) == Some("{") {
            return matching_close.get(after).copied().flatten();
        }
        return top_level_stop(tokens, after, &[";"]);
    }
    if tokens[scan].text == "do" && tokens.get(scan + 1).map(|token| token.text) == Some("{") {
        return matching_close.get(scan + 1).copied().flatten();
    }
    None
}

fn fold_for_trailing_increments(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    for for_at in 0..tokens.len() {
        if tokens[for_at].text != "for" || tokens.get(for_at + 1).map(|token| token.text) != Some("(")
        {
            continue;
        }
        let Some(header_close) = matching_close.get(for_at + 1).copied().flatten() else {
            continue;
        };
        let mut semis = Vec::new();
        let mut depth = 0i32;
        for (index, token) in tokens.iter().enumerate().take(header_close).skip(for_at + 2) {
            match token.text {
                "(" | "[" | "{" => depth += 1,
                ")" | "]" | "}" => depth -= 1,
                ";" if depth == 0 => semis.push(index),
                _ => {}
            }
        }
        if semis.len() != 2 || semis[1] + 1 != header_close {
            continue;
        }
        let body_at = header_close + 1;
        if tokens.get(body_at).map(|token| token.text) != Some("{") {
            continue;
        }
        let Some(body_close) = matching_close.get(body_at).copied().flatten() else {
            continue;
        };
        let last = if tokens.get(body_close - 1).map(|token| token.text) == Some(";")
            && tokens.get(body_close - 2).map(|token| token.text) == Some("++")
        {
            body_close - 3
        } else if tokens.get(body_close - 1).map(|token| token.text) == Some("++") {
            body_close - 2
        } else {
            continue;
        };
        if last <= body_at + 1
            || tokens.get(last).is_none_or(|token| token.kind != TokenKind::Identifier)
        {
            continue;
        }
        let name = tokens[last].text;
        let mut scan = body_at + 1;
        let mut same_level_continue = false;
        while scan < last {
            if let Some(close) = skip_nested_loop_or_function(&tokens, &matching_close, scan) {
                scan = close + 1;
                continue;
            }
            if tokens[scan].text == "continue" {
                same_level_continue = true;
                break;
            }
            scan += 1;
        }
        if same_level_continue {
            continue;
        }
        let init = &source[tokens[for_at + 1].end..tokens[semis[0]].start];
        let cond = &source[tokens[semis[0]].end..tokens[semis[1]].start];
        let body = source[tokens[body_at + 1].start..tokens[last].start]
            .trim_end_matches(';')
            .trim();
        let body = if body.is_empty() {
            ";".to_string()
        } else if body.contains(';') || body.contains('{') {
            format!("{{{body};}}")
        } else {
            format!("{body};")
        };
        replacements.push((
            tokens[for_at].start,
            tokens[body_close].end,
            format!("for({init};{cond};{name}++){body}"),
        ));
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn strip_unused_for_init_vars(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    for for_at in 0..tokens.len() {
        if tokens[for_at].text != "for" || tokens.get(for_at + 1).map(|token| token.text) != Some("(")
        {
            continue;
        }
        if tokens.get(for_at + 2).map(|token| token.text) != Some("var")
            && tokens.get(for_at + 2).map(|token| token.text) != Some("let")
        {
            continue;
        }
        if matching_close.get(for_at + 1).copied().flatten().is_none() {
            continue;
        }
        if tokens.get(for_at + 3).is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(for_at + 4).map(|token| token.text) != Some(",")
        {
            continue;
        }
        let name = tokens[for_at + 3].text;
        let scope_end = enclosing_block_end(&matching_close, for_at).unwrap_or(tokens.len());
        if identifier_occurs(&tokens, for_at + 4, scope_end, name) {
            continue;
        }
        replacements.push((tokens[for_at + 3].start, tokens[for_at + 4].end, String::new()));
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn flip_false_equalities(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 3 < tokens.len() {
        if tokens[cursor].text == "==="
            && tokens.get(cursor + 1).map(|token| token.text) == Some("!")
            && tokens.get(cursor + 2).map(|token| token.text) == Some("1")
        {
            let Some(left_start) = equality_left_start(&tokens, &matching_close, cursor) else {
                cursor += 1;
                continue;
            };
            let left = &source[tokens[left_start].start..tokens[cursor].start];
            replacements.push((
                tokens[left_start].start,
                tokens[cursor + 2].end,
                format!("!1==={left}"),
            ));
            cursor += 3;
            continue;
        }
        cursor += 1;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn equality_left_start(
    tokens: &[Token<'_>],
    matching_close: &[Option<usize>],
    eq_at: usize,
) -> Option<usize> {
    let prev = eq_at.checked_sub(1)?;
    if tokens[prev].text == ")" {
        let open = matching_close
            .iter()
            .enumerate()
            .find_map(|(open, close)| (*close == Some(prev)).then_some(open))?;
        let mut start = open;
        if start == 0 || tokens[start - 1].kind != TokenKind::Identifier {
            return None;
        }
        start -= 1;
        loop {
            if start >= 2
                && tokens[start - 1].text == "."
                && tokens[start - 2].kind == TokenKind::Identifier
            {
                start -= 2;
                continue;
            }
            if start >= 2 && tokens[start - 1].text == "." && tokens[start - 2].text == "]" {
                let close = start - 2;
                let Some(open) = matching_close
                    .iter()
                    .enumerate()
                    .find_map(|(open, end)| (*end == Some(close)).then_some(open))
                else {
                    break;
                };
                if open == 0 || tokens[open - 1].kind != TokenKind::Identifier {
                    break;
                }
                start = open - 1;
                continue;
            }
            break;
        }
        return Some(start);
    }
    (tokens[prev].kind == TokenKind::Identifier).then_some(prev)
}

fn fold_single_property_objects(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 10 < tokens.len() {
        let name_at = if matches!(tokens[cursor].text, "var" | "let") {
            cursor + 1
        } else {
            cursor
        };
        if tokens.get(name_at).is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(name_at + 1).map(|token| token.text) != Some("=")
            || tokens.get(name_at + 2).map(|token| token.text) != Some("{")
            || tokens.get(name_at + 3).map(|token| token.text) != Some("}")
            || tokens.get(name_at + 4).map(|token| token.text) != Some(";")
            || tokens.get(name_at + 5).map(|token| token.text) != Some(tokens[name_at].text)
            || tokens.get(name_at + 6).map(|token| token.text) != Some(".")
            || tokens
                .get(name_at + 7)
                .is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(name_at + 8).map(|token| token.text) != Some("=")
        {
            cursor += 1;
            continue;
        }
        let name = tokens[name_at].text;
        let Some(semi) = top_level_stop(&tokens, name_at + 9, &[";"]) else {
            cursor += 1;
            continue;
        };
        let prop = tokens[name_at + 7].text;
        let value = &source[tokens[name_at + 9].start..tokens[semi].start];
        let scope_end = enclosing_block_end(&matching_closers(&tokens), name_at).unwrap_or(tokens.len());
        let uses = (semi + 1..scope_end)
            .filter(|&index| tokens[index].kind == TokenKind::Identifier && tokens[index].text == name)
            .collect::<Vec<_>>();
        if uses.len() != 1 {
            cursor += 1;
            continue;
        }
        let use_at = uses[0];
        replacements.push((
            tokens[cursor].start,
            tokens[semi].end,
            String::new(),
        ));
        replacements.push((
            tokens[use_at].start,
            tokens[use_at].end,
            format!("{{{prop}:{value}}}"),
        ));
        cursor = semi + 1;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn is_statement_boundary(tokens: &[Token<'_>], index: usize) -> bool {
    matches!(
        index
            .checked_sub(1)
            .map(|prev| tokens[prev].text)
            .unwrap_or(";"),
        ";" | "{" | "}"
    )
}

fn for_header_semicolons(
    tokens: &[Token<'_>],
    matching_close: &[Option<usize>],
    for_at: usize,
) -> Option<(usize, usize, usize)> {
    if tokens.get(for_at).map(|token| token.text) != Some("for")
        || tokens.get(for_at + 1).map(|token| token.text) != Some("(")
    {
        return None;
    }
    let header_close = matching_close.get(for_at + 1).copied().flatten()?;
    let mut semis = Vec::new();
    let mut depth = 0i32;
    for (index, token) in tokens.iter().enumerate().take(header_close).skip(for_at + 2) {
        match token.text {
            "(" | "[" | "{" => depth += 1,
            ")" | "]" | "}" => depth -= 1,
            ";" if depth == 0 => semis.push(index),
            _ => {}
        }
    }
    if semis.len() != 2 {
        return None;
    }
    Some((header_close, semis[0], semis[1]))
}

fn is_unit_increment(tokens: &[Token<'_>], start: usize, end: usize, name: &str) -> bool {
    let span = &tokens[start..end];
    matches!(
        span,
        [name_tok, plusplus]
            if name_tok.text == name && plusplus.text == "++"
    ) || matches!(
        span,
        [plusplus, name_tok]
            if plusplus.text == "++" && name_tok.text == name
    )
}

fn cheap_literal_rhs(tokens: &[Token<'_>], start: usize, end: usize) -> bool {
    let span = &tokens[start..end];
    match span {
        [bang, digit] if bang.text == "!" && matches!(digit.text, "0" | "1") => true,
        [token]
            if matches!(
                token.text,
                "0" | "1" | "true" | "false" | "null" | "undefined"
            ) || token.kind == TokenKind::String =>
        {
            true
        }
        [open, close] if matches!((open.text, close.text), ("[", "]") | ("{", "}")) => true,
        _ => false,
    }
}

fn parse_bare_assign<'src>(
    source: &'src str,
    tokens: &[Token<'src>],
    at: usize,
) -> Option<(usize, &'src str, &'src str, usize)> {
    if !is_statement_boundary(tokens, at) || tokens.get(at)?.kind != TokenKind::Identifier {
        return None;
    }
    if tokens.get(at + 1).map(|token| token.text) != Some("=") {
        return None;
    }
    let semi = top_level_stop(tokens, at + 2, &[";"])?;
    Some((
        at,
        tokens[at].text,
        &source[tokens[at + 2].start..tokens[semi].start],
        semi + 1,
    ))
}

fn fold_chained_identifier_assigns(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 6 < tokens.len() {
        let Some((first_at, first_name, rhs, after_first)) =
            parse_bare_assign(source, &tokens, cursor)
        else {
            cursor += 1;
            continue;
        };
        if tokens.get(after_first).map(|token| token.kind) != Some(TokenKind::Identifier)
            || tokens.get(after_first + 1).map(|token| token.text) != Some("=")
            || tokens.get(after_first + 2).map(|token| token.text) != Some(first_name)
        {
            cursor += 1;
            continue;
        }
        let second_name = tokens[after_first].text;
        replacements.push((
            tokens[first_at].start,
            tokens[after_first + 2].end,
            format!("{second_name}={first_name}={rhs}"),
        ));
        cursor = after_first + 3;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_prefix_increment_for_bounds(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 8 < tokens.len() {
        if !is_statement_boundary(&tokens, cursor) {
            cursor += 1;
            continue;
        }
        let (name, inc_end) = if tokens[cursor].kind == TokenKind::Identifier
            && tokens.get(cursor + 1).map(|token| token.text) == Some("++")
            && tokens.get(cursor + 2).map(|token| token.text) == Some(";")
        {
            (tokens[cursor].text, cursor + 3)
        } else if tokens[cursor].text == "++"
            && tokens
                .get(cursor + 1)
                .is_some_and(|token| token.kind == TokenKind::Identifier)
            && tokens.get(cursor + 2).map(|token| token.text) == Some(";")
        {
            (tokens[cursor + 1].text, cursor + 3)
        } else {
            cursor += 1;
            continue;
        };
        let for_at = inc_end;
        let Some((header_close, first_semi, second_semi)) =
            for_header_semicolons(&tokens, &matching_close, for_at)
        else {
            cursor += 1;
            continue;
        };
        if first_semi != for_at + 2 {
            cursor += 1;
            continue;
        }
        if tokens.get(first_semi + 1).map(|token| token.text) != Some(name)
            || tokens.get(first_semi + 2).map(|token| token.text) != Some("<")
        {
            cursor += 1;
            continue;
        }
        if !is_unit_increment(&tokens, second_semi + 1, header_close, name) {
            cursor += 1;
            continue;
        }
        let bound = &source[tokens[first_semi + 3].start..tokens[second_semi].start];
        let bound = if expression_has_top_level_token(&tokens[first_semi + 3..second_semi], "&&")
            || expression_has_top_level_token(&tokens[first_semi + 3..second_semi], "||")
            || expression_has_top_level_token(&tokens[first_semi + 3..second_semi], "?")
            || expression_has_top_level_token(&tokens[first_semi + 3..second_semi], ",")
            || expression_has_top_level_token(&tokens[first_semi + 3..second_semi], "=")
        {
            format!("({bound})")
        } else {
            bound.to_string()
        };
        replacements.push((
            tokens[cursor].start,
            tokens[header_close].end,
            format!("for(;++{name}<{bound};)"),
        ));
        cursor = header_close + 1;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_increment_infinite_for_bounds(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 8 < tokens.len() {
        if !is_statement_boundary(&tokens, cursor) {
            cursor += 1;
            continue;
        }
        let (name, inc_end) = if tokens[cursor].kind == TokenKind::Identifier
            && tokens.get(cursor + 1).map(|token| token.text) == Some("++")
            && tokens.get(cursor + 2).map(|token| token.text) == Some(";")
        {
            (tokens[cursor].text, cursor + 3)
        } else if tokens[cursor].text == "++"
            && tokens
                .get(cursor + 1)
                .is_some_and(|token| token.kind == TokenKind::Identifier)
            && tokens.get(cursor + 2).map(|token| token.text) == Some(";")
        {
            (tokens[cursor + 1].text, cursor + 3)
        } else {
            cursor += 1;
            continue;
        };
        let for_at = inc_end;
        let Some((header_close, first_semi, second_semi)) =
            for_header_semicolons(&tokens, &matching_close, for_at)
        else {
            cursor += 1;
            continue;
        };
        if first_semi != for_at + 2
            || first_semi + 1 != second_semi
            || !is_unit_increment(&tokens, second_semi + 1, header_close, name)
        {
            cursor += 1;
            continue;
        }
        let body_at = header_close + 1;
        if tokens.get(body_at).map(|token| token.text) != Some("{") {
            cursor += 1;
            continue;
        }
        let Some(body_close) = matching_close.get(body_at).copied().flatten() else {
            cursor += 1;
            continue;
        };
        let mut scan = body_at + 1;
        let mut kept_prefix = "";
        if tokens.get(scan).map(|token| token.text) == Some("var")
            && tokens
                .get(scan + 1)
                .is_some_and(|token| token.kind == TokenKind::Identifier)
            && tokens.get(scan + 2).map(|token| token.text) == Some("=")
            && tokens.get(scan + 3).map(|token| token.text) == Some(name)
            && tokens.get(scan + 4).map(|token| token.text) == Some(";")
        {
            kept_prefix = &source[tokens[scan].start..tokens[scan + 4].end];
            scan += 5;
        }
        if tokens.get(scan).map(|token| token.text) != Some("if")
            || tokens.get(scan + 1).map(|token| token.text) != Some("(")
        {
            cursor += 1;
            continue;
        }
        let Some(if_close) = matching_close.get(scan + 1).copied().flatten() else {
            cursor += 1;
            continue;
        };
        let test = &tokens[scan + 2..if_close];
        let bound = if matches!(
            test,
            [ident, op, ..] if ident.text == name && op.text == ">="
        ) {
            &source[tokens[scan + 4].start..tokens[if_close].start]
        } else if test.len() >= 5
            && test[0].text == "!"
            && test[1].text == "("
            && test[2].text == name
            && test[3].text == "<"
            && test.last().is_some_and(|token| token.text == ")")
        {
            &source[test[4].start..test[test.len() - 1].start]
        } else {
            cursor += 1;
            continue;
        };
        let after_if = if tokens.get(if_close + 1).map(|token| token.text) == Some("break") {
            if tokens.get(if_close + 2).map(|token| token.text) == Some(";") {
                if_close + 3
            } else {
                if_close + 2
            }
        } else if tokens.get(if_close + 1).map(|token| token.text) == Some("{") {
            let Some(block_close) = matching_close.get(if_close + 1).copied().flatten() else {
                cursor += 1;
                continue;
            };
            if tokens.get(if_close + 2).map(|token| token.text) != Some("break") {
                cursor += 1;
                continue;
            }
            let after_break = if tokens.get(if_close + 3).map(|token| token.text) == Some(";") {
                if_close + 4
            } else {
                if_close + 3
            };
            if after_break != block_close {
                cursor += 1;
                continue;
            }
            block_close + 1
        } else {
            cursor += 1;
            continue;
        };
        let rest = &source[tokens[after_if].start..tokens[body_close].start];
        replacements.push((
            tokens[cursor].start,
            tokens[body_close].end,
            format!("for(;++{name}<{bound};){{{kept_prefix}{rest}}}"),
        ));
        cursor = body_close + 1;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn expression_statement_texts<'src>(
    source: &'src str,
    tokens: &[Token<'src>],
    start: usize,
    end: usize,
) -> Option<Vec<String>> {
    let mut index = start;
    let mut exprs = Vec::new();
    while index < end {
        if tokens[index].text == ";" {
            index += 1;
            continue;
        }
        if matches!(
            tokens[index].text,
            "if" | "for"
                | "while"
                | "var"
                | "let"
                | "const"
                | "function"
                | "return"
                | "switch"
                | "try"
                | "throw"
                | "class"
                | "do"
                | "break"
                | "continue"
                | "debugger"
        ) {
            return None;
        }
        let stop = top_level_stop(tokens, index, &[";"])
            .filter(|stop| *stop < end)
            .unwrap_or(end);
        if stop == index {
            return None;
        }
        let expr = source[tokens[index].start..tokens[stop].start].trim();
        if expr.is_empty() {
            return None;
        }
        exprs.push(expr.to_string());
        index = if stop < end { stop + 1 } else { end };
    }
    (!exprs.is_empty()).then_some(exprs)
}

fn fold_trailing_return_this(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    for open in 1..tokens.len() {
        if tokens[open].text != "{"
            || !matches!(tokens[open - 1].text, ")" | "=>")
        {
            continue;
        }
        let Some(close) = matching_close.get(open).copied().flatten() else {
            continue;
        };
        let mut end = close;
        if tokens.get(close - 1).map(|token| token.text) == Some(";") {
            end = close - 1;
        }
        if end < open + 3
            || tokens.get(end - 1).map(|token| token.text) != Some("this")
            || tokens.get(end - 2).map(|token| token.text) != Some("return")
        {
            continue;
        }
        let stmts_end = end - 2;
        if stmts_end == open + 1 {
            continue;
        }
        let prefix = if tokens.get(open + 1).map(|token| token.text) == Some("if")
            && tokens.get(open + 2).map(|token| token.text) == Some("(")
        {
            let Some(cond_close) = matching_close.get(open + 2).copied().flatten() else {
                continue;
            };
            let cond = &source[tokens[open + 3].start..tokens[cond_close].start];
            let (body_start, body_end) = if tokens.get(cond_close + 1).map(|token| token.text)
                == Some("{")
            {
                let Some(body_close) = matching_close.get(cond_close + 1).copied().flatten() else {
                    continue;
                };
                if body_close + 1 != stmts_end
                    && !(body_close + 2 == stmts_end
                        && tokens.get(body_close + 1).map(|token| token.text) == Some(";"))
                {
                    continue;
                }
                (cond_close + 2, body_close)
            } else {
                let Some(stop) = top_level_stop(&tokens, cond_close + 1, &[";"]) else {
                    continue;
                };
                if stop + 1 != stmts_end {
                    continue;
                }
                (cond_close + 1, stop)
            };
            let Some(exprs) = expression_statement_texts(source, &tokens, body_start, body_end)
            else {
                continue;
            };
            format!("{cond}&&({})", exprs.join(","))
        } else {
            let Some(exprs) = expression_statement_texts(source, &tokens, open + 1, stmts_end) else {
                continue;
            };
            if exprs.len() == 1 {
                exprs[0].clone()
            } else {
                exprs.join(",")
            }
        };
        replacements.push((
            tokens[open].start,
            tokens[close].end,
            format!("{{return {prefix},this}}"),
        ));
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_dead_initializer_reassigns(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 8 < tokens.len() {
        let decl = if matches!(tokens[cursor].text, "var" | "let")
            && tokens
                .get(cursor + 1)
                .is_some_and(|token| token.kind == TokenKind::Identifier)
        {
            Some((tokens[cursor].text, cursor + 1))
        } else {
            None
        };
        let Some((kind, name_at)) = decl else {
            cursor += 1;
            continue;
        };
        if tokens.get(name_at + 1).map(|token| token.text) != Some("=")
            || tokens
                .get(name_at + 2)
                .is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(name_at + 3).map(|token| token.text) != Some(";")
        {
            cursor += 1;
            continue;
        }
        let name = tokens[name_at].text;
        if tokens.get(name_at + 4).map(|token| token.text) != Some(name)
            || tokens.get(name_at + 5).map(|token| token.text) != Some("=")
        {
            cursor += 1;
            continue;
        }
        let Some(semi) = top_level_stop(&tokens, name_at + 6, &[";"]) else {
            cursor += 1;
            continue;
        };
        if identifier_occurs(&tokens, name_at + 6, semi, name) {
            cursor += 1;
            continue;
        }
        let rhs = &source[tokens[name_at + 6].start..tokens[semi].start];
        replacements.push((
            tokens[cursor].start,
            tokens[semi].end,
            format!("{kind} {name}={rhs};"),
        ));
        cursor = semi + 1;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_void_then_reassign(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 8 < tokens.len() {
        if !(is_statement_boundary(&tokens, cursor)
            || tokens
                .get(cursor.wrapping_sub(1))
                .is_some_and(|token| token.text == ","))
            || tokens[cursor].kind != TokenKind::Identifier
            || tokens.get(cursor + 1).map(|token| token.text) != Some("=")
            || tokens.get(cursor + 2).map(|token| token.text) != Some("void")
            || tokens.get(cursor + 3).map(|token| token.text) != Some("0")
            || tokens.get(cursor + 4).map(|token| token.text) != Some(";")
            || tokens.get(cursor + 5).map(|token| token.text) != Some(tokens[cursor].text)
            || tokens.get(cursor + 6).map(|token| token.text) != Some("=")
        {
            cursor += 1;
            continue;
        }
        replacements.push((tokens[cursor + 1].start, tokens[cursor + 6].start, String::new()));
        cursor += 7;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_single_use_index_temps(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 6 < tokens.len() {
        if tokens[cursor].kind != TokenKind::Identifier
            || tokens.get(cursor + 1).map(|token| token.text) != Some("=")
            || tokens
                .get(cursor + 2)
                .is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(cursor + 3).map(|token| token.text) != Some("[")
            || tokens.get(cursor + 4).is_none_or(|token| {
                token.kind != TokenKind::Identifier && token.kind != TokenKind::Number
            })
            || tokens.get(cursor + 5).map(|token| token.text) != Some("]")
            || !matches!(
                tokens.get(cursor + 6).map(|token| token.text),
                Some(";") | Some(",") | Some("}") | None
            )
            || !matches!(
                cursor
                    .checked_sub(1)
                    .map(|index| tokens[index].text)
                    .unwrap_or(";"),
                ";" | "{" | "}" | "let" | "var" | "const" | ","
            )
        {
            cursor += 1;
            continue;
        }
        let name = tokens[cursor].text;
        let rhs = source[tokens[cursor + 2].start..tokens[cursor + 5].end].to_string();
        let rhs_end = cursor + 5;
        let object = tokens[cursor + 2].text;
        let scope_end = enclosing_block_end(&matching_close, cursor).unwrap_or(tokens.len());
        let mut reads = Vec::new();
        let mut scan = rhs_end + 1;
        if matches!(
            tokens.get(scan).map(|token| token.text),
            Some(";") | Some(",")
        ) {
            scan += 1;
        }
        let mut safe = true;
        while scan < scope_end {
            if let Some(close) = nested_function_end(&tokens, &matching_close, scan) {
                scan = close + 1;
                continue;
            }
            if tokens[scan].kind == TokenKind::Identifier && tokens[scan].text == name {
                if tokens.get(scan + 1).map(|token| token.text) == Some("=")
                    && tokens.get(scan + 2).map(|token| token.text) != Some("=")
                    || matches!(
                        tokens.get(scan + 1).map(|token| token.text),
                        Some("++") | Some("--")
                    )
                    || matches!(
                        tokens.get(scan.wrapping_sub(1)).map(|token| token.text),
                        Some("++") | Some("--") | Some("[")
                    )
                {
                    safe = false;
                    break;
                }
                reads.push(scan);
            }
            if tokens[scan].kind == TokenKind::Identifier
                && tokens[scan].text == object
                && tokens.get(scan + 1).map(|token| token.text) == Some("=")
                && tokens.get(scan + 2).map(|token| token.text) != Some("=")
            {
                safe = false;
                break;
            }
            scan += 1;
        }
        if !safe || reads.len() != 1 {
            cursor += 1;
            continue;
        }
        let (from, to) = assignment_span_to_remove(&tokens, cursor, rhs_end);
        replacements.push((from, to, String::new()));
        replacements.push((tokens[reads[0]].start, tokens[reads[0]].end, rhs));
        cursor = rhs_end + 1;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count / 2 + count % 2))
}

fn fold_assigned_index_for_conditions(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    for for_at in 0..tokens.len() {
        let Some((header_close, first_semi, second_semi)) =
            for_header_semicolons(&tokens, &matching_close, for_at)
        else {
            continue;
        };
        let cond = &tokens[first_semi + 1..second_semi];
        let always = matches!(cond, [bang, zero] if bang.text == "!" && zero.text == "0")
            || matches!(cond, [token] if token.text == "true");
        if !always {
            continue;
        }
        let body_at = header_close + 1;
        if tokens.get(body_at).map(|token| token.text) != Some("{") {
            continue;
        }
        let Some(body_close) = matching_close.get(body_at).copied().flatten() else {
            continue;
        };
        if tokens.get(body_at + 1).map(|token| token.kind) != Some(TokenKind::Identifier)
            || tokens.get(body_at + 2).map(|token| token.text) != Some("=")
        {
            continue;
        }
        let name = tokens[body_at + 1].text;
        let Some(assign_semi) = top_level_stop(&tokens, body_at + 3, &[";"]) else {
            continue;
        };
        let if_at = assign_semi + 1;
        if tokens.get(if_at).map(|token| token.text) != Some("if")
            || tokens.get(if_at + 1).map(|token| token.text) != Some("(")
        {
            continue;
        }
        let Some(if_close) = matching_close.get(if_at + 1).copied().flatten() else {
            continue;
        };
        let test = &tokens[if_at + 2..if_close];
        let new_cond = if matches!(
            test,
            [ident, lt, zero]
                if ident.text == name && lt.text == "<" && zero.text == "0"
        ) || matches!(
            test,
            [bang, open, ident, gt, minus, one, close]
                if bang.text == "!"
                    && open.text == "("
                    && ident.text == name
                    && gt.text == ">"
                    && minus.text == "-"
                    && one.text == "1"
                    && close.text == ")"
        ) {
            format!(
                "({name}={})>-1",
                &source[tokens[body_at + 3].start..tokens[assign_semi].start]
            )
        } else {
            continue;
        };
        let after_if = if tokens.get(if_close + 1).map(|token| token.text) == Some("break") {
            if tokens.get(if_close + 2).map(|token| token.text) == Some(";") {
                if_close + 3
            } else {
                if_close + 2
            }
        } else if tokens.get(if_close + 1).map(|token| token.text) == Some("{") {
            let Some(block_close) = matching_close.get(if_close + 1).copied().flatten() else {
                continue;
            };
            if tokens.get(if_close + 2).map(|token| token.text) != Some("break") {
                continue;
            }
            let after_break = if tokens.get(if_close + 3).map(|token| token.text) == Some(";") {
                if_close + 4
            } else {
                if_close + 3
            };
            if after_break != block_close {
                continue;
            }
            block_close + 1
        } else {
            continue;
        };
        let init = elide_zero_for_init(
            &source[tokens[for_at + 2].start..tokens[first_semi].start],
            name,
        );
        let inc = &source[tokens[second_semi].end..tokens[header_close].start];
        let rest = &source[tokens[after_if].start..tokens[body_close].start];
        replacements.push((
            tokens[for_at].start,
            tokens[body_close].end,
            format!("for({init};{new_cond};{inc}){{{rest}}}"),
        ));
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn elide_zero_for_init(init: &str, name: &str) -> String {
    let trimmed = init.trim();
    for decl in ["var ", "let "] {
        if let Some(rest) = trimmed.strip_prefix(decl) {
            if rest == format!("{name}=0") || rest == format!("{name}=0.0") {
                return format!("{decl}{name}");
            }
        }
    }
    if trimmed == format!("{name}=0") || trimmed == format!("{name}=0.0") {
        return String::new();
    }
    init.to_string()
}

fn fold_index_scan_for_headers(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    for for_at in 0..tokens.len() {
        let Some((header_close, first_semi, second_semi)) =
            for_header_semicolons(&tokens, &matching_close, for_at)
        else {
            continue;
        };
        let init = &tokens[for_at + 2..first_semi];
        let (decl, name, zero_init) = match init {
            [decl, ident, eq, zero]
                if matches!(decl.text, "var" | "let")
                    && ident.kind == TokenKind::Identifier
                    && eq.text == "="
                    && zero.text == "0" =>
            {
                (decl.text, ident.text, true)
            }
            [decl, ident]
                if matches!(decl.text, "var" | "let") && ident.kind == TokenKind::Identifier =>
            {
                (decl.text, ident.text, false)
            }
            _ => continue,
        };
        if tokens.get(first_semi + 1).map(|token| token.text) != Some("(")
            || tokens.get(first_semi + 2).map(|token| token.text) != Some(name)
            || tokens.get(first_semi + 3).map(|token| token.text) != Some("=")
        {
            continue;
        }
        let Some(paren_close) = matching_close.get(first_semi + 1).copied().flatten() else {
            continue;
        };
        if paren_close >= second_semi {
            continue;
        }
        let after = &tokens[paren_close + 1..second_semi];
        let ge_zero = matches!(after, [op, zero] if op.text == ">=" && zero.text == "0");
        let gt_minus1 = matches!(
            after,
            [gt, minus, one] if gt.text == ">" && minus.text == "-" && one.text == "1"
        ) || matches!(
            after,
            [gt, num] if gt.text == ">" && num.text == "-1"
        );
        if !ge_zero && !gt_minus1 || !zero_init && !ge_zero {
            continue;
        }
        let assign = &source[tokens[first_semi + 1].start..tokens[paren_close].end];
        let inc = &source[tokens[second_semi].end..tokens[header_close].start];
        replacements.push((
            tokens[for_at].start,
            tokens[header_close].end,
            format!("for({decl} {name};{assign}>-1;{inc})"),
        ));
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_void_prefix_updates(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 1 < tokens.len() {
        if tokens[cursor].text == "--"
            && tokens[cursor + 1].kind == TokenKind::Identifier
            && matches!(
                tokens.get(cursor + 2).map(|token| token.text),
                Some(";") | Some(",") | Some("}") | None
            )
            && matches!(
                cursor
                    .checked_sub(1)
                    .map(|index| tokens[index].text)
                    .unwrap_or(";"),
                "&&" | "||" | "," | ";" | "{"
            )
        {
            replacements.push((
                tokens[cursor].start,
                tokens[cursor + 1].end,
                format!("{}--", tokens[cursor + 1].text),
            ));
            cursor += 2;
            continue;
        }
        cursor += 1;
    }
    Ok(apply_token_rewrites(source, replacements))
}

fn fold_boolean_context_double_not(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 4 < tokens.len() {
        if !matches!(tokens[cursor].text, "&&" | "||")
            || tokens.get(cursor + 1).map(|token| token.text) != Some("!")
            || tokens.get(cursor + 2).map(|token| token.text) != Some("!")
        {
            cursor += 1;
            continue;
        }
        let Some(stop) = top_level_stop(&tokens, cursor + 3, &["&&", "||", ";", ",", ")", "]", "}"])
        else {
            cursor += 1;
            continue;
        };
        if !matches!(tokens[stop].text, "&&" | "||") {
            cursor += 1;
            continue;
        }
        replacements.push((tokens[cursor + 1].start, tokens[cursor + 3].start, String::new()));
        cursor = stop;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_redundant_loop_body_braces(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    for index in 0..tokens.len() {
        if !matches!(tokens[index].text, "for" | "while")
            || tokens.get(index + 1).map(|token| token.text) != Some("(")
        {
            continue;
        }
        let Some(header_close) = matching_close.get(index + 1).copied().flatten() else {
            continue;
        };
        if tokens.get(header_close + 1).map(|token| token.text) != Some("{") {
            continue;
        }
        let body_open = header_close + 1;
        let Some(body_close) = matching_close.get(body_open).copied().flatten() else {
            continue;
        };
        if body_close <= body_open + 1 {
            continue;
        }
        let mut body_end = body_close;
        if tokens.get(body_close - 1).map(|token| token.text) == Some(";") {
            body_end = body_close - 1;
        }
        if !safe_braceless_loop_body(&tokens, body_open + 1, body_end) {
            continue;
        }
        let body = source[tokens[body_open + 1].start..tokens[body_end].start].trim();
        if body.is_empty() {
            continue;
        }
        replacements.push((
            tokens[body_open].start,
            tokens[body_close].end,
            format!("{body};"),
        ));
    }
    Ok(apply_token_rewrites(source, replacements))
}

fn safe_braceless_loop_body(tokens: &[Token<'_>], start: usize, end: usize) -> bool {
    if start >= end {
        return false;
    }
    if matches!(
        tokens[start].text,
        "if" | "else"
            | "var"
            | "let"
            | "const"
            | "function"
            | "class"
            | "return"
            | "throw"
            | "try"
            | "switch"
            | "with"
            | "do"
    ) {
        return false;
    }
    if matches!(tokens[start].text, "for" | "while") {
        if tokens.get(start + 1).map(|token| token.text) != Some("(") {
            return false;
        }
        let matching_close = matching_closers(tokens);
        let Some(header_close) = matching_close.get(start + 1).copied().flatten() else {
            return false;
        };
        if header_close >= end {
            return false;
        }
        let rest = header_close + 1;
        if rest >= end {
            return false;
        }
        if tokens[rest].text == "{" {
            return false;
        }
        return safe_braceless_loop_body(tokens, rest, end);
    }
    let mut depth = 0i32;
    for token in &tokens[start..end] {
        match token.text {
            "(" | "[" | "{" => depth += 1,
            ")" | "]" | "}" => depth -= 1,
            ";" if depth == 0 => return false,
            _ => {}
        }
        if depth < 0 {
            return false;
        }
    }
    depth == 0
}

fn fold_statement_negated_ors(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 4 < tokens.len() {
        if !is_statement_boundary(&tokens, cursor)
            || tokens[cursor].text != "!"
            || tokens
                .get(cursor + 1)
                .is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(cursor + 2).map(|token| token.text) != Some("||")
            || tokens.get(cursor + 3).map(|token| token.text) != Some("(")
        {
            cursor += 1;
            continue;
        }
        let name = tokens[cursor + 1].text;
        let Some(close) = matching_close.get(cursor + 3).copied().flatten() else {
            cursor += 1;
            continue;
        };
        if !statement_follows_paren(&tokens, close) {
            cursor += 1;
            continue;
        }
        let rhs = &source[tokens[cursor + 4].start..tokens[close].start];
        let end_at = if tokens.get(close + 1).map(|token| token.text) == Some(";") {
            close + 1
        } else {
            close
        };
        replacements.push((
            tokens[cursor].start,
            tokens[end_at].end,
            format!("{name}&&({rhs});"),
        ));
        cursor = end_at + 1;
    }
    Ok(apply_token_rewrites(source, replacements))
}

fn fold_chained_comma_assigns(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 6 < tokens.len() {
        if !matches!(
            cursor
                .checked_sub(1)
                .map(|index| tokens[index].text)
                .unwrap_or(";"),
            "(" | ","
        ) || tokens[cursor].kind != TokenKind::Identifier
            || tokens.get(cursor + 1).map(|token| token.text) != Some("=")
        {
            cursor += 1;
            continue;
        }
        let Some(comma) = top_level_stop(&tokens, cursor + 2, &[","]) else {
            cursor += 1;
            continue;
        };
        if tokens.get(comma + 1).is_none_or(|token| token.kind != TokenKind::Identifier)
            || tokens.get(comma + 2).map(|token| token.text) != Some("=")
            || tokens.get(comma + 3).map(|token| token.text) != Some(tokens[cursor].text)
            || !matches!(
                tokens.get(comma + 4).map(|token| token.text),
                Some(")") | Some(",") | Some(";")
            )
        {
            cursor += 1;
            continue;
        }
        let rhs = &source[tokens[cursor + 2].start..tokens[comma].start];
        let other = tokens[comma + 1].text;
        let first = tokens[cursor].text;
        replacements.push((
            tokens[cursor].start,
            tokens[comma + 3].end,
            format!("{other}={first}={rhs}"),
        ));
        cursor = comma + 4;
    }
    Ok(apply_token_rewrites(source, replacements))
}

fn fold_adjacent_expression_statements(
    source: &str,
) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut depth_paren = 0i32;
    let mut depth_brace = 0i32;
    let mut for_header_depth = 0i32;
    for (index, token) in tokens.iter().enumerate() {
        match token.text {
            "(" | "[" => {
                depth_paren += 1;
                if token.text == "("
                    && index > 0
                    && tokens[index - 1].text == "for"
                    && for_header_depth == 0
                {
                    for_header_depth = depth_paren;
                }
            }
            ")" | "]" => {
                if token.text == ")" && depth_paren == for_header_depth {
                    for_header_depth = 0;
                }
                depth_paren -= 1;
            }
            "{" => depth_brace += 1,
            "}" => depth_brace -= 1,
            ";" if depth_brace > 0 && (for_header_depth == 0 || depth_paren < for_header_depth) => {
                let left_start = previous_statement_start(&tokens, index);
                let right_end = next_statement_end(&tokens, index + 1);
                if is_expression_statement_span(&tokens, left_start, index)
                    && is_expression_statement_span(&tokens, index + 1, right_end)
                {
                    replacements.push((token.start, token.end, ",".to_string()));
                }
            }
            _ => {}
        }
    }
    Ok(apply_token_rewrites(source, replacements))
}

fn previous_statement_start(tokens: &[Token<'_>], semi: usize) -> usize {
    let mut depth_paren = 0i32;
    let mut depth_brace = 0i32;
    let mut index = semi;
    while index > 0 {
        index -= 1;
        match tokens[index].text {
            ")" | "]" => depth_paren += 1,
            "(" | "[" => depth_paren -= 1,
            "}" => depth_brace += 1,
            "{" => {
                if depth_brace == 0 && depth_paren == 0 {
                    return index + 1;
                }
                depth_brace -= 1;
            }
            ";" if depth_paren == 0 && depth_brace == 0 => return index + 1,
            _ => {}
        }
    }
    0
}

fn next_statement_end(tokens: &[Token<'_>], start: usize) -> usize {
    let mut depth_paren = 0i32;
    let mut depth_brace = 0i32;
    for index in start..tokens.len() {
        match tokens[index].text {
            "(" | "[" => depth_paren += 1,
            ")" | "]" => depth_paren -= 1,
            "{" => depth_brace += 1,
            "}" => {
                if depth_brace == 0 && depth_paren == 0 {
                    return index;
                }
                depth_brace -= 1;
            }
            ";" if depth_paren == 0 && depth_brace == 0 => return index,
            _ => {}
        }
    }
    tokens.len()
}

fn is_expression_statement_span(tokens: &[Token<'_>], start: usize, end: usize) -> bool {
    let start = (start..end)
        .find(|&index| tokens[index].text != ";")
        .unwrap_or(end);
    if start >= end {
        return false;
    }
    !matches!(
        tokens[start].text,
        "if" | "else"
            | "for"
            | "while"
            | "var"
            | "let"
            | "const"
            | "function"
            | "class"
            | "return"
            | "throw"
            | "try"
            | "switch"
            | "do"
            | "with"
            | "break"
            | "continue"
            | "debugger"
    )
}

fn fold_statement_or_assigns(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor < tokens.len() {
        if !is_statement_boundary(&tokens, cursor) {
            cursor += 1;
            continue;
        }
        if let Some((start, end, replacement, next)) =
            statement_or_assign_rewrite(source, &tokens, &matching_close, cursor)
        {
            replacements.push((start, end, replacement));
            cursor = next;
            continue;
        }
        cursor += 1;
    }
    Ok(apply_token_rewrites(source, replacements))
}

fn statement_or_assign_rewrite(
    source: &str,
    tokens: &[Token<'_>],
    matching_close: &[Option<usize>],
    cursor: usize,
) -> Option<(usize, usize, String, usize)> {
    if tokens[cursor].text == "!"
        && tokens.get(cursor + 1).is_some_and(|token| token.kind == TokenKind::Identifier)
        && tokens.get(cursor + 2).map(|token| token.text) == Some("&&")
        && tokens.get(cursor + 3).map(|token| token.text) == Some("(")
    {
        let name = tokens[cursor + 1].text;
        let close = matching_close.get(cursor + 3).copied().flatten()?;
        if tokens.get(cursor + 4).map(|token| token.text) == Some(name)
            && tokens.get(cursor + 5).map(|token| token.text) == Some("=")
            && statement_follows_paren(tokens, close)
        {
            let rhs = &source[tokens[cursor + 6].start..tokens[close].start];
            let end_at = if tokens.get(close + 1).map(|token| token.text) == Some(";") {
                close + 1
            } else {
                close
            };
            return Some((
                tokens[cursor].start,
                tokens[end_at].end,
                format!("{name}={name}||{rhs};"),
                end_at + 1,
            ));
        }
    }
    if tokens[cursor].kind == TokenKind::Identifier
        && tokens.get(cursor + 1).map(|token| token.text) == Some("||")
        && tokens.get(cursor + 2).map(|token| token.text) == Some("(")
    {
        let name = tokens[cursor].text;
        let close = matching_close.get(cursor + 2).copied().flatten()?;
        if tokens.get(cursor + 3).map(|token| token.text) == Some(name)
            && tokens.get(cursor + 4).map(|token| token.text) == Some("=")
            && statement_follows_paren(tokens, close)
        {
            let rhs = &source[tokens[cursor + 5].start..tokens[close].start];
            let end_at = if tokens.get(close + 1).map(|token| token.text) == Some(";") {
                close + 1
            } else {
                close
            };
            return Some((
                tokens[cursor].start,
                tokens[end_at].end,
                format!("{name}={name}||{rhs};"),
                end_at + 1,
            ));
        }
    }
    if tokens[cursor].text != "if" || tokens.get(cursor + 1).map(|token| token.text) != Some("(") {
        return None;
    }
    let cond_close = matching_close.get(cursor + 1).copied().flatten()?;
    if tokens.get(cursor + 2).map(|token| token.text) != Some("!")
        || tokens
            .get(cursor + 3)
            .is_none_or(|token| token.kind != TokenKind::Identifier)
        || cond_close != cursor + 4
    {
        return None;
    }
    let name = tokens[cursor + 3].text;
    let after = cond_close + 1;
    if tokens.get(after).map(|token| token.text) == Some(name)
        && tokens.get(after + 1).map(|token| token.text) == Some("=")
    {
        let semi = top_level_stop(tokens, after + 2, &[";"])?;
        if tokens.get(semi + 1).map(|token| token.text) == Some("else") {
            return None;
        }
        let rhs = &source[tokens[after + 2].start..tokens[semi].start];
        return Some((
            tokens[cursor].start,
            tokens[semi].end,
            format!("{name}={name}||{rhs};"),
            semi + 1,
        ));
    }
    if tokens.get(after).map(|token| token.text) != Some("{") {
        return None;
    }
    let block_close = matching_close.get(after).copied().flatten()?;
    if tokens.get(block_close + 1).map(|token| token.text) == Some("else") {
        return None;
    }
    if tokens.get(after + 1).map(|token| token.text) == Some(name)
        && tokens.get(after + 2).map(|token| token.text) == Some("=")
    {
        let semi = top_level_stop(tokens, after + 3, &[";"])?;
        let after_assign = if tokens.get(semi).map(|token| token.text) == Some(";") {
            semi + 1
        } else {
            semi
        };
        if after_assign != block_close {
            return None;
        }
        let rhs = &source[tokens[after + 3].start..tokens[semi].start];
        return Some((
            tokens[cursor].start,
            tokens[block_close].end,
            format!("{name}={name}||{rhs};"),
            block_close + 1,
        ));
    }
    if tokens.get(after + 1).map(|token| token.text) != Some("var")
        || tokens
            .get(after + 2)
            .is_none_or(|token| token.kind != TokenKind::Identifier)
        || tokens.get(after + 3).map(|token| token.text) != Some("=")
    {
        return None;
    }
    let temp = tokens[after + 2].text;
    let first_semi = top_level_stop(tokens, after + 4, &[";"])?;
    if tokens.get(first_semi + 1).map(|token| token.text) != Some(name)
        || tokens.get(first_semi + 2).map(|token| token.text) != Some("=")
        || tokens.get(first_semi + 3).map(|token| token.text) != Some(temp)
    {
        return None;
    }
    let after_copy = if tokens.get(first_semi + 4).map(|token| token.text) == Some(";") {
        first_semi + 5
    } else {
        first_semi + 4
    };
    if after_copy != block_close {
        return None;
    }
    let rhs = &source[tokens[after + 4].start..tokens[first_semi].start];
    Some((
        tokens[cursor].start,
        tokens[block_close].end,
        format!("{name}={name}||{rhs};"),
        block_close + 1,
    ))
}

fn statement_follows_paren(tokens: &[Token<'_>], close: usize) -> bool {
    matches!(
        tokens.get(close + 1).map(|token| token.text),
        Some(";") | Some("}") | None
    )
}

fn fold_prior_assign_into_for_init(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0usize;
    while cursor + 8 < tokens.len() {
        let mut assigns = Vec::new();
        let mut scan = cursor;
        while let Some(assign) = parse_bare_assign(source, &tokens, scan) {
            assigns.push(assign);
            scan = assign.3;
        }
        if !assigns.is_empty() {
            if let Some((header_close, first_semi, _)) =
                for_header_semicolons(&tokens, &matching_close, scan)
            {
                let init_empty = first_semi == scan + 2;
                let init_starts_decl = matches!(
                    tokens.get(scan + 2).map(|token| token.text),
                    Some("var") | Some("let") | Some("const")
                );
                if init_empty {
                    let init_parts = assigns
                        .iter()
                        .map(|(_, name, rhs, _)| format!("{name}={rhs}"))
                        .collect::<Vec<_>>();
                    let rest = &source[tokens[first_semi].start..tokens[header_close].end];
                    replacements.push((
                        tokens[assigns[0].0].start,
                        tokens[header_close].end,
                        format!("for({}{rest}", init_parts.join(",")),
                    ));
                    cursor = header_close + 1;
                    continue;
                }
                if !init_starts_decl {
                    let init_start = scan + 2;
                    let first_init = if tokens[init_start].kind == TokenKind::Identifier
                        && tokens.get(init_start + 1).map(|token| token.text) == Some("=")
                    {
                        top_level_stop(&tokens, init_start + 2, &[",", ";"]).and_then(|rhs_end| {
                            cheap_literal_rhs(&tokens, init_start + 2, rhs_end).then(|| {
                                (
                                    tokens[init_start].text,
                                    &source[tokens[init_start + 2].start..tokens[rhs_end].start],
                                    rhs_end,
                                )
                            })
                        })
                    } else {
                        None
                    };
                    if let Some((init_name, init_rhs, rhs_end)) = first_init {
                        if let Some((_, last_name, last_rhs, _)) = assigns.last() {
                            if *last_rhs == init_rhs {
                                let mut init_parts = assigns
                                    .iter()
                                    .map(|(_, name, rhs, _)| format!("{name}={rhs}"))
                                    .collect::<Vec<_>>();
                                init_parts.pop();
                                init_parts.push(format!("{last_name}={init_name}={init_rhs}"));
                                let rest = &source[tokens[rhs_end].start..tokens[header_close].end];
                                replacements.push((
                                    tokens[assigns[0].0].start,
                                    tokens[header_close].end,
                                    format!("for({}{rest}", init_parts.join(",")),
                                ));
                                cursor = header_close + 1;
                                continue;
                            }
                        }
                    }
                }
            }
        }

        let (decl, name_at) = if matches!(tokens[cursor].text, "var" | "let")
            && tokens
                .get(cursor + 1)
                .is_some_and(|token| token.kind == TokenKind::Identifier)
        {
            (format!("{} ", tokens[cursor].text), cursor + 1)
        } else if tokens[cursor].kind == TokenKind::Identifier {
            (String::new(), cursor)
        } else {
            cursor += 1;
            continue;
        };
        if !is_statement_boundary(&tokens, cursor)
            || tokens.get(name_at + 1).map(|token| token.text) != Some("=")
        {
            cursor += 1;
            continue;
        }
        let Some(semi) = top_level_stop(&tokens, name_at + 2, &[";"]) else {
            cursor += 1;
            continue;
        };
        if tokens.get(semi + 1).map(|token| token.text) != Some("for")
            || tokens.get(semi + 2).map(|token| token.text) != Some("(")
            || tokens.get(semi + 3).map(|token| token.text) != Some(";")
        {
            cursor += 1;
            continue;
        }
        let Some(header_close) = matching_close.get(semi + 2).copied().flatten() else {
            cursor += 1;
            continue;
        };
        let rest = &source[tokens[semi + 3].start..tokens[header_close].end];
        let init = &source[tokens[name_at].start..tokens[semi].start];
        replacements.push((
            tokens[cursor].start,
            tokens[header_close].end,
            format!("for({decl}{init}{rest}"),
        ));
        cursor = header_close + 1;
    }
    let (output, count) = apply_token_rewrites(source, replacements);
    Ok((output, count))
}

fn fold_arrow_guard_returns(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut matching_close = vec![None; tokens.len()];
    let mut stack = Vec::<usize>::new();
    for (index, token) in tokens.iter().enumerate() {
        match token.text {
            "(" | "[" | "{" => stack.push(index),
            ")" | "]" | "}" => {
                let Some(open) = stack.pop() else {
                    continue;
                };
                matching_close[open] = Some(index);
            }
            _ => {}
        }
    }

    let mut replacements = Vec::new();
    for body_open in 1..tokens.len() {
        if tokens[body_open].text != "{" || tokens[body_open - 1].text != "=>" {
            continue;
        }
        let Some(body_close) = matching_close[body_open] else {
            continue;
        };
        let if_index = body_open + 1;
        if tokens.get(if_index).map(|token| token.text) != Some("if")
            || tokens.get(if_index + 1).map(|token| token.text) != Some("(")
        {
            continue;
        }
        let condition_open = if_index + 1;
        let Some(condition_close) = matching_close[condition_open] else {
            continue;
        };
        let first_return = condition_close + 1;
        if tokens.get(first_return).map(|token| token.text) != Some("return") {
            continue;
        }
        let mut delimiters = Vec::<&str>::new();
        let mut first_semicolon = None;
        for (index, token) in tokens
            .iter()
            .enumerate()
            .take(body_close)
            .skip(first_return + 1)
        {
            match token.text {
                "(" | "[" | "{" => delimiters.push(token.text),
                ")" | "]" | "}" => {
                    delimiters.pop();
                }
                ";" if delimiters.is_empty() => {
                    first_semicolon = Some(index);
                    break;
                }
                _ => {}
            }
        }
        let Some(first_semicolon) = first_semicolon else {
            continue;
        };
        let second_return = first_semicolon + 1;
        if tokens.get(second_return).map(|token| token.text) != Some("return")
            || second_return + 1 >= body_close
        {
            continue;
        }
        let second_end = if tokens[body_close - 1].text == ";" {
            body_close - 1
        } else {
            body_close
        };
        if second_return + 1 >= second_end {
            continue;
        }

        let condition = &source[tokens[condition_open].end..tokens[condition_close].start];
        let condition =
            if conditional_test_needs_grouping(&tokens[condition_open + 1..condition_close]) {
                format!("({condition})")
            } else {
                condition.to_string()
            };
        // Bare `return;` is a value-producing `undefined` arm once the two
        // returns become one conditional expression. Never leave an empty
        // grammar arm (`condition?:value`) in a codec-scored candidate.
        let first = if first_return + 1 == first_semicolon {
            "void 0".to_string()
        } else {
            let first = &source[tokens[first_return + 1].start..tokens[first_semicolon].start];
            if expression_has_top_level_token(&tokens[first_return + 1..first_semicolon], ",") {
                format!("({first})")
            } else {
                first.to_string()
            }
        };
        let second = &source[tokens[second_return + 1].start..tokens[second_end].start];
        let second = if expression_has_top_level_token(&tokens[second_return + 1..second_end], ",")
        {
            format!("({second})")
        } else {
            second.to_string()
        };
        let replacement = format!("{condition}?{first}:{second}");
        let start = tokens[body_open].start;
        let end = tokens[body_close].end;
        if replacement.len() < end - start {
            replacements.push((start, end, replacement));
        }
    }
    if replacements.is_empty() {
        return Ok((source.to_string(), 0));
    }
    // Nested candidates overlap; prefer the outermost non-overlapping set so
    // the largest guard/body wrapper disappears in this bounded pass.
    replacements.sort_unstable_by_key(|(start, end, _)| (*start, *end));
    let mut retained = Vec::new();
    let mut last_end = 0;
    for replacement in replacements {
        if replacement.0 >= last_end {
            last_end = replacement.1;
            retained.push(replacement);
        }
    }
    let count = retained.len();
    let mut output = source.to_string();
    for (start, end, replacement) in retained.into_iter().rev() {
        output.replace_range(start..end, &replacement);
    }
    Ok((output, count))
}

fn conditional_test_needs_grouping(tokens: &[Token<'_>]) -> bool {
    let mut depth = 0usize;
    for token in tokens {
        match token.text {
            "(" | "[" | "{" => depth += 1,
            ")" | "]" | "}" => depth = depth.saturating_sub(1),
            "," | "?" | "=" | "+=" | "-=" | "*=" | "/=" | "%=" | "&=" | "|=" | "^=" | "<<="
            | ">>=" | ">>>="
                if depth == 0 =>
            {
                return true;
            }
            _ => {}
        }
    }
    false
}

fn expression_has_top_level_token(tokens: &[Token<'_>], expected: &str) -> bool {
    let mut depth = 0usize;
    for token in tokens {
        match token.text {
            "(" | "[" | "{" => depth += 1,
            ")" | "]" | "}" => depth = depth.saturating_sub(1),
            token if token == expected && depth == 0 => return true,
            _ => {}
        }
    }
    false
}

/// Index of the token that ends the statement starting at `start`, and whether
/// that token is the statement's own `;` rather than the enclosing block's `}`.
fn statement_terminator(tokens: &[Token<'_>], start: usize) -> Option<(usize, bool)> {
    let mut depth = 0usize;
    for (index, token) in tokens.iter().enumerate().skip(start) {
        match token.text {
            "(" | "[" | "{" => depth += 1,
            ")" | "]" | "}" => {
                if depth == 0 {
                    return Some((index, false));
                }
                depth -= 1;
            }
            ";" if depth == 0 => return Some((index, true)),
            _ => {}
        }
    }
    None
}

/// A `return` argument spelled as one conditional arm.
///
/// An absent argument is `undefined` once the two returns become one
/// expression, and a top-level comma binds looser than a conditional arm.
fn conditional_return_arm(source: &str, tokens: &[Token<'_>], start: usize, end: usize) -> String {
    if start >= end {
        return "void 0".to_string();
    }
    let text = &source[tokens[start].start..tokens[end - 1].end];
    if expression_has_top_level_token(&tokens[start..end], ",") {
        format!("({text})")
    } else {
        text.to_string()
    }
}

fn spans_line_terminator(source: &str) -> bool {
    source.contains(['\n', '\r', '\u{2028}', '\u{2029}'])
}

/// Collapse a guarded return and the return that follows it into a single
/// conditional return.
///
/// `if(C)return A;return B` and `return C?A:B` evaluate `C`, then exactly one
/// of `A` or `B`, and complete with the same value. Nothing else can run
/// between them: the guarded arm returns, so the following statement is
/// reached exactly when `C` is falsy.
///
/// The `if` must be a statement of the enclosing block. An `if` that is the
/// unbraced body of a loop or a labelled statement is refused, because the
/// fused return would then leave the loop on the first iteration instead of
/// continuing it. An `else` arm is refused implicitly: the token after the
/// guarded return is then `else` rather than `return`.
///
/// Longer ladders collapse one level per round, from the tail inward, so
/// `if(C1)return A;if(C2)return B;return C` reaches `return C1?A:C2?B:C`
/// through the right-associative spelling with no added parentheses.
fn fold_conditional_return_tails(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let mut output = source.to_string();
    let mut folded = 0usize;
    loop {
        let Some(tokens) = lex_certainly(&output)? else {
            return Ok((output, folded));
        };
        let matching_close = matching_closers(&tokens);
        let mut replacements = Vec::<(usize, usize, String)>::new();

        for guard in 0..tokens.len() {
            if tokens[guard].text != "if" {
                continue;
            }
            let condition_open = guard + 1;
            if tokens.get(condition_open).map(|token| token.text) != Some("(") {
                continue;
            }
            let Some(condition_close) = matching_close[condition_open] else {
                continue;
            };

            // The guarded arm is a lone `return`, either bare or braced.
            let braced = tokens.get(condition_close + 1).map(|token| token.text) == Some("{");
            let guarded_return = if braced {
                condition_close + 2
            } else {
                condition_close + 1
            };
            if tokens.get(guarded_return).map(|token| token.text) != Some("return") {
                continue;
            }
            let Some((guarded_end, _)) = statement_terminator(&tokens, guarded_return + 1) else {
                continue;
            };
            let next_statement = if braced {
                let Some(brace_close) = matching_close[condition_close + 1] else {
                    continue;
                };
                // Exactly one statement inside the braces, with at most a
                // trailing `;`.
                if guarded_end != brace_close
                    && !(guarded_end + 1 == brace_close && tokens[guarded_end].text == ";")
                {
                    continue;
                }
                brace_close + 1
            } else {
                if tokens[guarded_end].text != ";" {
                    continue;
                }
                guarded_end + 1
            };
            // An `else` arm belongs to this `if`, so the fused return replaces
            // one whole statement with one whole statement and may sit
            // wherever the `if` did. A fall-through tail is a separate
            // statement of the enclosing block, so the `if` has to be one too:
            // as the unbraced body of a loop or a labelled statement, the
            // fused return would leave the loop instead of continuing it.
            let alternative = tokens.get(next_statement).map(|token| token.text) == Some("else");
            if !alternative
                && guard.checked_sub(1).is_some_and(|previous| {
                    !matches!(tokens[previous].text, "{" | "}" | ";" | "else")
                })
            {
                continue;
            }
            let tail_braced =
                alternative && tokens.get(next_statement + 1).map(|token| token.text) == Some("{");
            let tail_return = next_statement + usize::from(alternative) + usize::from(tail_braced);
            if tokens.get(tail_return).map(|token| token.text) != Some("return") {
                continue;
            }
            let Some((terminator, semicolon)) = statement_terminator(&tokens, tail_return + 1)
            else {
                continue;
            };
            // The replacement is an expression statement, so a braced arm's
            // own `}` disappears with it.
            let (tail_end, end) = if tail_braced {
                let Some(brace_close) = matching_close[next_statement + 1] else {
                    continue;
                };
                if terminator != brace_close
                    && !(terminator + 1 == brace_close && tokens[terminator].text == ";")
                {
                    continue;
                }
                (terminator, tokens[brace_close].end)
            } else if semicolon {
                (terminator, tokens[terminator].end)
            } else {
                (terminator, tokens[terminator].start)
            };

            // `return` followed by a line terminator is already `return;`, so
            // splicing across one would change what the argument is.
            let start = tokens[guard].start;
            if spans_line_terminator(&output[start..end]) {
                continue;
            }

            let condition = &output[tokens[condition_open].end..tokens[condition_close].start];
            let condition =
                if conditional_test_needs_grouping(&tokens[condition_open + 1..condition_close]) {
                    format!("({condition})")
                } else {
                    condition.to_string()
                };
            let guarded = conditional_return_arm(&output, &tokens, guarded_return + 1, guarded_end);
            let tail = conditional_return_arm(&output, &tokens, tail_return + 1, tail_end);
            let mut replacement = format!("return {condition}?{guarded}:{tail}");
            if semicolon && !tail_braced {
                replacement.push(';');
            }
            if replacement.len() < end - start {
                replacements.push((start, end, replacement));
            }
        }

        if replacements.is_empty() {
            return Ok((output, folded));
        }
        // Fusing the tail first lets the guard before it fuse in the next
        // round, so keep the rightmost of any overlapping pair.
        replacements.sort_unstable_by_key(|(start, end, _)| (*start, *end));
        let mut retained = Vec::<(usize, usize, String)>::new();
        for replacement in replacements.into_iter().rev() {
            if retained
                .last()
                .is_none_or(|(start, _, _)| replacement.1 <= *start)
            {
                retained.push(replacement);
            }
        }
        folded += retained.len();
        for (start, end, replacement) in retained {
            output.replace_range(start..end, &replacement);
        }
    }
}

/// Spell an arrow whose body is a lone `return` as a concise body.
///
/// `=>{return X}` and `=>X` produce the same value. A body that begins with
/// `{` would be read as a block, and a top-level comma binds looser than the
/// arrow body, so both are parenthesized.
fn fold_single_return_arrow_bodies(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let Some(tokens) = lex_certainly(source)? else {
        return Ok((source.to_string(), 0));
    };
    let matching_close = matching_closers(&tokens);
    let mut replacements = Vec::<(usize, usize, String)>::new();

    for body_open in 1..tokens.len() {
        if tokens[body_open].text != "{" || tokens[body_open - 1].text != "=>" {
            continue;
        }
        let (Some(body_close), Some(value)) =
            (matching_close[body_open], tokens.get(body_open + 1))
        else {
            continue;
        };
        if value.text != "return" {
            continue;
        }
        let Some((terminator, _)) = statement_terminator(&tokens, body_open + 2) else {
            continue;
        };
        if terminator != body_close
            && !(terminator + 1 == body_close && tokens[terminator].text == ";")
        {
            continue;
        }
        // `=>{}` already returns `undefined` in fewer bytes than `=>void 0`.
        if body_open + 2 >= terminator {
            continue;
        }
        let start = tokens[body_open].start;
        let end = tokens[body_close].end;
        if spans_line_terminator(&source[start..end]) {
            continue;
        }
        let text = &source[tokens[body_open + 2].start..tokens[terminator - 1].end];
        let replacement = if tokens[body_open + 2].text == "{"
            || expression_has_top_level_token(&tokens[body_open + 2..terminator], ",")
        {
            format!("({text})")
        } else {
            text.to_string()
        };
        if replacement.len() < end - start {
            replacements.push((start, end, replacement));
        }
    }

    if replacements.is_empty() {
        return Ok((source.to_string(), 0));
    }
    let retained = non_overlapping_ranges(replacements);
    let count = retained.len();
    let mut output = source.to_string();
    for (start, end, replacement) in retained.into_iter().rev() {
        output.replace_range(start..end, &replacement);
    }
    Ok((output, count))
}

/// Keep the outermost of any overlapping rewrite so nested candidates cannot
/// splice into a range that already moved.
fn non_overlapping_ranges(
    mut replacements: Vec<(usize, usize, String)>,
) -> Vec<(usize, usize, String)> {
    replacements.sort_unstable_by_key(|(start, end, _)| (*start, *end));
    let mut retained = Vec::<(usize, usize, String)>::new();
    let mut last_end = 0;
    for replacement in replacements {
        if replacement.0 >= last_end {
            last_end = replacement.1;
            retained.push(replacement);
        }
    }
    retained
}

fn merge_adjacent_declarations(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let mut output = source.to_string();
    let mut merged = 0;
    loop {
        let tokens = lex(&output)?;
        let mut candidate = None;
        for declaration in 0..tokens.len() {
            let kind = tokens[declaration].text;
            if !matches!(kind, "let" | "var" | "const")
                || declaration
                    .checked_sub(1)
                    .is_some_and(|previous| !matches!(tokens[previous].text, ";" | "{" | "}"))
            {
                continue;
            }
            let mut delimiters = Vec::<&str>::new();
            for index in declaration + 1..tokens.len().saturating_sub(1) {
                match tokens[index].text {
                    "(" | "[" | "{" => delimiters.push(tokens[index].text),
                    ")" | "]" | "}" => {
                        delimiters.pop();
                    }
                    ";" if delimiters.is_empty() => {
                        if tokens[index + 1].text == kind
                            && tokens
                                .get(index + 2)
                                .is_some_and(|token| token.kind == TokenKind::Identifier)
                        {
                            candidate = Some((tokens[index].start, tokens[index + 2].start));
                        }
                        break;
                    }
                    _ => {}
                }
            }
            if candidate.is_some() {
                break;
            }
        }
        let Some((start, end)) = candidate else {
            break;
        };
        output.replace_range(start..end, ",");
        merged += 1;
    }
    Ok((output, merged))
}

/// Rotates the generated SSA spelling `flag=true;while(flag){...;flag=next}`
/// into `do{...}while(next)`. The proof deliberately requires the synthetic
/// flag to occur only at those three sites and rejects `continue`, whose
/// bottom-condition timing would otherwise differ.
fn rotate_proven_initial_true_loops(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut matching_close = vec![None; tokens.len()];
    let mut stack = Vec::<usize>::new();
    for (index, token) in tokens.iter().enumerate() {
        match token.text {
            "(" | "[" | "{" => stack.push(index),
            ")" | "]" | "}" => {
                let Some(open) = stack.pop() else {
                    continue;
                };
                matching_close[open] = Some(index);
            }
            _ => {}
        }
    }

    let mut replacements = Vec::<(usize, usize, String)>::new();
    let mut cursor = 0;
    while cursor < tokens.len().saturating_sub(9) {
        let start = cursor;
        let Some(name) = tokens
            .get(start)
            .filter(|token| token.kind == TokenKind::Identifier)
            .map(|token| token.text)
        else {
            cursor += 1;
            continue;
        };
        if tokens.get(start + 1).map(|token| token.text) != Some("=") {
            cursor += 1;
            continue;
        }
        let while_index = if tokens.get(start + 2).map(|token| token.text) == Some("true")
            && tokens.get(start + 3).map(|token| token.text) == Some(";")
        {
            start + 4
        } else if tokens.get(start + 2).map(|token| token.text) == Some("!")
            && tokens.get(start + 3).map(|token| token.text) == Some("0")
            && tokens.get(start + 4).map(|token| token.text) == Some(";")
        {
            start + 5
        } else {
            cursor += 1;
            continue;
        };
        if tokens.get(while_index).map(|token| token.text) != Some("while")
            || tokens.get(while_index + 1).map(|token| token.text) != Some("(")
            || tokens.get(while_index + 2).map(|token| token.text) != Some(name)
            || tokens.get(while_index + 3).map(|token| token.text) != Some(")")
            || tokens.get(while_index + 4).map(|token| token.text) != Some("{")
        {
            cursor += 1;
            continue;
        }
        let body_open = while_index + 4;
        let Some(body_close) = matching_close[body_open] else {
            cursor += 1;
            continue;
        };
        if tokens[body_open + 1..body_close]
            .iter()
            .any(|token| token.text == "continue")
            || tokens[start..body_close]
                .iter()
                .filter(|token| token.kind == TokenKind::Identifier && token.text == name)
                .count()
                != 3
        {
            cursor = body_close + 1;
            continue;
        }

        let mut delimiters = Vec::<&str>::new();
        let mut top_level_semicolons = Vec::new();
        for (index, token) in tokens
            .iter()
            .enumerate()
            .take(body_close)
            .skip(body_open + 1)
        {
            match token.text {
                "(" | "[" | "{" => delimiters.push(token.text),
                ")" | "]" | "}" => {
                    delimiters.pop();
                }
                ";" if delimiters.is_empty() => top_level_semicolons.push(index),
                _ => {}
            }
        }
        // Standard-grammar emission may omit the update statement's final
        // semicolon immediately before `}`. Treat the block close as the same
        // statement boundary so this later peephole accepts both scored forms.
        let terminal_semicolon = top_level_semicolons
            .last()
            .copied()
            .filter(|semicolon| semicolon + 1 == body_close);
        let final_end = terminal_semicolon.unwrap_or(body_close);
        let final_start = top_level_semicolons
            .iter()
            .rev()
            .nth(usize::from(terminal_semicolon.is_some()))
            .map_or(body_open + 1, |index| index + 1);
        if tokens.get(final_start).map(|token| token.text) != Some(name)
            || tokens.get(final_start + 1).map(|token| token.text) != Some("=")
            || final_start + 2 >= final_end
        {
            cursor = body_close + 1;
            continue;
        }

        let mut replacement = String::new();
        replacement.push_str("do{");
        let mut retained_body = &source[tokens[body_open].end..tokens[final_start].start];
        if retained_body.ends_with(';') {
            retained_body = &retained_body[..retained_body.len() - 1];
        }
        replacement.push_str(retained_body);
        replacement.push_str("}while(");
        replacement.push_str(&source[tokens[final_start + 2].start..tokens[final_end].start]);
        replacement.push_str(");");
        let replaced_start = tokens[start].start;
        let replaced_end = tokens[body_close].end;
        if replacement.len() < replaced_end - replaced_start {
            replacements.push((replaced_start, replaced_end, replacement));
        }
        cursor = body_close + 1;
    }

    if replacements.is_empty() {
        return Ok((source.to_string(), 0));
    }
    let count = replacements.len();
    let mut output = source.to_string();
    for (start, end, replacement) in replacements.into_iter().rev() {
        output.replace_range(start..end, &replacement);
    }
    Ok((output, count))
}

fn remove_unused_standalone_vars(source: &str) -> Result<(String, usize), JavaScriptParseError> {
    let mut output = source.to_string();
    let mut removed = 0;
    loop {
        let tokens = lex(&output)?;
        let mut matching_open = vec![None; tokens.len()];
        let mut matching_close = vec![None; tokens.len()];
        let mut stack = Vec::<usize>::new();
        for (index, token) in tokens.iter().enumerate() {
            match token.text {
                "(" | "[" | "{" => stack.push(index),
                ")" | "]" | "}" => {
                    let Some(open) = stack.pop() else {
                        continue;
                    };
                    matching_open[index] = Some(open);
                    matching_close[open] = Some(index);
                }
                _ => {}
            }
        }
        let function_bodies = (0..tokens.len())
            .filter(|index| tokens[*index].text == "{")
            .filter_map(|body| {
                let end = matching_close[body]?;
                let arrow = body
                    .checked_sub(1)
                    .is_some_and(|previous| tokens[previous].text == "=>");
                if arrow {
                    let before_arrow = body.checked_sub(2)?;
                    let parameter_start = if tokens[before_arrow].text == ")" {
                        matching_open[before_arrow]?
                    } else {
                        before_arrow
                    };
                    return Some((body, end, parameter_start));
                }
                let close_params = body.checked_sub(1)?;
                (tokens[close_params].text == ")").then_some(())?;
                let open_params = matching_open[close_params]?;
                let before = open_params.checked_sub(1)?;
                let is_function = tokens[before].text == "function"
                    || before
                        .checked_sub(1)
                        .is_some_and(|index| tokens[index].text == "function")
                    || tokens[before].kind == TokenKind::Identifier;
                is_function.then_some((body, end, open_params))
            })
            .collect::<Vec<_>>();

        let candidate = uninitialized_var_declarators(&tokens).into_iter().find_map(
            |(index, remove_start, remove_end)| {
                let (scope_start, scope_end) = function_bodies
                    .iter()
                    .copied()
                    .filter(|(start, end, _)| *start < index && index < *end)
                    .max_by_key(|(start, _, _)| *start)
                    .map(|(start, end, _)| (start, end))
                    .unwrap_or((usize::MAX, tokens.len()));
                let first = if scope_start == usize::MAX {
                    0
                } else {
                    scope_start + 1
                };
                let name = tokens[index].text;
                let shadowing_nested_scopes = function_bodies
                    .iter()
                    .copied()
                    .filter(|(start, end, _)| first <= *start && *end < scope_end)
                    .filter(|(start, end, _)| {
                        function_scope_declares(&tokens, &matching_open, *start, *end, name)
                    })
                    .collect::<Vec<_>>();
                let occurrences = tokens[first..scope_end]
                    .iter()
                    .enumerate()
                    .filter(|(offset, token)| {
                        let token_index = first + *offset;
                        token.kind == TokenKind::Identifier
                            && token.text == name
                            && !shadowing_nested_scopes
                                .iter()
                                .any(|(_, end, parameter_start)| {
                                    *parameter_start <= token_index && token_index < *end
                                })
                    })
                    .count();
                (occurrences == 1).then_some((remove_start, remove_end))
            },
        );
        let Some((start, end)) = candidate else {
            break;
        };
        output.replace_range(start..end, "");
        removed += 1;
    }
    Ok((output, removed))
}

/// Drops the space in `return "x"`, `case -1:`, `typeof {}` and friends.
///
/// A keyword only needs a separator when the next token could otherwise merge
/// into it, which is exactly when that token starts with an identifier
/// character or a digit (`return x`, `return 5`). String, template and regex
/// literals, and punctuation that opens a group or applies a prefix operator,
/// can all sit flush against the keyword.
///
/// `.` is deliberately excluded: `return .5` re-lexes as a member access on the
/// keyword when the space is removed.
fn elide_separating_keyword_spaces(
    source: &str,
) -> Result<(String, usize), JavaScriptParseError> {
    let Some(tokens) = lex_certainly(source)? else {
        return Ok((source.to_string(), 0));
    };
    let mut cuts = Vec::new();
    for pair in tokens.windows(2) {
        let [left, right] = pair else { continue };
        if left.kind != TokenKind::Keyword || right.start != left.end + 1 {
            continue;
        }
        if source.as_bytes().get(left.end) != Some(&b' ') {
            continue;
        }
        let flush = match right.kind {
            TokenKind::String | TokenKind::Template | TokenKind::Regex => true,
            TokenKind::Punct => right
                .text
                .as_bytes()
                .first()
                .is_some_and(|byte| matches!(byte, b'[' | b'(' | b'{' | b'!' | b'~' | b'+' | b'-')),
            _ => false,
        };
        if flush {
            cuts.push(left.end);
        }
    }
    if cuts.is_empty() {
        return Ok((source.to_string(), 0));
    }
    let mut output = String::with_capacity(source.len());
    let mut cursor = 0;
    for cut in &cuts {
        output.push_str(&source[cursor..*cut]);
        cursor = cut + 1;
    }
    output.push_str(&source[cursor..]);
    Ok((output, cuts.len()))
}

/// A declarator is removable when nothing observes dropping its initializer.
/// Uninitialized bindings qualify trivially; so does a binding initialized to a
/// single literal token, because evaluating a literal cannot be observed.
///
/// The string pool is the common producer of the second shape: it hoists a
/// literal into a binding, and a later decision to spell the uses differently
/// (`o["k"]` collapsing to `o.k`) can strand the binding with no readers.
fn declarator_initializer_is_inert(tokens: &[Token<'_>], start: usize, end: usize) -> bool {
    match end - start {
        1 => true,
        3 => {
            tokens[start + 1].text == "="
                && match tokens[start + 2].kind {
                    TokenKind::Number | TokenKind::String | TokenKind::Regex => true,
                    TokenKind::Keyword => {
                        matches!(tokens[start + 2].text, "true" | "false" | "null")
                    }
                    _ => false,
                }
        }
        _ => false,
    }
}

/// Returns removable `var`/`let`/`const` declarators with the byte range that
/// removes just that declarator (or the complete declaration when it is the
/// only one).
fn uninitialized_var_declarators(tokens: &[Token<'_>]) -> Vec<(usize, usize, usize)> {
    let mut candidates = Vec::new();
    for var_index in 0..tokens.len() {
        if !matches!(tokens[var_index].text, "var" | "let" | "const") {
            continue;
        }
        // `for ( let i = 0 ; ... )` ends its declaration on the header's own
        // semicolon, so removing the declaration would eat a required `;`.
        if var_index
            .checked_sub(2)
            .is_some_and(|index| tokens[index].text == "for" && tokens[index + 1].text == "(")
        {
            continue;
        }
        let mut delimiters = Vec::<&str>::new();
        let mut segment_start = var_index + 1;
        let mut segments = Vec::<(usize, usize, Option<usize>)>::new();
        let mut cursor = segment_start;
        let mut semicolon = None;
        while cursor < tokens.len() {
            match tokens[cursor].text {
                "(" | "[" | "{" => delimiters.push(tokens[cursor].text),
                ")" | "]" | "}" => {
                    if delimiters.pop().is_none() {
                        break;
                    }
                }
                "," if delimiters.is_empty() => {
                    segments.push((segment_start, cursor, Some(cursor)));
                    segment_start = cursor + 1;
                }
                ";" if delimiters.is_empty() => {
                    segments.push((segment_start, cursor, None));
                    semicolon = Some(cursor);
                    break;
                }
                _ => {}
            }
            cursor += 1;
        }
        let Some(semicolon) = semicolon else {
            continue;
        };
        for (segment_index, (start, end, following_comma)) in segments.iter().enumerate() {
            if tokens[*start].kind != TokenKind::Identifier
                || !declarator_initializer_is_inert(tokens, *start, *end)
            {
                continue;
            }
            let (remove_start, remove_end) = if segments.len() == 1 {
                (tokens[var_index].start, tokens[semicolon].end)
            } else if segment_index == 0 {
                (
                    tokens[*start].start,
                    tokens[following_comma.expect("a non-final segment has a comma")].end,
                )
            } else {
                (tokens[start - 1].start, tokens[end - 1].end)
            };
            candidates.push((*start, remove_start, remove_end));
        }
    }
    candidates
}

fn function_scope_declares(
    tokens: &[Token<'_>],
    matching_open: &[Option<usize>],
    body: usize,
    end: usize,
    name: &str,
) -> bool {
    let parameter_range = body.checked_sub(1).and_then(|before_body| {
        if tokens[before_body].text == "=>" {
            let before_arrow = before_body.checked_sub(1)?;
            if tokens[before_arrow].text == ")" {
                matching_open[before_arrow].map(|open| (open + 1, before_arrow))
            } else {
                Some((before_arrow, before_arrow + 1))
            }
        } else if tokens[before_body].text == ")" {
            matching_open[before_body].map(|open| (open + 1, before_body))
        } else {
            None
        }
    });
    if parameter_range.is_some_and(|(start, finish)| {
        tokens[start..finish]
            .iter()
            .any(|token| token.kind == TokenKind::Identifier && token.text == name)
    }) {
        return true;
    }

    let mut cursor = body + 1;
    while cursor < end {
        if tokens[cursor].text != "var" {
            cursor += 1;
            continue;
        }
        cursor += 1;
        let mut delimiter_depth = 0usize;
        let mut expects_name = true;
        while cursor < end {
            let token = tokens[cursor];
            if delimiter_depth == 0 && token.text == ";" {
                break;
            }
            if expects_name && token.kind == TokenKind::Identifier {
                if token.text == name {
                    return true;
                }
                expects_name = false;
            }
            match token.text {
                "(" | "[" | "{" => delimiter_depth += 1,
                ")" | "]" | "}" => delimiter_depth = delimiter_depth.saturating_sub(1),
                "," if delimiter_depth == 0 => expects_name = true,
                _ => {}
            }
            cursor += 1;
        }
    }
    false
}

fn reuse_dead_var_binding(source: &str) -> Result<(String, bool), JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut matching_open = vec![None; tokens.len()];
    let mut matching_close = vec![None; tokens.len()];
    let mut stack = Vec::<usize>::new();
    let mut brace_depth = vec![0usize; tokens.len()];
    let mut depth = 0usize;
    for (index, token) in tokens.iter().enumerate() {
        brace_depth[index] = depth;
        match token.text {
            "(" | "[" | "{" => {
                stack.push(index);
                if token.text == "{" {
                    depth += 1;
                }
            }
            ")" | "]" | "}" => {
                let Some(open) = stack.pop() else {
                    continue;
                };
                matching_open[index] = Some(open);
                matching_close[open] = Some(index);
                if token.text == "}" {
                    depth = depth.saturating_sub(1);
                }
            }
            _ => {}
        }
    }

    let function_bodies = (0..tokens.len())
        .filter(|index| tokens[*index].text == "{")
        .filter_map(|body| {
            let end = matching_close[body]?;
            if body
                .checked_sub(1)
                .is_some_and(|previous| tokens[previous].text == "=>")
            {
                let before_arrow = body.checked_sub(2)?;
                let (parameter_start, parameter_end) = if tokens[before_arrow].text == ")" {
                    let open = matching_open[before_arrow]?;
                    (open + 1, before_arrow)
                } else {
                    (before_arrow, before_arrow + 1)
                };
                return Some((body, end, parameter_start, parameter_end));
            }
            let close_params = body.checked_sub(1)?;
            (tokens[close_params].text == ")").then_some(())?;
            let open_params = matching_open[close_params]?;
            let before = open_params.checked_sub(1)?;
            let is_function = tokens[before].text == "function"
                || before
                    .checked_sub(1)
                    .is_some_and(|index| tokens[index].text == "function")
                || tokens[before].kind == TokenKind::Identifier;
            is_function.then_some((body, end, open_params + 1, close_params))
        })
        .collect::<Vec<_>>();
    let arrow_parameter_ranges = tokens
        .iter()
        .enumerate()
        .filter(|(_, token)| token.text == "=>")
        .filter_map(|(arrow, _)| {
            let before_arrow = arrow.checked_sub(1)?;
            if tokens[before_arrow].text == ")" {
                let open = matching_open[before_arrow]?;
                Some((open + 1, before_arrow))
            } else {
                Some((before_arrow, before_arrow + 1))
            }
        })
        .collect::<Vec<_>>();

    for second_var in 0..tokens.len().saturating_sub(2) {
        if tokens[second_var].text != "var"
            || tokens[second_var + 1].kind != TokenKind::Identifier
            || tokens[second_var + 2].text != "="
            || second_var
                .checked_sub(1)
                .is_some_and(|previous| !matches!(tokens[previous].text, ";" | "{" | "}"))
        {
            continue;
        }
        let Some((scope_start, scope_end, _, _)) = function_bodies
            .iter()
            .copied()
            .filter(|(start, end, _, _)| *start < second_var && second_var < *end)
            .max_by_key(|(start, _, _, _)| *start)
        else {
            continue;
        };
        // Removing the `var` keyword is valid only for a single-declarator
        // statement.  In `var next=value,i=0,tmp`, doing so would turn `i`
        // and `tmp` into undeclared assignments (and can overwrite a mangled
        // top-level function in modules).
        if var_declaration_has_multiple_declarators(&tokens, second_var, scope_end) {
            continue;
        }
        let declaration_depth = brace_depth[second_var];
        let second_name = tokens[second_var + 1].text;
        let Some(first_var) = (scope_start + 1..second_var).rev().find(|index| {
            tokens[*index].text == "var"
                && tokens.get(*index + 1).is_some_and(|token| {
                    token.kind == TokenKind::Identifier && token.text != second_name
                })
                && tokens
                    .get(*index + 2)
                    .is_some_and(|token| token.text == "=")
                && brace_depth[*index] == declaration_depth
        }) else {
            continue;
        };
        let first_name = tokens[first_var + 1].text;
        // A use inside an already-created nested function remains live for as
        // long as that closure can escape. Textual last-use alone is therefore
        // insufficient: reusing the binding would mutate the closure's capture.
        let captured_before_second = (first_var + 2..second_var).any(|index| {
            tokens[index].kind == TokenKind::Identifier
                && tokens[index].text == first_name
                && function_bodies.iter().any(|(body, end, _, _)| {
                    scope_start < *body && *body < index && index < *end && *end < scope_end
                })
        });
        if captured_before_second {
            continue;
        }
        if tokens[second_var + 2..scope_end]
            .iter()
            .any(|token| token.kind == TokenKind::Identifier && token.text == first_name)
        {
            continue;
        }
        if tokens[scope_start + 1..second_var]
            .iter()
            .any(|token| token.kind == TokenKind::Identifier && token.text == second_name)
        {
            continue;
        }

        let mut replacements = vec![(
            tokens[second_var].start,
            tokens[second_var + 1].end,
            first_name,
        )];
        let mut safe = true;
        for index in second_var + 2..scope_end {
            let token = tokens[index];
            if token.kind != TokenKind::Identifier || token.text != second_name {
                continue;
            }
            let nested_parameter =
                arrow_parameter_ranges
                    .iter()
                    .any(|(parameter_start, parameter_end)| {
                        *parameter_start <= index && index < *parameter_end
                    })
                    || function_bodies
                        .iter()
                        .any(|(_, _, parameter_start, parameter_end)| {
                            *parameter_start <= index && index < *parameter_end
                        });
            let declaration = index.checked_sub(1).is_some_and(|previous| {
                matches!(
                    tokens[previous].text,
                    "var" | "let" | "const" | "function" | "class" | "catch"
                )
            });
            let property = index
                .checked_sub(1)
                .is_some_and(|previous| matches!(tokens[previous].text, "." | "?."))
                || tokens.get(index + 1).is_some_and(|next| next.text == ":");
            if nested_parameter || declaration || property {
                safe = false;
                break;
            }
            replacements.push((token.start, token.end, first_name));
        }
        if !safe || replacements.len() == 1 {
            continue;
        }
        let mut output = String::with_capacity(source.len().saturating_sub(4));
        let mut cursor = 0;
        for (start, end, replacement) in replacements {
            output.push_str(&source[cursor..start]);
            output.push_str(replacement);
            cursor = end;
        }
        output.push_str(&source[cursor..]);
        return Ok((output, true));
    }
    Ok((source.to_string(), false))
}

fn var_declaration_has_multiple_declarators(
    tokens: &[Token<'_>],
    var_index: usize,
    scope_end: usize,
) -> bool {
    let mut delimiter_depth = 0usize;
    for token in tokens
        .iter()
        .take(scope_end)
        .skip(var_index.saturating_add(1))
    {
        match token.text {
            "(" | "[" | "{" => delimiter_depth += 1,
            ")" | "]" | "}" => delimiter_depth = delimiter_depth.saturating_sub(1),
            "," if delimiter_depth == 0 => return true,
            ";" if delimiter_depth == 0 => return false,
            _ => {}
        }
    }
    true
}

pub fn analyze_generated_javascript(
    source: &str,
) -> Result<JavaScriptSyntaxMetrics, JavaScriptParseError> {
    let tokens = lex(source)?;
    let delimiter_nesting = validate_delimiters(&tokens)?;
    let parsed = parse_expression_regions(&tokens);
    Ok(syntax_metrics(source, &tokens, &parsed, delimiter_nesting))
}

pub fn single_character_identifiers(source: &str) -> Result<Vec<u8>, JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut identifiers = tokens
        .iter()
        .flat_map(|token| {
            let mut found = Vec::new();
            if token.kind == TokenKind::Identifier && token.text.len() == 1 {
                found.push(token.text.as_bytes()[0]);
            } else if token.kind == TokenKind::Template {
                for window in token.text.as_bytes().windows(4) {
                    if window[0] == b'$'
                        && window[1] == b'{'
                        && window[2].is_ascii_alphabetic()
                        && window[3] == b'}'
                    {
                        found.push(window[2]);
                    }
                }
            }
            found
        })
        .collect::<Vec<_>>();
    identifiers.sort_unstable();
    identifiers.dedup();
    Ok(identifiers)
}

pub fn remap_single_character_identifiers(
    source: &str,
    mapping: &[u8; 128],
) -> Result<String, JavaScriptParseError> {
    let tokens = lex(source)?;
    let mut replacements = Vec::new();
    for token in &tokens {
        if token.kind == TokenKind::Identifier && token.text.len() == 1 {
            let byte = token.text.as_bytes()[0];
            let replacement = mapping[byte as usize];
            if replacement != byte {
                replacements.push((token.start, token.end, replacement));
            }
        } else if token.kind == TokenKind::Template {
            for (offset, window) in token.text.as_bytes().windows(4).enumerate() {
                if window[0] != b'$'
                    || window[1] != b'{'
                    || !window[2].is_ascii_alphabetic()
                    || window[3] != b'}'
                {
                    continue;
                }
                let replacement = mapping[window[2] as usize];
                if replacement != window[2] {
                    replacements.push((
                        token.start + offset + 2,
                        token.start + offset + 3,
                        replacement,
                    ));
                }
            }
        }
    }
    if replacements.is_empty() {
        return Ok(source.to_string());
    }
    let mut output = String::with_capacity(source.len());
    let mut cursor = 0;
    for (start, end, replacement) in replacements {
        output.push_str(&source[cursor..start]);
        output.push(char::from(replacement));
        cursor = end;
    }
    output.push_str(&source[cursor..]);
    Ok(output)
}

fn syntax_metrics(
    source: &str,
    tokens: &[Token<'_>],
    parsed: &[ParsedRegion<'_>],
    delimiter_nesting: usize,
) -> JavaScriptSyntaxMetrics {
    let functions = tokens
        .iter()
        .filter(|token| token.text == "function" || token.text == "=>")
        .count();
    let branches = tokens
        .iter()
        .filter(|token| matches!(token.text, "if" | "switch" | "case" | "?"))
        .count();
    let loops = tokens
        .iter()
        .filter(|token| matches!(token.text, "for" | "while" | "do"))
        .count();
    let calls = tokens
        .windows(2)
        .filter(|pair| {
            pair[1].text == "("
                && (matches!(
                    pair[0].kind,
                    TokenKind::Identifier | TokenKind::String | TokenKind::Template
                ) || matches!(pair[0].text, ")" | "]"))
                && !matches!(pair[0].text, "if" | "for" | "while" | "switch" | "catch")
        })
        .count();
    let parsed_nodes = non_overlapping_parsed_node_count(parsed);
    let expression_nesting = parsed
        .iter()
        .map(|region| region.expression.max_depth())
        .max()
        .unwrap_or(0);
    let max_nesting = delimiter_nesting.max(expression_nesting);
    let structural_nodes = tokens
        .iter()
        .filter(|token| !matches!(token.text, ";" | "," | "(" | ")" | "[" | "]" | "{" | "}"))
        .count();
    let ast_nodes = structural_nodes.max(parsed_nodes);
    let literal_bytes = tokens
        .iter()
        .filter(|token| {
            matches!(
                token.kind,
                TokenKind::Number | TokenKind::String | TokenKind::Template
            )
        })
        .map(|token| token.text.len())
        .sum::<usize>();

    let parse_cost = (tokens.len() as u64)
        .saturating_mul(8)
        .saturating_add(literal_bytes as u64)
        .saturating_add((max_nesting as u64).saturating_pow(2));
    let compile_cost = (ast_nodes as u64)
        .saturating_mul(12)
        .saturating_add((functions as u64).saturating_mul(64))
        .saturating_add((calls as u64).saturating_mul(12))
        .saturating_add((branches as u64).saturating_mul(32))
        .saturating_add((loops as u64).saturating_mul(48));
    let estimated_memory_bytes = (source.len() as u64)
        .saturating_mul(2)
        .saturating_add((tokens.len() as u64).saturating_mul(24))
        .saturating_add((ast_nodes as u64).saturating_mul(32))
        .saturating_add((max_nesting as u64).saturating_mul(64));

    JavaScriptSyntaxMetrics {
        bytes: source.len(),
        tokens: tokens.len(),
        ast_nodes,
        max_nesting,
        functions,
        calls,
        branches,
        loops,
        parse_cost,
        compile_cost,
        estimated_memory_bytes,
    }
}

fn non_overlapping_parsed_node_count(parsed: &[ParsedRegion<'_>]) -> usize {
    // `parse_expression_regions` deliberately discovers nested suffixes as
    // independent rewrite opportunities (notably every arm after `:` in a
    // conditional chain). Those regions describe the same AST nodes and must
    // not be summed for startup accounting. Regions are produced in ascending
    // start-token order, and successfully parsed overlaps are nested, so the
    // first interval is the maximal expression root; later contained roots are
    // skipped while genuinely disjoint statement expressions remain additive.
    let mut covered_until = 0;
    let mut nodes = 0usize;
    for region in parsed {
        if region.start_token < covered_until {
            continue;
        }
        nodes = nodes.saturating_add(region.expression.node_count());
        covered_until = region.end_token;
    }
    nodes
}

fn apply_rewrites(source: &str, rewrites: &[Rewrite]) -> String {
    if rewrites.is_empty() {
        return source.to_string();
    }
    let saved = rewrites
        .iter()
        .map(|rewrite| rewrite.end.saturating_sub(rewrite.start))
        .sum::<usize>();
    let mut output = String::with_capacity(source.len().saturating_sub(saved / 4));
    let mut cursor = 0;
    for rewrite in rewrites {
        output.push_str(&source[cursor..rewrite.start]);
        output.push_str(&source[rewrite.identifier_start..rewrite.identifier_end]);
        output.push_str(rewrite.operator);
        output.push('=');
        output.push_str(&source[rewrite.rhs_start..rewrite.rhs_end]);
        cursor = rewrite.end;
    }
    output.push_str(&source[cursor..]);
    output
}

fn non_overlapping_rewrites(rewrites: Vec<Rewrite>) -> Vec<Rewrite> {
    let mut retained = Vec::with_capacity(rewrites.len());
    let mut end = 0;
    for rewrite in rewrites {
        if rewrite.start >= end {
            end = rewrite.end;
            retained.push(rewrite);
        }
    }
    retained
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ParsedRegion<'src> {
    start_token: usize,
    end_token: usize,
    expression: Expression<'src>,
}

fn parse_expression_regions<'src>(tokens: &[Token<'src>]) -> Vec<ParsedRegion<'src>> {
    let mut regions = Vec::new();
    for start in 0..tokens.len() {
        if !can_start_expression_region(tokens, start) {
            continue;
        }
        let end = expression_region_end(tokens, start);
        if end <= start {
            continue;
        }
        let mut parser = ExpressionParser::new(&tokens[start..end]);
        if let Some(expression) = parser.parse_complete() {
            regions.push(ParsedRegion {
                start_token: start,
                end_token: end,
                expression,
            });
        }
    }
    regions
}

fn can_start_expression_region(tokens: &[Token<'_>], index: usize) -> bool {
    if index == 0 {
        return true;
    }
    matches!(tokens[index - 1].text, "{" | "}" | ";" | ":" | ")")
        && !matches!(
            tokens[index].text,
            "let"
                | "var"
                | "const"
                | "return"
                | "throw"
                | "break"
                | "continue"
                | "case"
                | "default"
                | "else"
        )
}

fn expression_region_end(tokens: &[Token<'_>], start: usize) -> usize {
    let mut stack = Vec::new();
    for (index, token) in tokens.iter().enumerate().skip(start) {
        match token.text {
            "(" | "[" | "{" => stack.push(token.text),
            ")" => {
                if stack.last() == Some(&"(") {
                    stack.pop();
                } else if stack.is_empty() {
                    return index;
                } else {
                    return start;
                }
            }
            "]" => {
                if stack.last() == Some(&"[") {
                    stack.pop();
                } else if stack.is_empty() {
                    return index;
                } else {
                    return start;
                }
            }
            "}" => {
                if stack.last() == Some(&"{") {
                    stack.pop();
                } else if stack.is_empty() {
                    return index;
                } else {
                    return start;
                }
            }
            ";" if stack.is_empty() => return index,
            _ => {}
        }
    }
    tokens.len()
}

fn compound_assignment_rewrite(tokens: &[Token<'_>], region: &ParsedRegion<'_>) -> Option<Rewrite> {
    let Expression::Assignment { operator, lhs, rhs } = &region.expression else {
        return None;
    };
    if *operator != "=" {
        return None;
    }
    let Expression::Identifier(assigned) = lhs.as_ref() else {
        return None;
    };
    let Expression::Binary {
        operator,
        lhs: binary_lhs,
        ..
    } = rhs.as_ref()
    else {
        return None;
    };
    let Expression::Identifier(read) = binary_lhs.as_ref() else {
        return None;
    };
    if assigned != read {
        return None;
    }
    let operator = match *operator {
        "+" => "+",
        "-" => "-",
        "*" => "*",
        "/" => "/",
        "%" => "%",
        "&" => "&",
        "|" => "|",
        "^" => "^",
        "<<" => "<<",
        ">>" => ">>",
        ">>>" => ">>>",
        _ => return None,
    };

    let region_tokens = &tokens[region.start_token..region.end_token];
    let assignment_index = region_tokens.iter().position(|token| token.text == "=")?;
    let binary_index = region_tokens
        .iter()
        .enumerate()
        .skip(assignment_index + 1)
        .find(|(_, token)| token.text == operator)
        .map(|(index, _)| index)?;
    let identifier = region_tokens.first()?;
    let rhs = region_tokens.get(binary_index + 1)?;
    let last = region_tokens.last()?;
    Some(Rewrite {
        start: identifier.start,
        end: last.end,
        rhs_start: rhs.start,
        rhs_end: last.end,
        identifier_start: identifier.start,
        identifier_end: identifier.end,
        operator,
    })
}

struct ExpressionParser<'tokens, 'src> {
    tokens: &'tokens [Token<'src>],
    cursor: usize,
}

impl<'tokens, 'src> ExpressionParser<'tokens, 'src> {
    const fn new(tokens: &'tokens [Token<'src>]) -> Self {
        Self { tokens, cursor: 0 }
    }

    fn parse_complete(&mut self) -> Option<Expression<'src>> {
        let expression = self.parse_expression(1)?;
        (self.cursor == self.tokens.len()).then_some(expression)
    }

    fn parse_expression(&mut self, minimum_precedence: u8) -> Option<Expression<'src>> {
        let mut lhs = self.parse_prefix()?;
        loop {
            lhs = self.parse_postfix(lhs)?;
            let Some(token) = self.peek().copied() else {
                break;
            };
            if token.text == "?" {
                if 3 < minimum_precedence {
                    break;
                }
                self.cursor += 1;
                let then_value = self.parse_expression(1)?;
                self.consume(":")?;
                let else_value = self.parse_expression(3)?;
                lhs = Expression::Conditional {
                    condition: Box::new(lhs),
                    then_value: Box::new(then_value),
                    else_value: Box::new(else_value),
                };
                continue;
            }
            let Some((precedence, right_associative, assignment)) = infix_precedence(token.text)
            else {
                break;
            };
            if precedence < minimum_precedence {
                break;
            }
            self.cursor += 1;
            let rhs = self.parse_expression(if right_associative {
                precedence
            } else {
                precedence + 1
            })?;
            lhs = if token.text == "," {
                match lhs {
                    Expression::Sequence(mut values) => {
                        values.push(rhs);
                        Expression::Sequence(values)
                    }
                    value => Expression::Sequence(vec![value, rhs]),
                }
            } else if assignment {
                Expression::Assignment {
                    operator: token.text,
                    lhs: Box::new(lhs),
                    rhs: Box::new(rhs),
                }
            } else {
                Expression::Binary {
                    operator: token.text,
                    lhs: Box::new(lhs),
                    rhs: Box::new(rhs),
                }
            };
        }
        Some(lhs)
    }

    fn parse_prefix(&mut self) -> Option<Expression<'src>> {
        let token = *self.peek()?;
        if matches!(
            token.text,
            "!" | "~" | "+" | "-" | "typeof" | "void" | "delete" | "++" | "--"
        ) {
            self.cursor += 1;
            return Some(Expression::Unary {
                operand: Box::new(self.parse_expression(15)?),
            });
        }
        self.cursor += 1;
        match token.kind {
            TokenKind::Identifier => Some(Expression::Identifier(token.text)),
            TokenKind::Number | TokenKind::String | TokenKind::Template => {
                Some(Expression::Literal)
            }
            TokenKind::Keyword
                if matches!(token.text, "true" | "false" | "null" | "this" | "undefined") =>
            {
                Some(Expression::Literal)
            }
            TokenKind::Punct if token.text == "(" => {
                let expression = self.parse_expression(1)?;
                self.consume(")")?;
                Some(expression)
            }
            TokenKind::Punct if token.text == "[" => {
                let mut values = Vec::new();
                if self.peek().is_some_and(|token| token.text == "]") {
                    self.cursor += 1;
                    return Some(Expression::Array(values));
                }
                loop {
                    values.push(self.parse_expression(2)?);
                    if self.peek().is_some_and(|token| token.text == "]") {
                        self.cursor += 1;
                        break;
                    }
                    self.consume(",")?;
                }
                Some(Expression::Array(values))
            }
            _ => None,
        }
    }

    fn parse_postfix(&mut self, mut expression: Expression<'src>) -> Option<Expression<'src>> {
        loop {
            match self.peek().map(|token| token.text) {
                Some("(") => {
                    self.cursor += 1;
                    let mut arguments = Vec::new();
                    if self.peek().is_some_and(|token| token.text == ")") {
                        self.cursor += 1;
                    } else {
                        loop {
                            arguments.push(self.parse_expression(2)?);
                            if self.peek().is_some_and(|token| token.text == ")") {
                                self.cursor += 1;
                                break;
                            }
                            self.consume(",")?;
                        }
                    }
                    expression = Expression::Call {
                        callee: Box::new(expression),
                        arguments,
                    };
                }
                Some(".") => {
                    self.cursor += 1;
                    let property = *self.peek()?;
                    if !matches!(property.kind, TokenKind::Identifier | TokenKind::Keyword) {
                        return None;
                    }
                    self.cursor += 1;
                    expression = Expression::Member {
                        object: Box::new(expression),
                        property: Box::new(Expression::Identifier(property.text)),
                    };
                }
                Some("[") => {
                    self.cursor += 1;
                    let property = self.parse_expression(1)?;
                    self.consume("]")?;
                    expression = Expression::Member {
                        object: Box::new(expression),
                        property: Box::new(property),
                    };
                }
                Some("++" | "--") => {
                    self.cursor += 1;
                    expression = Expression::Unary {
                        operand: Box::new(expression),
                    };
                }
                _ => break,
            }
        }
        Some(expression)
    }

    fn consume(&mut self, expected: &str) -> Option<()> {
        if self.peek()?.text != expected {
            return None;
        }
        self.cursor += 1;
        Some(())
    }

    fn peek(&self) -> Option<&Token<'src>> {
        self.tokens.get(self.cursor)
    }
}

const fn infix_precedence(operator: &str) -> Option<(u8, bool, bool)> {
    match operator.as_bytes() {
        b"," => Some((1, false, false)),
        b"=" | b"+=" | b"-=" | b"*=" | b"/=" | b"%=" | b"&=" | b"|=" | b"^=" | b"<<=" | b">>="
        | b">>>=" | b"&&=" | b"||=" | b"??=" => Some((2, true, true)),
        b"??" => Some((4, false, false)),
        b"||" => Some((5, false, false)),
        b"&&" => Some((6, false, false)),
        b"|" => Some((7, false, false)),
        b"^" => Some((8, false, false)),
        b"&" => Some((9, false, false)),
        b"==" | b"!=" | b"===" | b"!==" => Some((10, false, false)),
        b"<" | b"<=" | b">" | b">=" | b"in" | b"instanceof" => Some((11, false, false)),
        b"<<" | b">>" | b">>>" => Some((12, false, false)),
        b"+" | b"-" => Some((13, false, false)),
        b"*" | b"/" | b"%" => Some((14, false, false)),
        b"**" => Some((15, true, false)),
        _ => None,
    }
}

fn validate_delimiters(tokens: &[Token<'_>]) -> Result<usize, JavaScriptParseError> {
    let mut stack = Vec::new();
    let mut maximum = 0;
    for token in tokens {
        match token.text {
            "(" | "[" | "{" => {
                stack.push(token);
                maximum = maximum.max(stack.len());
            }
            ")" | "]" | "}" => {
                let Some(open) = stack.pop() else {
                    return Err(JavaScriptParseError {
                        offset: token.start,
                        message: "unmatched closing delimiter",
                    });
                };
                let matches = matches!(
                    (open.text, token.text),
                    ("(", ")") | ("[", "]") | ("{", "}")
                );
                if !matches {
                    return Err(JavaScriptParseError {
                        offset: token.start,
                        message: "mismatched closing delimiter",
                    });
                }
            }
            _ => {}
        }
    }
    if let Some(open) = stack.last() {
        return Err(JavaScriptParseError {
            offset: open.start,
            message: "unclosed delimiter",
        });
    }
    Ok(maximum)
}

/// How a still-open delimiter was opened. Only the distinction that decides
/// whether a `/` after the matching closer starts a regular expression or a
/// division is tracked.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GroupKind {
    /// `(` of `if`/`while`/`for`/`with`/`switch`/`catch`. A statement — and
    /// therefore a regular-expression literal — may follow its `)`.
    ControlHeader,
    /// Any other `(`: a call argument list, parameter list, or grouping. Its
    /// `)` ends an expression, so a following `/` is division.
    Expression,
    Bracket,
    Brace,
}

/// A lexed token stream plus whether every `/` in it was classified from an
/// unambiguous predecessor.
///
/// Regex-versus-division is decided by the previous significant token. Every
/// predecessor this emitter produces resolves exactly — `)` through the group
/// stack, `]`/`++`/`--`/identifiers/literals as division, and every other
/// operator or statement keyword as a regex start. The single genuinely
/// ambiguous predecessor in the grammar is `}`, which ends a block (statement
/// position, regex) or an object/function expression (division). That case is
/// reported rather than guessed, so punctuation-shaped rewrites can refuse a
/// stream they cannot prove they read correctly.
#[derive(Debug, Clone)]
struct LexedSource<'src> {
    tokens: Vec<Token<'src>>,
    slash_classification_certain: bool,
}

fn lex(source: &str) -> Result<Vec<Token<'_>>, JavaScriptParseError> {
    Ok(lex_classified(source)?.tokens)
}

/// Lex only when every `/` was classified from an unambiguous predecessor.
///
/// Punctuation-shaped rewrites select operators positionally, so a `/` read as
/// division when it opened a regular-expression body (or the reverse) would
/// corrupt the artifact. Returning `None` keeps the caller's input untouched.
fn lex_certainly(source: &str) -> Result<Option<Vec<Token<'_>>>, JavaScriptParseError> {
    let lexed = lex_classified(source)?;
    Ok(lexed.slash_classification_certain.then_some(lexed.tokens))
}

fn lex_classified(source: &str) -> Result<LexedSource<'_>, JavaScriptParseError> {
    let bytes = source.as_bytes();
    let mut tokens = Vec::with_capacity(source.len() / 2);
    let mut groups = Vec::<GroupKind>::new();
    // A program starts at statement position, where `/` opens a regex.
    let mut regex_allowed = true;
    let mut slash_classification_certain = true;
    let mut cursor = 0;
    while cursor < bytes.len() {
        let byte = bytes[cursor];
        if byte.is_ascii_whitespace() {
            cursor += 1;
            continue;
        }
        if source[cursor..].starts_with("//") {
            cursor += 2;
            while cursor < bytes.len() && !matches!(bytes[cursor], b'\n' | b'\r') {
                cursor += 1;
            }
            continue;
        }
        if source[cursor..].starts_with("/*") {
            let start = cursor;
            cursor += 2;
            while cursor + 1 < bytes.len() && &source[cursor..cursor + 2] != "*/" {
                cursor += 1;
            }
            if cursor + 1 >= bytes.len() {
                return Err(JavaScriptParseError {
                    offset: start,
                    message: "unterminated block comment",
                });
            }
            cursor += 2;
            continue;
        }
        let start = cursor;
        let kind = if is_identifier_start(byte) {
            cursor += 1;
            while cursor < bytes.len() && is_identifier_continue(bytes[cursor]) {
                cursor += 1;
            }
            let word = &source[start..cursor];
            if is_keyword(word) {
                // Only the value keywords end an expression. Every other
                // keyword introduces one, so a following `/` opens a regex.
                regex_allowed = !matches!(word, "this" | "super" | "true" | "false" | "null");
                TokenKind::Keyword
            } else {
                regex_allowed = false;
                TokenKind::Identifier
            }
        } else if byte.is_ascii_digit()
            || (byte == b'.' && bytes.get(cursor + 1).is_some_and(u8::is_ascii_digit))
        {
            cursor = scan_number(bytes, cursor);
            regex_allowed = false;
            TokenKind::Number
        } else if matches!(byte, b'\'' | b'"') {
            cursor = scan_quoted(bytes, cursor, byte)?;
            regex_allowed = false;
            TokenKind::String
        } else if byte == b'`' {
            cursor = scan_template(bytes, cursor)?;
            regex_allowed = false;
            TokenKind::Template
        } else if byte == b'/' && regex_allowed {
            match scan_regex(bytes, cursor) {
                Some(end) => {
                    cursor = end;
                    regex_allowed = false;
                    TokenKind::Regex
                }
                // A body that runs past a line terminator is not a regular
                // expression. Fall back to punctuation and record that this
                // `/` was not read with certainty.
                None => {
                    slash_classification_certain = false;
                    cursor += punctuation_width(&source[cursor..]);
                    regex_allowed = true;
                    TokenKind::Punct
                }
            }
        } else {
            let width = punctuation_width(&source[cursor..]);
            let text = &source[cursor..cursor + width];
            cursor += width;
            match text {
                "(" => {
                    let header = tokens.last().is_some_and(|token: &Token<'_>| {
                        token.kind == TokenKind::Keyword
                            && matches!(
                                token.text,
                                "if" | "while" | "for" | "with" | "switch" | "catch"
                            )
                    });
                    groups.push(if header {
                        GroupKind::ControlHeader
                    } else {
                        GroupKind::Expression
                    });
                    regex_allowed = true;
                }
                "[" => {
                    groups.push(GroupKind::Bracket);
                    regex_allowed = true;
                }
                "{" => {
                    groups.push(GroupKind::Brace);
                    regex_allowed = true;
                }
                ")" | "]" | "}" => {
                    let opened = groups.pop();
                    regex_allowed = match opened {
                        Some(GroupKind::ControlHeader) => true,
                        Some(GroupKind::Expression | GroupKind::Bracket) => false,
                        // A block's `}` sits at statement position, an object
                        // or function expression's `}` does not. Assume the
                        // statement reading and flag the stream only when a
                        // `/` actually depends on the guess.
                        Some(GroupKind::Brace) | None => {
                            if next_significant_byte(bytes, cursor) == Some(b'/') {
                                slash_classification_certain = false;
                            }
                            true
                        }
                    };
                }
                // A postfix update ends an expression; nothing else that this
                // arm can see does.
                "++" | "--" => {}
                _ => regex_allowed = true,
            }
            TokenKind::Punct
        };
        tokens.push(Token {
            kind,
            text: &source[start..cursor],
            start,
            end: cursor,
        });
    }
    Ok(LexedSource {
        tokens,
        slash_classification_certain,
    })
}

/// Skip whitespace and comments to report the next code byte after `cursor`.
fn next_significant_byte(bytes: &[u8], mut cursor: usize) -> Option<u8> {
    while cursor < bytes.len() {
        let byte = bytes[cursor];
        if byte.is_ascii_whitespace() {
            cursor += 1;
            continue;
        }
        if byte == b'/' && bytes.get(cursor + 1) == Some(&b'/') {
            cursor += 2;
            while cursor < bytes.len() && !matches!(bytes[cursor], b'\n' | b'\r') {
                cursor += 1;
            }
            continue;
        }
        if byte == b'/' && bytes.get(cursor + 1) == Some(&b'*') {
            cursor += 2;
            while cursor + 1 < bytes.len() && &bytes[cursor..cursor + 2] != b"*/" {
                cursor += 1;
            }
            cursor = (cursor + 2).min(bytes.len());
            continue;
        }
        return Some(byte);
    }
    None
}

/// Scan a regular-expression literal body and flags from its opening `/`.
///
/// `\` escapes the next character, a `[...]` class holds an unescaped `/`, and
/// a line terminator inside the body means this `/` was not a regex after all.
fn scan_regex(bytes: &[u8], start: usize) -> Option<usize> {
    let mut cursor = start + 1;
    let mut in_class = false;
    loop {
        let byte = *bytes.get(cursor)?;
        match byte {
            b'\n' | b'\r' => return None,
            b'\\' => {
                // A trailing backslash cannot escape a line terminator here.
                if matches!(bytes.get(cursor + 1), None | Some(b'\n') | Some(b'\r')) {
                    return None;
                }
                cursor += 2;
            }
            b'[' => {
                in_class = true;
                cursor += 1;
            }
            b']' => {
                in_class = false;
                cursor += 1;
            }
            b'/' if !in_class => {
                cursor += 1;
                break;
            }
            _ => cursor += 1,
        }
    }
    // An empty body lexes as a line comment, never as a regex.
    if cursor == start + 2 {
        return None;
    }
    while cursor < bytes.len() && is_identifier_continue(bytes[cursor]) {
        cursor += 1;
    }
    Some(cursor)
}

fn scan_quoted(bytes: &[u8], start: usize, quote: u8) -> Result<usize, JavaScriptParseError> {
    let mut cursor = start + 1;
    while cursor < bytes.len() {
        match bytes[cursor] {
            b'\\' => cursor = (cursor + 2).min(bytes.len()),
            byte if byte == quote => return Ok(cursor + 1),
            b'\n' | b'\r' if quote != b'`' => {
                return Err(JavaScriptParseError {
                    offset: start,
                    message: "unterminated string literal",
                });
            }
            _ => cursor += 1,
        }
    }
    Err(JavaScriptParseError {
        offset: start,
        message: "unterminated string literal",
    })
}

fn scan_template(bytes: &[u8], start: usize) -> Result<usize, JavaScriptParseError> {
    let mut cursor = start + 1;
    while cursor < bytes.len() {
        match bytes[cursor] {
            b'\\' => cursor = (cursor + 2).min(bytes.len()),
            b'`' => return Ok(cursor + 1),
            b'$' if bytes.get(cursor + 1) == Some(&b'{') => {
                cursor = scan_template_expression(bytes, cursor + 2, start)?;
            }
            _ => cursor += 1,
        }
    }
    Err(JavaScriptParseError {
        offset: start,
        message: "unterminated template literal",
    })
}

fn scan_template_expression(
    bytes: &[u8],
    mut cursor: usize,
    template_start: usize,
) -> Result<usize, JavaScriptParseError> {
    let mut brace_depth = 1usize;
    while cursor < bytes.len() {
        match bytes[cursor] {
            b'\'' | b'"' => cursor = scan_quoted(bytes, cursor, bytes[cursor])?,
            b'`' => cursor = scan_template(bytes, cursor)?,
            b'{' => {
                brace_depth += 1;
                cursor += 1;
            }
            b'}' => {
                brace_depth -= 1;
                cursor += 1;
                if brace_depth == 0 {
                    return Ok(cursor);
                }
            }
            _ => cursor += 1,
        }
    }
    Err(JavaScriptParseError {
        offset: template_start,
        message: "unterminated template interpolation",
    })
}

fn scan_number(bytes: &[u8], start: usize) -> usize {
    let mut cursor = start;
    while cursor < bytes.len() {
        let byte = bytes[cursor];
        let exponent_sign = matches!(byte, b'+' | b'-')
            && cursor > start
            && matches!(bytes[cursor - 1], b'e' | b'E');
        if byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_') || exponent_sign {
            cursor += 1;
        } else {
            break;
        }
    }
    cursor
}

fn punctuation_width(source: &str) -> usize {
    let bytes = source.as_bytes();
    match bytes.first().copied() {
        Some(b'>') => match bytes.get(1).copied() {
            Some(b'>') => match bytes.get(2).copied() {
                Some(b'>') if bytes.get(3) == Some(&b'=') => 4,
                Some(b'>' | b'=') => 3,
                _ => 2,
            },
            Some(b'=') => 2,
            _ => 1,
        },
        Some(b'=') => match bytes.get(1).copied() {
            Some(b'=') if bytes.get(2) == Some(&b'=') => 3,
            Some(b'=' | b'>') => 2,
            _ => 1,
        },
        Some(b'!') => match bytes.get(1).copied() {
            Some(b'=') if bytes.get(2) == Some(&b'=') => 3,
            Some(b'=') => 2,
            _ => 1,
        },
        Some(b'*') => match bytes.get(1).copied() {
            Some(b'*') if bytes.get(2) == Some(&b'=') => 3,
            Some(b'*' | b'=') => 2,
            _ => 1,
        },
        Some(b'<') => match bytes.get(1).copied() {
            Some(b'<') if bytes.get(2) == Some(&b'=') => 3,
            Some(b'<' | b'=') => 2,
            _ => 1,
        },
        Some(b'&') => match bytes.get(1).copied() {
            Some(b'&') if bytes.get(2) == Some(&b'=') => 3,
            Some(b'&' | b'=') => 2,
            _ => 1,
        },
        Some(b'|') => match bytes.get(1).copied() {
            Some(b'|') if bytes.get(2) == Some(&b'=') => 3,
            Some(b'|' | b'=') => 2,
            _ => 1,
        },
        Some(b'?') => match bytes.get(1).copied() {
            Some(b'?') if bytes.get(2) == Some(&b'=') => 3,
            Some(b'?') => 2,
            _ => 1,
        },
        Some(b'+') => match bytes.get(1).copied() {
            Some(b'+' | b'=') => 2,
            _ => 1,
        },
        Some(b'-') => match bytes.get(1).copied() {
            Some(b'-' | b'=') => 2,
            _ => 1,
        },
        Some(b'/' | b'%' | b'^') => match bytes.get(1).copied() {
            Some(b'=') => 2,
            _ => 1,
        },
        Some(_) => source.chars().next().map_or(1, char::len_utf8),
        None => 1,
    }
}

const fn is_identifier_start(byte: u8) -> bool {
    byte.is_ascii_alphabetic() || matches!(byte, b'_' | b'$')
}

const fn is_identifier_continue(byte: u8) -> bool {
    is_identifier_start(byte) || byte.is_ascii_digit()
}

fn is_keyword(identifier: &str) -> bool {
    matches!(
        identifier,
        "as" | "async"
            | "await"
            | "break"
            | "case"
            | "catch"
            | "class"
            | "const"
            | "continue"
            | "debugger"
            | "default"
            | "delete"
            | "do"
            | "else"
            | "export"
            | "extends"
            | "false"
            | "finally"
            | "for"
            | "from"
            | "function"
            | "get"
            | "if"
            | "import"
            | "in"
            | "instanceof"
            | "let"
            | "new"
            | "null"
            | "of"
            | "return"
            | "set"
            | "static"
            | "super"
            | "switch"
            | "this"
            | "throw"
            | "true"
            | "try"
            | "typeof"
            | "undefined"
            | "var"
            | "void"
            | "while"
            | "with"
            | "yield"
    )
}

#[cfg(test)]
mod tests {
    use super::{
        analyze_generated_javascript, function_leading_declaration_variant, lex,
        non_overlapping_parsed_node_count, optimize_generated_javascript, parse_expression_regions,
        punctuation_width, reorder_uninitialized_var_declarators, PeepholeResult,
    };

    const LEGACY_PUNCTUATION: [&str; 31] = [
        ">>>=", "===", "!==", "**=", "<<=", ">>=", ">>>", "&&=", "||=", "??=", "=>", "++", "--",
        "**", "<<", ">>", "<=", ">=", "==", "!=", "&&", "||", "??", "+=", "-=", "*=", "/=", "%=",
        "&=", "|=", "^=",
    ];

    fn legacy_punctuation_width(source: &str) -> usize {
        LEGACY_PUNCTUATION
            .iter()
            .find(|punctuation| source.starts_with(**punctuation))
            .map_or_else(
                || source.chars().next().map_or(1, char::len_utf8),
                |punctuation| punctuation.len(),
            )
    }

    fn assert_punctuation_width_matches_legacy(source: &str) {
        assert_eq!(
            punctuation_width(source),
            legacy_punctuation_width(source),
            "punctuation dispatch differed for {source:?}"
        );
    }

    fn assert_operator_alphabet_equivalence(source: &mut String, remaining: usize) {
        if !source.is_empty() {
            assert_punctuation_width_matches_legacy(source);
        }
        if remaining == 0 {
            return;
        }
        for byte in b"=!*<>&|?+-/%^" {
            source.push(char::from(*byte));
            assert_operator_alphabet_equivalence(source, remaining - 1);
            source.pop();
        }
    }

    fn optimize_emitted_without_regex_literals(source: &str) -> PeepholeResult {
        optimize_generated_javascript(source).unwrap()
    }

    fn run_javascript(source: &str) -> String {
        let output = std::process::Command::new("node")
            .arg("-e")
            .arg(source)
            .output()
            .expect("node must execute generated JavaScript");
        assert!(
            output.status.success(),
            "node failed:\n{}\nsource:\n{source}",
            String::from_utf8_lossy(&output.stderr)
        );
        String::from_utf8(output.stdout).expect("node stdout must be UTF-8")
    }

    #[test]
    fn punctuation_dispatch_recognizes_every_legacy_operator() {
        for punctuation in LEGACY_PUNCTUATION {
            assert_eq!(
                punctuation_width(punctuation),
                punctuation.len(),
                "failed to consume all of {punctuation:?}"
            );
            assert_punctuation_width_matches_legacy(punctuation);
            assert_punctuation_width_matches_legacy(&format!("{punctuation}suffix"));
        }
    }

    #[test]
    fn punctuation_dispatch_matches_every_strict_prefix_and_ambiguous_munch() {
        assert_punctuation_width_matches_legacy("");
        for punctuation in LEGACY_PUNCTUATION {
            for prefix_width in 0..punctuation.len() {
                assert_punctuation_width_matches_legacy(&punctuation[..prefix_width]);
            }
        }

        let mut source = String::with_capacity(4);
        assert_operator_alphabet_equivalence(&mut source, 4);

        for (source, expected) in [
            (">>>=", 4),
            (">>>==", 4),
            (">>>>", 3),
            (">>=", 3),
            (">>==", 3),
            (">>", 2),
            ("====", 3),
            ("!===", 3),
            ("**==", 3),
            ("&&==", 3),
            ("||==", 3),
            ("??==", 3),
        ] {
            assert_eq!(punctuation_width(source), expected, "{source:?}");
            assert_punctuation_width_matches_legacy(source);
        }
    }

    #[test]
    fn punctuation_dispatch_preserves_single_character_and_unicode_fallbacks() {
        for byte in 0_u8..=127 {
            let source = char::from(byte).to_string();
            assert_punctuation_width_matches_legacy(&source);
        }

        for source in [
            "a",
            ".25",
            ";tail",
            "~value",
            "@decorator",
            "é",
            "×next",
            "中=value",
            "🦀>>>=",
            "\u{80}",
            "…",
            "é===",
            ">é",
            "=🦀",
        ] {
            assert_punctuation_width_matches_legacy(source);
        }
        for (source, expected) in [("é", 2), ("中=value", 3), ("🦀>>>=", 4)] {
            assert_eq!(punctuation_width(source), expected, "{source:?}");
        }
    }

    #[test]
    fn variants_only_simple_function_leading_generated_declarations() {
        let source = "var a='function(){var no=1}';let b=function*(){var c=1;yield c};function d(e,f){var g=-2,h;return g+h}";
        assert_eq!(
            function_leading_declaration_variant(source).as_deref(),
            Some("var a='function(){var no=1}';let b=function*(){let c=1;yield c};function d(e,f){let g=-2,h;return g+h}")
        );

        for rejected in [
            "function defaults(a=1){var b=1;return b}",
            "function parameter(a){var a=1;return a}",
            "function self(){var a=a||1;return a}",
            "function call(){var a=read();return a}",
            "function redeclared(){var a=1;var a=2;return a}",
            "function hoisted(){var a=1;function a(){}return a}",
            "function nested(){if(x){var a=1}return a}",
            "function header(){for(var a=0;a<1;a++)use(a)}",
            "function text(){return `var a=${value}`}",
        ] {
            assert_eq!(
                function_leading_declaration_variant(rejected),
                None,
                "{rejected}"
            );
        }
    }

    #[test]
    fn rewrites_only_complete_parsed_assignment_statements() {
        let optimized = optimize_generated_javascript(
            "function f(a,b){a=a+b;let c=a+b;if(c)a=a*2;for(;a<9;a=a+1)b=b^a;return a}",
        )
        .unwrap();

        assert_eq!(
            optimized.code,
            "function f(a,b){a+=b;let c=a+b;if(c)a*=2;for(;a<9;a++)b^=a;return a}"
        );
        assert_eq!(optimized.rewrites, 5);
    }

    #[test]
    fn preserves_non_identifier_assignments_and_different_operands() {
        let source = "a.x=a.x+1;a=b+1;return a";
        let optimized = optimize_generated_javascript(source).unwrap();
        assert_eq!(optimized.code, source);
        assert_eq!(optimized.rewrites, 0);
    }

    #[test]
    fn negated_equality_folds_loose_and_strict_without_reordering_operands() {
        let optimized = optimize_emitted_without_regex_literals(
            "let a=!(left()==right()),b=!(left()===right()),c=!(left()!=right()),d=!(left()!==right());use(a,b,c,d)",
        );

        assert_eq!(
            optimized.code,
            "let a=left()!=right(),b=left()!==right(),c=left()==right(),d=left()===right();use(a,b,c,d)"
        );
        assert_eq!(optimized.rewrites, 4);
    }

    #[test]
    fn negated_equality_groups_under_tighter_parents_and_refuses_non_roots() {
        let optimized = optimize_emitted_without_regex_literals(
            "let a=1+!(left()==right()),b=typeof !(left()===right()),c=!(left()==right()&&guard()),d=!(x==/a==b/.test(s));use(a,b,c,d)",
        );

        assert_eq!(
            optimized.code,
            "let a=1+(left()!=right()),b=typeof(left()!==right()),c=!(left()==right()&&guard()),d=x!=/a==b/.test(s);use(a,b,c,d)"
        );
        assert_eq!(optimized.rewrites, 4);
    }

    #[test]
    fn negated_equality_refuses_postfix_yield_and_ambiguous_expression_starts() {
        let source = "!(x==y).z;!(x==y)(z);!(x==y)[z];!(x==y)?.z;!(x==y)`tag`;!(x==y)++;!(x==y)--;!(x==y)**z;new!(x==y);function* g(){return!(yield x==y)};!({}==x);!(function(){}==x);!(class{}==x);!(async function(){}==x)";
        let optimized = optimize_emitted_without_regex_literals(source);

        assert_eq!(optimized.code, source);
        assert_eq!(optimized.rewrites, 0);
    }

    #[test]
    fn negated_equality_requires_proof_that_regex_literals_are_absent() {
        let source = "let a=/!(x==y)/,b=/prefix!(x===y)suffix/;use(a,b)";
        let optimized = optimize_generated_javascript(source).unwrap();

        assert_eq!(optimized.code, source);
        assert_eq!(optimized.rewrites, 0);
    }

    #[test]
    fn canonicalizes_exact_typeof_identifiers_and_ascii_string_members() {
        let optimized = optimize_emitted_without_regex_literals(
            "let a=typeof(value)==\"number\",b=object[\"scrollTop\"],c=this['default'],d=typeof(value)instanceof Object;use(a,b,c,d)",
        );

        assert_eq!(
            optimized.code,
            "let a=typeof value==\"number\",b=object.scrollTop,c=this.default,d=typeof value instanceof Object;use(a,b,c,d)"
        );
        assert_eq!(optimized.rewrites, 4);
    }

    #[test]
    fn reorders_only_uninitialized_var_declarators_before_initializers() {
        let source = "function run(){var log=[],first=(log.push('first'),1),empty,second=(log.push('second'),2),later;var stable,tail=3;return [empty,first,later,second,stable,tail,log.join(',')]}console.log(JSON.stringify(run()))";
        let optimized = optimize_emitted_without_regex_literals(source);

        assert_eq!(
            optimized.code,
            "function run(){var empty,later,stable,log=[],first=(log.push('first'),1),second=(log.push('second'),2),tail=3;return[empty,first,later,second,stable,tail,log.join(',')]}console.log(JSON.stringify(run()))"
        );
        assert_eq!(run_javascript(&optimized.code), run_javascript(source));
    }

    #[test]
    fn var_declarator_reordering_preserves_hoisting_and_for_initializer_order() {
        let source = "let log=[];function run(){var observed=(log.push('first'),typeof later),later;for(var start=(log.push('second'),0),unused,index=(log.push('third'),start);index<1;index++){log.push(observed)}return [later,unused,log.join(',')]}console.log(JSON.stringify(run()))";
        let optimized = optimize_emitted_without_regex_literals(source);

        assert!(
            optimized
                .code
                .contains("var later,observed=(log.push('first'),typeof later)"),
            "{}",
            optimized.code
        );
        assert!(
            optimized.code.contains(
                "for(var unused,start=(log.push('second'),0),index=(log.push('third'),start);"
            ),
            "{}",
            optimized.code
        );
        assert_eq!(run_javascript(&optimized.code), run_javascript(source));
    }

    #[test]
    fn var_declarator_reordering_refuses_tdz_destructuring_and_ambiguous_boundaries() {
        let source = "var top=read(),laterTop;var object={function:0};object.function;if(true){var initializedTop=read(),laterInTopBlock}var methodObject={function(){}};methodObject.function()\n{var initializedCallBlock=read(),laterCallBlock}function run(values){let initialized=read(),later;const first=read(),second=2;var {item}=source,plain;for(var key in source)use(key);for(var value of values)use(value);var kept=read(),/*keep*/empty;use(kept,empty,item,plain,initialized,later,first,second);var asi=read(),laterAsi\nuse(asi,laterAsi);var a=1,empty,b=2\nx,y;return y}use(top,laterTop,initializedTop,laterInTopBlock,initializedCallBlock,laterCallBlock)";
        let (optimized, rewrites) = reorder_uninitialized_var_declarators(source).unwrap();

        assert_eq!(optimized, source);
        assert_eq!(rewrites, 0);

        let unicode_asi = "function unicode(){var a=1,empty,b=2\u{2028}x,y;return y}";
        assert_eq!(
            reorder_uninitialized_var_declarators(unicode_asi)
                .unwrap()
                .0,
            unicode_asi
        );

        let reorderable =
            "function plain(){var initialized=read(),empty;return [initialized,empty]}";
        assert_eq!(
            optimize_generated_javascript(reorderable).unwrap().code,
            "function plain(){var empty,initialized=read();return[initialized,empty]}"
        );
    }

    #[test]
    fn canonical_member_syntax_separates_adjacent_keywords_and_preserves_comments() {
        let source = "let a=object[\"item\"]instanceof Object,b=object[\"key\"]in container;for(object[\"slot\"]of values){}let c=object[\"key\"]/*keep*/in container";
        let optimized = optimize_emitted_without_regex_literals(source);

        assert_eq!(
            optimized.code,
            "let a=object.item instanceof Object,b=object.key in container;for(object.slot of values){}let c=object.key/*keep*/in container"
        );
        assert_eq!(optimized.rewrites, 4);

        let runtime_source = "let object={item:{},key:\"present\",slot:0},container={present:true},values=[3,5],result=[];result.push(object[\"item\"]instanceof Object,object[\"key\"]in container,object[\"key\"]/*keep*/in container);for(object[\"slot\"]of values){result.push(object.slot)}console.log(JSON.stringify(result))";
        let runtime_optimized = optimize_emitted_without_regex_literals(runtime_source);
        assert_eq!(
            run_javascript(&runtime_optimized.code),
            run_javascript(runtime_source)
        );
    }

    #[test]
    fn canonical_leaf_syntax_refuses_ambiguous_or_non_exact_spellings() {
        let source = "typeof(value).length;typeof(value)[\"length\"];typeof(value)();typeof(value)?.length;typeof(value)**2;typeof value;typeof(/*keep*/value);object[\"not-valid\"];object[\"\\x66oo\"];object[\"é\"];object?.[\"safe\"];object /*keep*/[\"safe\"];call()[\"safe\"];[\"safe\"];if(flag)[\"safe\"];let text=`typeof(value) object[\"safe\"]`";
        let optimized = optimize_emitted_without_regex_literals(source);

        assert_eq!(optimized.code, source);
        assert_eq!(optimized.rewrites, 0);

        // A regex body holds the same character sequences the rewrite selects.
        // The lexer reads each literal as one token, so only the spellings
        // outside them fold.
        // `use(a,b)` keeps both bindings live; without a reader they are dead
        // literal initializers and a different pass removes them outright.
        let regex =
            "let a=/typeof(value)/,b=/object[\"safe\"]/;typeof(value);object[\"safe\"];use(a,b)";
        let alongside_regex_literals = optimize_generated_javascript(regex).unwrap();
        assert_eq!(
            alongside_regex_literals.code,
            "let a=/typeof(value)/,b=/object[\"safe\"]/;typeof value;object.safe;use(a,b)"
        );

        // `}` is the one predecessor that does not decide `/` on its own: a
        // block ends at statement position, an object or function expression
        // does not. Refuse the whole artifact rather than guess.
        let after_brace = "function f(){}/re/.test(source);typeof(value)";
        assert_eq!(
            optimize_generated_javascript(after_brace).unwrap().code,
            after_brace
        );
    }

    #[test]
    fn canonical_leaf_syntax_preserves_runtime_property_and_typeof_behavior() {
        let source = "let reads=[],object=new Proxy({value:7,default:9},{get(target,key){reads.push(key);return target[key]}});let result=[typeof(object),object[\"value\"],object[\"default\"]];console.log(JSON.stringify([result,reads]))";
        let optimized = optimize_emitted_without_regex_literals(source);

        assert!(
            optimized.code.contains("typeof object"),
            "{}",
            optimized.code
        );
        assert!(
            optimized.code.contains("object.value"),
            "{}",
            optimized.code
        );
        assert!(
            optimized.code.contains("object.default"),
            "{}",
            optimized.code
        );
        assert_eq!(run_javascript(&optimized.code), run_javascript(source));
    }

    #[test]
    fn folds_assigned_truthy_ternary_to_logical_or() {
        let optimized = optimize_generated_javascript(
            "function f(n){if(n==null)return n+\"\";var s=typeof n;return \"object\"==s||\"function\"==s?(n=i[Object.prototype.toString.call(n)])?n:\"object\":s}",
        )
        .unwrap();
        assert!(
            optimized.code.contains("i[Object.prototype.toString.call(n)]||\"object\""),
            "{}",
            optimized.code
        );
        assert!(
            !optimized.code.contains(")?n:\"object\""),
            "{}",
            optimized.code
        );
    }

    #[test]
    fn folds_an_assignment_followed_by_its_truthiness_guard() {
        let optimized = optimize_generated_javascript(
            "function f(x){a=read(x);if(a){use(a)}b=next();if(b){use(b)}}",
        )
        .unwrap();
        assert_eq!(
            optimized.code,
            "function f(x){if(a=read(x)){use(a)}if(b=next()){use(b)}}"
        );
        assert_eq!(optimized.rewrites, 2);
    }

    #[test]
    fn assignment_guard_folding_stays_within_proven_statement_boundaries() {
        let sources = [
            "function f(x){if(x)a=read();if(a)use(a)}",
            "function f(x){while(x)a=read();if(a)use(a)}",
            "function f(x){x?a=read():b=next();if(b)use(b)}",
            "function f(){a.x=read();if(a.x)use(a.x)}",
            "function f(){a=read();if(b)use(a)}",
        ];

        for source in sources {
            let optimized = optimize_generated_javascript(source).unwrap();
            assert_eq!(optimized.code, source);
        }

        let nested = optimize_generated_javascript(
            "function f(){a=choose(call(1),{x:[2,3]});if(a){use(a)}}",
        )
        .unwrap();
        assert_eq!(
            nested.code,
            "function f(){if(a=choose(call(1),{x:[2,3]})){use(a)}}"
        );
    }

    #[test]
    fn reuses_a_dead_function_scoped_var_binding() {
        let optimized = optimize_generated_javascript(
            "function f(x){var a=first(x);if(a)use(a);var b=second(x);if(b)use(b)}",
        )
        .unwrap();

        assert_eq!(
            optimized.code,
            "function f(x){var a=first(x);if(a)use(a);if(a=second(x))use(a)}"
        );
        assert_eq!(optimized.rewrites, 2);

        let optimized = optimize_generated_javascript(
            "let f=x=>{var a=first(x);if(a)use(a);var b=second(x);if(b)use(b)};",
        )
        .unwrap();
        assert_eq!(
            optimized.code,
            "let f=x=>{var a=first(x);if(a)use(a);if(a=second(x))use(a)};"
        );
    }

    #[test]
    fn never_reuses_a_binding_from_a_sibling_arrow_scope() {
        let source = "let f=x=>{var a=first(x);return a},g=x=>{var b=second(x);return b};";
        let (optimized, reused) = super::reuse_dead_var_binding(source).unwrap();
        assert!(!reused);
        assert_eq!(optimized, source);

        for source in [
            "function f(){var a=first();var b=second();use(b=>a+b)}",
            "function f(){var a=first();var b=second();use((b)=>a+b)}",
            "function f(){var a=first();save(()=>{use(a)});var b=second();return b}",
        ] {
            let (optimized, reused) = super::reuse_dead_var_binding(source).unwrap();
            assert!(!reused, "{optimized}");
            assert_eq!(optimized, source);
        }
    }

    #[test]
    fn keeps_var_keyword_for_multi_declarator_reuse_candidates() {
        let source = "function f(x){var a=first(x);if(a)use(a);var b=second(x),i=0,tmp;for(;i<2;i++)tmp=b;return tmp}";
        let optimized = optimize_generated_javascript(source).unwrap();

        assert!(
            optimized.code.contains("var tmp,b=second(x),i=0"),
            "{}",
            optimized.code
        );
        assert!(!optimized.code.contains("a=second(x)"));
    }

    #[test]
    fn keeps_var_bindings_when_lifetimes_or_nested_names_overlap() {
        for (source, expected) in [
            (
                "function f(x){var a=first(x);var b=second(x);use(a,b)}",
                "function f(x){var a=first(x),b=second(x);use(a,b)}",
            ),
            (
                "function f(x){use(b);var a=first(x);var b=second(x);use(b)}",
                "function f(x){use(b);var a=first(x),b=second(x);use(b)}",
            ),
            (
                "function f(x){var a=first(x);var b=second(x);use(function(b){return b})}",
                "function f(x){var a=first(x),b=second(x);use(function(b){return b})}",
            ),
        ] {
            let optimized = optimize_generated_javascript(source).unwrap();
            assert_eq!(optimized.code, expected);
        }
    }

    #[test]
    fn removes_only_unreferenced_standalone_var_declarations() {
        let optimized = optimize_generated_javascript(
            "let f=a=>{var h;if(a)return 1;return b=>{var h;return b}},q=a=>{var g;return b=>{var x=0,g=1;return b+g}};function g(){var x;use(x)}",
        )
        .unwrap();
        // `var x=0` is dropped too: nothing reads `x`, and evaluating a literal
        // is unobservable, so the initializer cannot be missed.
        assert_eq!(
            optimized.code,
            "let f=a=>a?1:b=>b,q=a=>b=>{var g=1;return b+g};function g(){var x;use(x)}"
        );
        assert_eq!(optimized.rewrites, 7);

        let optimized = optimize_generated_javascript(
            "let f=(a,b)=>{var e;if(a)return b;return e=>{if(e)return e;return b}};",
        )
        .unwrap();
        assert_eq!(optimized.code, "let f=(a,b)=>a?b:e=>e?e:b;");
    }

    #[test]
    fn keeps_bindings_whose_initializer_could_be_observed_or_read() {
        // An unread binding still has to stay when dropping it would drop a
        // call, a property read, or any other evaluation that can be observed.
        for source in [
            "function f(){var x=side();use(1)}",
            "function f(o){var x=o.k;use(1)}",
            "function f(o){var x=o[k()];use(1)}",
            "function f(){var x=1+g();use(1)}",
            "function f(){let x=new C;use(1)}",
        ] {
            assert_eq!(
                optimize_generated_javascript(source).unwrap().code,
                source,
                "must keep an observable initializer: {source}"
            );
        }
        // A literal-initialized binding that is actually read also stays.
        let read = "function f(){var x=2;return x+1}";
        assert_eq!(optimize_generated_javascript(read).unwrap().code, read);
    }

    #[test]
    fn rotates_only_proven_initial_true_flag_loops() {
        let optimized = optimize_generated_javascript(
            "function f(a){var b,c;b=!0;while(b){c=work(a);b=c<12;}return c}",
        )
        .unwrap();
        assert_eq!(
            optimized.code,
            "function f(a){var c;do{c=work(a)}while(c<12);return c}"
        );

        let omitted_terminal_semicolon = optimize_generated_javascript(
            "function f(a){var b,c;b=!0;while(b){c=work(a);b=c<12}return c}",
        )
        .unwrap();
        assert_eq!(omitted_terminal_semicolon.code, optimized.code);

        assert_eq!(
            optimize_generated_javascript(
                "function f(){var a=true;while(a){if(read())continue;a=read()}}"
            )
            .unwrap()
            .code,
            "function f(){var a=true;while(a){if(read())continue;a=read()}}"
        );
        assert_eq!(
            optimize_generated_javascript("function f(){var a=true;while(a){use(a);a=read()}}")
                .unwrap()
                .code,
            "function f(){var a=true;while(a)use(a),a=read();}"
        );
        assert_eq!(
            optimize_generated_javascript("function f(){var a=false;while(a){work();a=read()}}")
                .unwrap()
                .code,
            "function f(){var a=false;while(a)work(),a=read();}"
        );
    }

    #[test]
    fn merges_only_adjacent_same_kind_declarations() {
        let optimized = optimize_generated_javascript(
            "let a;let b=1;var c=2;var d=3;const e=4;const f=5;use(a,b,c,d,e,f)",
        )
        .unwrap();
        assert_eq!(
            optimized.code,
            "let a,b=1;var c=2,d=3;const e=4,f=5;use(a,b,c,d,e,f)"
        );
    }

    #[test]
    fn folds_guarded_returns_and_their_tails_into_one_conditional_return() {
        for (source, expected) in [
            (
                "function f(a){if(a)return 1;return 2}",
                "function f(a){return a?1:2}",
            ),
            (
                "function f(a,b){if(a)return 1;if(b)return 2;return 3}",
                "function f(a,b){return a?1:b?2:3}",
            ),
            (
                "function f(a){if(a){return 1}return 2}",
                "function f(a){return a?1:2}",
            ),
            (
                "function f(a){if(a)return;return 2}",
                "function f(a){return a?void 0:2}",
            ),
            (
                "function f(a){if(a)return 1;else return 2}",
                "function f(a){return a?1:2}",
            ),
            (
                "function f(a){if(a)return 1;else{return 2}}",
                "function f(a){return a?1:2}",
            ),
            (
                "function f(a,b){while(a)if(b)return 1;else return 2}",
                "function f(a,b){while(a)return b?1:2}",
            ),
            (
                "function f(a,b){if(a){if(b)return 1;return 2}return 3}",
                "function f(a,b){return a?b?1:2:3}",
            ),
            (
                "function f(a,b){if(a=b)return 1;return 2}",
                "function f(a,b){return(a=b)?1:2}",
            ),
            (
                "function f(a,b){if(a)return b,1;return 2}",
                "function f(a,b){return a?(b,1):2}",
            ),
            (
                "function f(a){if(/x/.test(a))return 1;return 2}",
                "function f(a){return/x/.test(a)?1:2}",
            ),
        ] {
            assert_eq!(
                optimize_generated_javascript(source).unwrap().code,
                expected
            );
        }
    }

    #[test]
    fn refuses_return_tails_that_are_not_the_next_statement_of_the_same_block() {
        for source in [
            // The `if` is the loop body: fusing the tail into it would leave
            // the loop on the first iteration.
            "function f(a,b){while(b)if(a)return 1;return 2}",
            "function f(a,b){for(;b;)if(a)return 1;return 2}",
            "function f(a,b){l:if(a)return 1;return 2}",
            // Another statement runs between the two returns.
            "function f(a,b){if(a)return 1;b();return 2}",
            // The guarded arm is not a lone return.
            "function f(a,b){if(a){b();return 1}return 2}",
            "function f(a,b){if(a)return 1;else{b();return 2}}",
        ] {
            assert_eq!(optimize_generated_javascript(source).unwrap().code, source);
        }
    }

    #[test]
    fn conditional_return_fusion_preserves_loop_and_ladder_behavior() {
        let source = "function classify(n){if(n<0)return\"negative\";if(n==0)return\"zero\";return\"positive\"}function scan(values){var i=0;while(i<values.length){if(values[i]>2)return i;i++}return -1}var out=[];for(var n of[-1,0,7])out.push(classify(n));out.push(scan([1,2,3]),scan([1,1,1]));console.log(JSON.stringify(out))";
        let optimized = optimize_generated_javascript(source).unwrap();

        assert!(
            optimized
                .code
                .contains("return n<0?\"negative\":n==0?\"zero\":\"positive\""),
            "{}",
            optimized.code
        );
        assert_eq!(run_javascript(&optimized.code), run_javascript(source));
    }

    #[test]
    fn folds_arrow_guard_returns_into_conditional_bodies() {
        let optimized = optimize_generated_javascript(
            "let f=(a,b)=>{if(a==b)return a;return c=>{if(c)return b;return a}};use(f)",
        )
        .unwrap();
        assert_eq!(optimized.code, "let f=(a,b)=>a==b?a:c=>c?b:a;use(f)");

        let undefined_arm = optimize_generated_javascript(
            "let f=(condition,fallback)=>{if(condition)return;return fallback()};use(f)",
        )
        .unwrap();
        assert_eq!(
            undefined_arm.code,
            "let f=(condition,fallback)=>condition?void 0:fallback();use(f)"
        );
    }

    #[test]
    fn folds_expression_only_if_else_arms_into_a_conditional_sequence() {
        let optimized = optimize_generated_javascript(
            "function f(a){if(test(a)){a=a+1;b=a<12;}else{b=false;}return b}",
        )
        .unwrap();
        assert_eq!(
            optimized.code,
            "function f(a){test(a)?(a++,b=a<12):b=false;return b}"
        );
        assert_eq!(optimized.rewrites, 4);

        let optimized = optimize_generated_javascript(
            "function f(x){if(x){first(),second()}else{third(),fourth()}}",
        )
        .unwrap();
        assert_eq!(
            optimized.code,
            "function f(x){x?(first(),second()):(third(),fourth());}"
        );

        let optimized = optimize_generated_javascript(
            "function f(x){if(x){console.log(1)}else{console.log(0)}}",
        )
        .unwrap();
        assert_eq!(optimized.code, "function f(x){console.log(x?1:0);}");

        let optimized = optimize_generated_javascript(
            "q.call(r,\"a\")?console.log(1):console.log(0);q.call(r,\"b\")?console.log(1):console.log(0)",
        )
        .unwrap();
        assert_eq!(
            optimized.code,
            "console.log(q.call(r,\"a\")?1:0);console.log(q.call(r,\"b\")?1:0);"
        );

        for source in [
            "function f(a){if(a){let b=1;use(b)}else{use(a)}}",
            "function f(a){if(a)use(a);else use(0)}",
        ] {
            assert_eq!(optimize_generated_javascript(source).unwrap().code, source);
        }

        // Two returning arms are a conditional return, not a conditional
        // sequence, so the dedicated fold owns them.
        assert_eq!(
            optimize_generated_javascript("function f(a){if(a){return 1}else{return 2}}")
                .unwrap()
                .code,
            "function f(a){return a?1:2}"
        );
    }

    #[test]
    fn groups_assignment_results_used_as_conditional_tests() {
        let optimized = optimize_generated_javascript(
            "let f=()=>{flag=!flag;if(flag)return 'first';return 'second'};use(f)",
        )
        .unwrap();
        assert_eq!(
            optimized.code,
            "let f=()=>(flag=!flag)?'first':'second';use(f)"
        );
    }

    #[test]
    fn groups_sequence_expressions_used_as_conditional_arms() {
        let optimized = optimize_generated_javascript(
            "let f=x=>{if(x)return first(),second();return third(),fourth()};use(f)",
        )
        .unwrap();
        assert_eq!(
            optimized.code,
            "let f=x=>x?(first(),second()):(third(),fourth());use(f)"
        );
    }

    #[test]
    fn derives_stable_nonzero_startup_metrics() {
        let metrics = analyze_generated_javascript(
            "function f(a){while(a)a=f(a-1.25);return a}console.log(f(.5))",
        )
        .unwrap();
        assert_eq!(metrics.functions, 1);
        assert_eq!(metrics.loops, 1);
        assert!(metrics.tokens > 10);
        assert!(metrics.ast_nodes > 5);
        assert!(metrics.parse_cost > 0);
        assert!(metrics.compile_cost > metrics.parse_cost / 2);
        assert!(metrics.estimated_memory_bytes > metrics.bytes as u64);
    }

    #[test]
    fn startup_metrics_count_overlapping_expression_regions_once() {
        let tokens = lex("a?b:c?d:e?f:g").unwrap();
        let parsed = parse_expression_regions(&tokens);
        let overlapping_sum = parsed
            .iter()
            .map(|region| region.expression.node_count())
            .sum::<usize>();
        let non_overlapping = non_overlapping_parsed_node_count(&parsed);

        assert!(
            parsed.len() > 1,
            "expected nested conditional suffix regions"
        );
        assert!(non_overlapping < overlapping_sum);
        assert_eq!(non_overlapping, parsed[0].expression.node_count());
        let metrics = analyze_generated_javascript("a?b:c?d:e?f:g").unwrap();
        assert!(metrics.ast_nodes <= metrics.tokens, "{metrics:?}");
    }

    #[test]
    fn startup_metrics_still_add_disjoint_expression_regions() {
        let tokens = lex("a+b;c*d").unwrap();
        let parsed = parse_expression_regions(&tokens);
        let independent_sum = parsed
            .iter()
            .map(|region| region.expression.node_count())
            .sum::<usize>();

        assert_eq!(parsed.len(), 2, "{parsed:?}");
        assert_eq!(non_overlapping_parsed_node_count(&parsed), independent_sum);
    }

    #[test]
    fn nesting_metric_includes_expression_depth_without_delimiters() {
        let shallow = analyze_generated_javascript("a?b:c").unwrap();
        let deep = analyze_generated_javascript("a?b?c?d:e:f:g").unwrap();
        assert!(
            deep.max_nesting > shallow.max_nesting,
            "{shallow:?} {deep:?}"
        );
    }

    #[test]
    fn remaps_only_identifier_tokens_for_entropy_probes() {
        let mut mapping = std::array::from_fn(|index| index as u8);
        mapping[b'a' as usize] = b'z';
        assert_eq!(
            super::remap_single_character_identifiers(
                "let a='a';a=obj.a+1e-7;console.log(`${a}`)",
                &mapping,
            )
            .unwrap(),
            "let z='a';z=obj.z+1e-7;console.log(`${z}`)"
        );
    }

    #[test]
    fn scans_unicode_in_nested_template_interpolations_without_splitting_utf8() {
        let source = "let f=a=>`${show(`value × ${a}`)}`;console.log(f(2))";
        let metrics = analyze_generated_javascript(source).unwrap();
        assert!(metrics.tokens > 5, "{metrics:?}");

        let optimized = optimize_generated_javascript(source).unwrap();
        assert!(optimized.code.contains('×'), "{}", optimized.code);
    }

    #[test]
    fn rejects_malformed_generated_javascript() {
        let error = analyze_generated_javascript("function f(){return [1,2}").unwrap_err();
        assert_eq!(error.offset(), 24);
    }
}


#[cfg(test)]
mod keyword_space_tests {
    use super::optimize_generated_javascript;

    #[test]
    fn drops_separators_a_keyword_does_not_need() {
        let optimized = optimize_generated_javascript(
            "function f(a){if(a)return \"x\";return !1}function g(){return [1,2]}",
        )
        .unwrap();
        // The conditional-return fold also fires here, so the guarded pair
        // collapses; what this asserts is that no `return` keeps a separator it
        // does not need.
        assert_eq!(
            optimized.code,
            "function f(a){return a?\"x\":!1}function g(){return[1,2]}"
        );
    }

    #[test]
    fn keeps_separators_that_a_keyword_still_needs() {
        for source in [
            "function f(a){return a}",
            "function f(){return 5}",
            "function f(){return .5}",
            "function f(a){return typeof a}",
        ] {
            assert_eq!(
                optimize_generated_javascript(source).unwrap().code,
                source,
                "must not fuse: {source}"
            );
        }
    }

    #[test]
    fn elided_output_still_runs_identically() {
        let source = "function f(a){if(a)return -1;return (a,0)}function g(){return /b/.test(\"abc\")}";
        let optimized = optimize_generated_javascript(source).unwrap();
        assert!(optimized.code.len() < source.len());
        let script = format!("{}\nconsole.log([f(1),f(0),g()].join(\",\"));", optimized.code);
        let original = format!("{source}\nconsole.log([f(1),f(0),g()].join(\",\"));");
        let run = |code: &str| {
            let path = std::env::temp_dir().join(format!("lil-kw-{}.js", code.len()));
            std::fs::write(&path, code).unwrap();
            let out = std::process::Command::new("node").arg(&path).output().unwrap();
            String::from_utf8_lossy(&out.stdout).trim().to_string()
        };
        assert_eq!(run(&script), run(&original));
        assert_eq!(run(&script), "-1,0,true");
    }

    #[test]
    fn folds_index_assigns_into_postfix_updates() {
        let assign = optimize_generated_javascript("function m(a,b){var i=a.length,j=0;for(;j<b.length;j++)a[i]=b[j],i++;return a}")
            .unwrap();
        assert!(assign.code.contains("a[i++]=b[j]"), "{}", assign.code);
        assert!(!assign.code.contains(",i++"), "{}", assign.code);

        let read = optimize_generated_javascript("function t(a){var i=0,n,s=\"\";for(;;){n=a[i],i++;if(n==null)break;s+=n}return s}")
            .unwrap();
        assert!(read.code.contains("n=a[i++]"), "{}", read.code);

        let original = "function m(a,b){var i=a.length,j=0;for(;j<b.length;j++)a[i]=b[j],i++;a.length=i;return a}console.log(JSON.stringify(m([1], [2,3])))";
        let folded = optimize_generated_javascript(original).unwrap();
        assert_eq!(run_node(&folded.code).trim(), run_node(original).trim());
        assert_eq!(run_node(&folded.code).trim(), "[1,2,3]");
    }

    #[test]
    fn folds_conditional_push_into_a_singleton_array() {
        let optimized = optimize_generated_javascript(
            "function eq(f){var i=this.length;g=[];f>=0&&f<i&&g.push(this[f]);return this.pushStack(g)}",
        )
        .unwrap();
        assert!(
            optimized.code.contains("return this.pushStack(f>=0&&f<i?[this[f]]:[])"),
            "{}",
            optimized.code
        );

        let original = "function eq(f){var i=this.length;var g=[];f>=0&&f<i&&g.push(this[f]);return g}console.log(JSON.stringify(eq.call({0:\"a\",1:\"b\",length:2},1)))";
        let folded = optimize_generated_javascript(original).unwrap();
        assert_eq!(run_node(&folded.code).trim(), run_node(original).trim());
        assert_eq!(run_node(&folded.code).trim(), "[\"b\"]");
    }

    #[test]
    fn folds_guarded_boolean_and_into_an_addend() {
        let source = "function eq(f){var i=this.length,g=f<0;!g||(g=this.length);f+=g;return f}";
        let (direct, count) = super::fold_guarded_and_addends(source).unwrap();
        assert!(
            count > 0 && direct.contains("f+=f<0&&this.length"),
            "{count} {direct}"
        );
        let optimized = optimize_generated_javascript(source).unwrap();
        assert!(
            optimized.code.contains("f+=f<0&&this.length") || optimized.code.contains("f+=f<0&&i"),
            "{}",
            optimized.code
        );
        assert!(!optimized.code.contains(",g="), "{}", optimized.code);

        let original = "function eq(f){var g=f<0;!g||(g=this.length);f+=g;return f}console.log([eq.call({length:4},-1),eq.call({length:4},2)].join(\",\"))";
        let folded = optimize_generated_javascript(original).unwrap();
        assert_eq!(run_node(&folded.code).trim(), run_node(original).trim());
        assert_eq!(run_node(&folded.code).trim(), "3,2");
    }

    #[test]
    fn folds_statement_unit_updates_to_postfix() {
        let optimized = optimize_generated_javascript(
            "function each(a,n){for(var i=0;i<n;i+=1)a[i]+=1;return a}",
        )
        .unwrap();
        assert!(optimized.code.contains("i++"), "{}", optimized.code);
        assert!(!optimized.code.contains("i+=1"), "{}", optimized.code);
        assert!(optimized.code.contains("a[i]+=1"), "{}", optimized.code);

        let original = "function each(a,n){for(var i=0;i<n;i+=1)a[i]+=1;return a}console.log(each([1,2],2).join(\",\"))";
        let folded = optimize_generated_javascript(original).unwrap();
        assert_eq!(run_node(&folded.code).trim(), run_node(original).trim());
        assert_eq!(run_node(&folded.code).trim(), "2,3");
    }

    #[test]
    fn folds_coalesced_or_into_a_returned_disjunction() {
        let optimized = optimize_generated_javascript(
            "function end(){var s=this.prevObject;!s&&(s=this.constructor());return s}",
        )
        .unwrap();
        assert_eq!(
            optimized.code,
            "function end(){return this.prevObject||this.constructor()}"
        );

        let original = "function end(){var s=this.prevObject;!s&&(s=this.constructor());return s}console.log(end.call({prevObject:0,constructor:()=>\"c\"}))";
        let folded = optimize_generated_javascript(original).unwrap();
        assert_eq!(run_node(&folded.code).trim(), run_node(original).trim());
        assert_eq!(run_node(&folded.code).trim(), "c");
    }

    #[test]
    fn folds_coalesced_or_into_a_method_receiver() {
        let optimized = optimize_generated_javascript(
            "function strip(e){e=e.match(o);!e&&(e=[]);return e.join(\" \")}",
        )
        .unwrap();
        assert_eq!(optimized.code, "function strip(e){return(e.match(o)||[]).join(\" \")}");
    }

    #[test]
    fn flattens_parenthesized_string_concat_chains() {
        let optimized = optimize_generated_javascript(
            "function tag(n){return \"[object \"+(n+\"]\")}",
        )
        .unwrap();
        assert_eq!(optimized.code, "function tag(n){return\"[object \"+n+\"]\"}");
    }

    #[test]
    fn flips_trailing_false_equality_without_dropping_the_callee() {
        let optimized = optimize_generated_javascript(
            "function each(t,n){for(r in t)if(n.call(t[r],r,t[r])===!1)break;return t}",
        )
        .unwrap();
        assert!(
            optimized.code.contains("!1===n.call(t[r],r,t[r])"),
            "{}",
            optimized.code
        );
        assert!(!optimized.code.contains("n.!1"), "{}", optimized.code);

        let apply = optimize_generated_javascript(
            "function fire(a,i,m){if(a[i].apply(m[0],m[1])===!1)a.length=0}",
        )
        .unwrap();
        assert!(
            apply.code.contains("!1===a[i].apply(m[0],m[1])"),
            "{}",
            apply.code
        );
        assert!(!apply.code.contains(".!1"), "{}", apply.code);
    }

    #[test]
    fn folds_false_break_into_the_for_condition() {
        let optimized = optimize_generated_javascript(
            "function each(t,n){for(var r=0,e=t.length;r<e;r++){if(n.call(t[r],r,t[r])===!1)break}return t}",
        )
        .unwrap();
        assert!(
            optimized.code.contains("!1!==n.call(t[r],r,t[r])")
                && optimized.code.contains("r++")
                && !optimized.code.contains("break"),
            "{}",
            optimized.code
        );
    }

    #[test]
    fn folds_truthy_index_walks_into_for_header_assigns() {
        let optimized = optimize_generated_javascript(
            "function text(o){var d=0,t=\"\",M;for(;!0;){M=d+1;d=o[d];if(!d)break;t+=l(d);d=M}return t}",
        )
        .unwrap();
        assert!(
            optimized.code.contains("M=o[d++]") && optimized.code.contains("t+=l(M);"),
            "{}",
            optimized.code
        );

        let original = "function l(n){return n.v||\"\"}function text(o){var d=0,t=\"\",M;for(;!0;){M=d+1;d=o[d];if(!d)break;t+=l(d);d=M}return t}console.log(text([{v:\"a\"},{v:\"b\"}]))";
        let folded = optimize_generated_javascript(original).unwrap();
        assert_eq!(run_node(&folded.code).trim(), run_node(original).trim());
        assert_eq!(run_node(&folded.code).trim(), "ab");
    }

    #[test]
    fn folds_self_minus_one_into_decrement() {
        let optimized = optimize_generated_javascript("function f(i){i=i-1;return i}").unwrap();
        assert!(optimized.code.contains("i--"), "{}", optimized.code);
        assert!(!optimized.code.contains("i=i-1"), "{}", optimized.code);
    }

    #[test]
    fn copies_identifier_aliases_into_their_only_reads() {
        let optimized = optimize_generated_javascript(
            "function xml(f){var h=f&&f.nodeName,E=f&&f.namespaceURI;f=T;!E&&(E=h||\"HTML\");return!f.test(E)}",
        )
        .unwrap();
        assert!(
            optimized.code.contains("return!T.test(") && !optimized.code.contains("f=T"),
            "{}",
            optimized.code
        );
    }

    #[test]
    fn folds_temp_computed_keys_into_the_member() {
        let optimized = optimize_generated_javascript(
            "function add(h,E){let i=\"[object \"+E+\"]\";h[i]=E.toLowerCase();return h}",
        )
        .unwrap();
        assert!(
            optimized.code.contains("h[\"[object \"+E+\"]\"]=E.toLowerCase()"),
            "{}",
            optimized.code
        );

        let arrow = optimize_generated_javascript(
            "let add=(h,E)=>{let i=\"[object \"+E+\"]\";h[i]=E.toLowerCase()}",
        )
        .unwrap();
        assert!(arrow.code.contains("h[\"[object \"+E+\"]\"]"), "{}", arrow.code);
        assert!(arrow.code.contains("}"), "{}", arrow.code);
    }

    #[test]
    fn folds_trailing_for_increments_into_the_header() {
        let optimized = optimize_generated_javascript(
            "function m(f,h){for(var r=+h.length,E=0,i=0;i<r;){f[E++]=h[i];i++;}return f}",
        )
        .unwrap();
        assert!(
            optimized.code.contains("for(var r=+h.length,E=0,i=0;i<r;i++)"),
            "{}",
            optimized.code
        );
        assert!(!optimized.code.contains("i++;"), "{}", optimized.code);
        assert!(
            optimized.code.contains("h[i];return") || optimized.code.contains("h[i]; return"),
            "{}",
            optimized.code
        );
    }

    #[test]
    fn does_not_comma_join_continue_into_an_expression() {
        let optimized = optimize_generated_javascript(
            "function f(){for(var n=0;n<3;n++){if(n==1){n++;continue}}return n}",
        )
        .unwrap();
        assert!(
            !optimized.code.contains(",continue"),
            "{}",
            optimized.code
        );
        assert_eq!(
            run_node(&format!("{};console.log(f())", optimized.code)).trim(),
            "3"
        );
    }

    #[test]
    fn does_not_lift_trailing_increment_when_continue_already_increments() {
        let original = "function f(a){var n=0,s=0;for(;n<a.length;){if(a[n]==null){n++;continue}s+=a[n];n++;}return s}console.log(f([1,null,2]))";
        let optimized = optimize_generated_javascript(original).unwrap();
        assert!(
            !optimized.code.contains("for(;n<a.length;n++)"),
            "{}",
            optimized.code
        );
        assert_eq!(run_node(&optimized.code).trim(), run_node(original).trim());
        assert_eq!(run_node(&optimized.code).trim(), "3");
    }

    #[test]
    fn does_not_lift_trailing_increment_when_continue_skips_it() {
        let original = "function f(a){var n=0,s=0;for(;n<a.length;){if(a[n]==null)continue;s+=a[n];n++;}return s}";
        let optimized = optimize_generated_javascript(original).unwrap();
        assert!(
            !optimized.code.contains("for(;n<a.length;n++)"),
            "{}",
            optimized.code
        );
        assert!(
            optimized.code.contains("n++") || optimized.code.contains("++n"),
            "{}",
            optimized.code
        );
    }

    #[test]
    fn uses_cached_length_in_the_for_condition() {
        let each = optimize_generated_javascript(
            "function each(j,t){for(var n=j.length,r=0;r<j.length&&t(j[r]);r++);return j}",
        )
        .unwrap();
        assert!(each.code.contains("r<n&&"), "{}", each.code);
        assert!(!each.code.contains("r<j.length"), "{}", each.code);

        let grep = optimize_generated_javascript(
            "function g(j,t,r){var n=[],i=j.length,o=!r;for(r=0;r<j.length;r++)n.push(j[r]);return n}",
        )
        .unwrap();
        assert!(grep.code.contains("r<i"), "{}", grep.code);

        let prefix = optimize_generated_javascript(
            "let v=(i,q,t)=>{var b=[],d=i.length,p=!t;for(t=0;t<i.length;++t)!q(i[t],t)!=p&&b.push(i[t]);return b}",
        )
        .unwrap();
        assert!(prefix.code.contains("t<d"), "{}", prefix.code);
    }

    #[test]
    fn copies_module_aliases_past_nested_function_assigns() {
        let optimized = optimize_generated_javascript(
            "let q=n;function x(){var n=1;return n}k={push:q}",
        )
        .unwrap();
        assert!(optimized.code.contains("push:n"), "{}", optimized.code);
        assert!(!optimized.code.contains("push:q"), "{}", optimized.code);
    }

    #[test]
    fn copies_reads_before_a_later_reassignment() {
        let optimized = optimize_generated_javascript(
            "let N=j;k={constructor:N};N=j;c.call(N)",
        )
        .unwrap();
        assert!(
            optimized.code.contains("constructor:j") && optimized.code.contains("c.call(j)"),
            "{}",
            optimized.code
        );
    }

    #[test]
    fn prefers_a_cached_member_binding_over_rereading_the_property() {
        let text = optimize_generated_javascript(
            "function text(t){var r=t.nodeType;if(!t.nodeType){return\"\"}return r}",
        )
        .unwrap();
        assert!(
            text.code.contains("!r") && text.code.contains("return"),
            "{}",
            text.code
        );
        assert_eq!(text.code.matches("nodeType").count(), 1, "{}", text.code);

        let grep = optimize_generated_javascript(
            "let i=z=>z,l=(z,t,r)=>{var n=[],i=z.length,o=!r;for(r=0;r<z.length;r++)n.push(z[r]);return n}",
        )
        .unwrap();
        assert!(grep.code.contains("r<i"), "{}", grep.code);
    }

    #[test]
    fn drops_unused_member_copy_declarators() {
        let optimized = optimize_generated_javascript("let q=k.push,T=k.sort;k={push:k.push,sort:k.sort}").unwrap();
        assert!(!optimized.code.contains("q="), "{}", optimized.code);
        assert!(!optimized.code.contains("T="), "{}", optimized.code);
        assert!(optimized.code.contains("push:k.push"), "{}", optimized.code);

        let used_before = optimize_generated_javascript(
            "let o=j=>b.call(j);var b=t.toString,q=k.push;k={push:k.push}",
        )
        .unwrap();
        assert!(used_before.code.contains("b=t.toString"), "{}", used_before.code);
        assert!(!used_before.code.contains("q="), "{}", used_before.code);
    }

    #[test]
    fn rematerializes_same_scope_single_use_empty_functions_and_regexes() {
        let noop = optimize_generated_javascript("let H=()=>{},o=1;k={noop:H,id:o}").unwrap();
        assert!(
            noop.code.contains("noop:()=>{}") && !noop.code.contains("H="),
            "{}",
            noop.code
        );

        let regex = optimize_generated_javascript(
            "let O=/\\D/g;k={expando:(\"jQuery\"+Math.random()).replace(O,\"\")}",
        )
        .unwrap();
        assert!(
            regex.code.contains(".replace(/\\D/g,\"\")") && !regex.code.contains("O="),
            "{}",
            regex.code
        );

        let shared = optimize_generated_javascript("let H=()=>{};k={a:H,b:H}").unwrap();
        assert!(shared.code.contains("H=()=>{}"), "{}", shared.code);

        let nested = optimize_generated_javascript("let H=()=>{};function f(){return H}").unwrap();
        assert!(
            nested.code.contains("H=()=>{}") && nested.code.contains("return H"),
            "{}",
            nested.code
        );
    }

    #[test]
    fn reuses_existing_tostring_aliases_for_prototype_calls() {
        let object = optimize_generated_javascript(
            "let K=a=>k[Object.prototype.toString.call(a)];var k={},C=k.toString",
        )
        .unwrap();
        assert!(
            object.code.contains("C.call(a)") && !object.code.contains("Object.prototype.toString"),
            "{}",
            object.code
        );

        let function = optimize_generated_javascript(
            "let q=a=>D.call(a)==w;var w=Function.prototype.toString.call(Object),k={},t=k.hasOwnProperty,D=t.toString",
        )
        .unwrap();
        assert!(
            function.code.contains("D.call(a)==D.call(Object)")
                && !function.code.contains("Function.prototype.toString")
                && !function.code.contains("w="),
            "{}",
            function.code
        );
    }

    #[test]
    fn chains_repeated_member_assigns_of_the_same_binding() {
        let optimized = optimize_generated_javascript("k={};j.fn=k;j.prototype=k;j.extend=c").unwrap();
        assert!(
            optimized.code.contains("j.fn=j.prototype=k"),
            "{}",
            optimized.code
        );
    }

    #[test]
    fn folds_coalesced_or_into_a_regex_test() {
        let optimized = optimize_generated_javascript(
            "function xml(e,t,o){var d=e&&e.namespaceURI;!d&&(d=t&&t.nodeName||\"HTML\");return!o.test(d)}",
        )
        .unwrap();
        assert_eq!(
            optimized.code,
            "function xml(e,t,o){return!o.test(e&&e.namespaceURI||t&&t.nodeName||\"HTML\")}"
        );
    }

    #[test]
    fn drops_void_undefined_before_an_immediate_reassign() {
        let optimized = optimize_generated_javascript(
            "function f(){var a;a=void 0;a=g();return a}",
        )
        .unwrap();
        assert!(
            optimized.code.contains("a=g()") && !optimized.code.contains("void 0"),
            "{}",
            optimized.code
        );

        let comma = optimize_generated_javascript(
            "function f(){var e=()=>1,a=void 0;a={n:e};return a}",
        )
        .unwrap();
        assert!(
            comma.code.contains("a={n:") && !comma.code.contains("void 0"),
            "{}",
            comma.code
        );
    }

    #[test]
    fn chains_adjacent_identifier_copies_into_one_assign() {
        let (code, count) = super::fold_chained_identifier_assigns(
            "function f(x){var a,b;a=x;b=a;a=null;return [a,b]}",
        )
        .unwrap();
        assert!(count > 0, "{code}");
        assert!(code.contains("b=a=x"), "{code}");

        let (lists, count) = super::fold_chained_identifier_assigns(
            "function f(){var u,o,i,e;u=[];o=u;e=\"\";i=e;return [o,i,u,e]}",
        )
        .unwrap();
        assert!(count >= 2, "{lists}");
        assert!(lists.contains("o=u=[]") && lists.contains("i=e=\"\""), "{lists}");
    }

    #[test]
    fn folds_preincrement_plus_for_into_prefix_condition() {
        let optimized = optimize_generated_javascript(
            "function f(a,i){i++;for(;i<a.length;i++)a[i]();return i}",
        )
        .unwrap();
        assert!(
            optimized.code.contains("for(;++i<a.length;)"),
            "{}",
            optimized.code
        );
        assert!(!optimized.code.contains("i++;for"), "{}", optimized.code);
    }

    #[test]
    fn folds_assigned_index_break_into_the_for_condition() {
        let optimized = optimize_generated_javascript(
            "function rem(a,v){for(var i=0;!0;){i=a.indexOf(v,i);if(i<0)break;a.splice(i,1)}return a}",
        )
        .unwrap();
        assert!(
            optimized.code.contains("(i=a.indexOf(v,i))>-1"),
            "{}",
            optimized.code
        );
        assert!(!optimized.code.contains("if(i<0)"), "{}", optimized.code);
        assert!(
            !optimized.code.contains("var i=0") && !optimized.code.contains(">=0"),
            "{}",
            optimized.code
        );
    }

    #[test]
    fn absorbs_prior_assigns_into_a_nonempty_for_init() {
        let chained = optimize_generated_javascript(
            "function f(q){var n,c;n=!0;for(c=!0;q.length;c=-1)q.pop();return n}",
        )
        .unwrap();
        assert!(
            chained.code.contains("n=c=!0") || chained.code.contains("for(n=c=!0"),
            "{}",
            chained.code
        );

        let empty_init = optimize_generated_javascript(
            "function f(q){var o,n;o=o||q;n=!0;for(;q.length;)q.pop();return o}",
        )
        .unwrap();
        assert!(
            empty_init.code.contains("for(o=o||q,n=!0;")
                || empty_init.code.contains("for(n=!0,o=o||q;"),
            "{}",
            empty_init.code
        );
    }

    #[test]
    fn folds_statement_or_assign_into_for_init() {
        let and_form = optimize_generated_javascript(
            "function f(o,e,r,n,c,i){!r&&(r=o.once);for(c=n=!0;e.length;i=-1)e.pop();return r}",
        )
        .unwrap();
        assert!(
            and_form.code.contains("for(r=r||o.once,c=n=!0;")
                || and_form.code.contains("r=r||o.once"),
            "{}",
            and_form.code
        );
        assert!(!and_form.code.contains("!r&&(r="), "{}", and_form.code);

        let if_temp = optimize_generated_javascript(
            "function f(o,e,r,n,c,i){if(!r){var t=o.once;r=t}for(c=n=!0;e.length;i=-1)e.pop();return r}",
        )
        .unwrap();
        assert!(
            if_temp.code.contains("r=r||o.once"),
            "{}",
            if_temp.code
        );
        assert!(!if_temp.code.contains("if(!r)"), "{}", if_temp.code);

        let original = "function f(o,e,r,n,c,i){!r&&(r=o.once);for(c=n=!0;e.length;i=-1)e.pop();return r}console.log(f({once:7},[1],0,0,0,0)+','+f({once:8},[],1,0,0,0))";
        let folded = optimize_generated_javascript(original).unwrap();
        assert_eq!(run_node(&folded.code).trim(), run_node(original).trim());
        assert_eq!(run_node(&folded.code).trim(), "7,1");

        let truthy_clear = optimize_generated_javascript(
            "function empty(t){t&&(t=[]);return t}",
        )
        .unwrap();
        assert!(
            truthy_clear.code.contains("t&&(t=[])") || truthy_clear.code.contains("t&&(t=[]),"),
            "{}",
            truthy_clear.code
        );
        assert!(!truthy_clear.code.contains("t=t||[]"), "{}", truthy_clear.code);
    }

    #[test]
    fn unwraps_expression_bodies_of_nested_for_loops() {
        let optimized = optimize_generated_javascript(
            "function f(t,e,o,i,a){for(c=n=!0;e.length;i=-1){for(a=e.shift();++i<t.length;){!1===t[i].apply(a[0],a[1])&&o.stopOnFalse&&(i=t.length,a=!1)}}o.memory||(a=!1);return t}",
        )
        .unwrap();
        assert!(
            optimized.code.contains(")for(") && optimized.code.contains(";)!1==="),
            "{}",
            optimized.code
        );
        assert!(
            !optimized.code.contains("length;){") && !optimized.code.contains(";){!1==="),
            "{}",
            optimized.code
        );

        let original = "function f(n){var s=0;for(var i=0;i<n;i++){for(var j=0;j<n;j++){s+=1}}return s}console.log(f(3))";
        let folded = optimize_generated_javascript(original).unwrap();
        assert_eq!(run_node(&folded.code).trim(), run_node(original).trim());
        assert_eq!(run_node(&folded.code).trim(), "9");

        let once_unwrapped = optimize_generated_javascript(
            "function d(o,e,t,i,n,c,r,a){for(r=r||o.once,c=n=!0;e.length;i=-1){for(a=e.shift();++i<t.length;)!1===t[i].apply(a[0],a[1])&&o.stopOnFalse&&(i=t.length,a=!1);}o.memory||(a=!1)}",
        )
        .unwrap();
        assert!(
            once_unwrapped.code.contains(")for("),
            "{}",
            once_unwrapped.code
        );
    }

    #[test]
    fn folds_fire_tail_into_comma_statements() {
        let optimized = optimize_generated_javascript(
            "function f(b,a,e){for(;e;)e--;i.memory||(e=!1);d=!1;!b||(a=e?[]:\"\");return a}",
        )
        .unwrap();
        assert!(
            optimized.code.contains("i.memory||(e=!1),d=!1,b&&(a=e?[]:\"\")")
                || optimized.code.contains(",d=!1,b&&("),
            "{}",
            optimized.code
        );
        assert!(
            optimized.code.contains("b&&(") && !optimized.code.contains("!b||("),
            "{}",
            optimized.code
        );

        let lock = optimize_generated_javascript(
            "function lock(e,d,a){!e&&!d&&(e=\"\",a=e);return a}",
        )
        .unwrap();
        assert!(
            lock.code.contains("a=e=\"\""),
            "{}",
            lock.code
        );

        let fire_tail = optimize_generated_javascript(
            "function d(){for(r=r||o.once,c=n=!0;e.length;i=-1)for(a=e.shift();++i<t.length;)!1===t[i].apply(a[0],a[1])&&o.stopOnFalse&&(i=t.length,a=!1);o.memory||(a=!1);n=!1;r&&(t=a?[]:\"\")}",
        )
        .unwrap();
        assert!(
            fire_tail.code.contains("o.memory||(a=!1),n=!1,r&&("),
            "{}",
            fire_tail.code
        );

        let removed = optimize_generated_javascript(
            "function rem(t,i,n){for(var p=0;(p=l(n,t,p))>=0;){t.splice(p,1);p<=i&&--i}return t}",
        )
        .unwrap();
        assert!(
            removed.code.contains("for(var p;(p=l(n,t,p))>-1;)")
                && (removed.code.contains("t.splice(p,1),p<=i&&i--")
                    || removed.code.contains("splice(p,1),p<=i&&i--")),
            "{}",
            removed.code
        );

        let nested_call = optimize_generated_javascript(
            "function rem(t,i,n){return f(arguments,(e,n)=>{for(var p=0;(p=l(n,t,p))>=0;){t.splice(p,1);p<=i&&--i}}),this}",
        )
        .unwrap();
        assert!(
            nested_call.code.contains("t.splice(p,1),p<=i&&i--")
                || nested_call.code.contains("splice(p,1),p<=i&&i--"),
            "{}",
            nested_call.code
        );

        let already_gt = optimize_generated_javascript(
            "function rem(t,i,n){for(var p=0;(p=l(n,t,p))>-1;)t.splice(p,1),p<=i&&i--;return t}",
        )
        .unwrap();
        assert!(
            already_gt.code.contains("for(var p;(p=l(n,t,p))>-1;)"),
            "{}",
            already_gt.code
        );

        let method_unused = optimize_generated_javascript(
            "function make(){var f=-1;return{lock(){var f;return this},read(){return f}}}",
        )
        .unwrap();
        assert!(
            !method_unused.code.contains("lock(){var f;")
                && !method_unused.code.contains("lock(){var f}"),
            "{}",
            method_unused.code
        );
    }

    #[test]
    fn folds_increment_infinite_for_into_prefix_condition() {
        let optimized = optimize_generated_javascript(
            "function f(a,i){i++;for(;;i++){var t=i;if(i>=a.length){break}t=a[i];t()}}",
        )
        .unwrap();
        assert!(
            optimized.code.contains("for(;++i<a.length;)"),
            "{}",
            optimized.code
        );
        assert!(!optimized.code.contains("i++;for"), "{}", optimized.code);
        assert!(!optimized.code.contains("if(i>="), "{}", optimized.code);
        assert!(
            optimized.code.contains("a[i]()") || optimized.code.contains("a[i];"),
            "{}",
            optimized.code
        );
    }

    #[test]
    fn keeps_index_copies_that_are_reassigned_later() {
        let source = "function ext(t,a,r,s,o){var u=t[a];s&&!Array.isArray(u)?u=[]:!s&&!o(u)&&(u={});t[a]=e(u);return t}";
        let optimized = optimize_generated_javascript(source).unwrap();
        assert!(
            optimized.code.contains("u=t[a]") || optimized.code.contains("u=t[a];"),
            "{}",
            optimized.code
        );
        assert!(
            optimized.code.contains("e(u)") || optimized.code.contains("e(u)"),
            "{}",
            optimized.code
        );
    }

    #[test]
    fn inlines_single_use_index_temps_in_a_fire_loop() {
        let optimized = optimize_generated_javascript(
            "function f(a,i,m){i++;for(;;i++){var t=i;if(i>=a.length){break}t=a[i];var c=m[0];!1===t.apply(c,m[1])&&(i=+a.length)}}",
        )
        .unwrap();
        assert!(
            optimized.code.contains("a[i].apply(m[0],m[1])"),
            "{}",
            optimized.code
        );
    }

    #[test]
    fn folds_trailing_return_this_into_a_comma() {
        let fire = optimize_generated_javascript(
            "function fire(){a.fireWith(this,arguments);return this}",
        )
        .unwrap();
        assert!(
            fire.code.contains("return a.fireWith(this,arguments),this"),
            "{}",
            fire.code
        );

        let add = optimize_generated_javascript(
            "function add(){if(i){e&&u.push(e);n();e&&f()}return this}",
        )
        .unwrap();
        assert!(
            add.code.contains("return i&&(") && add.code.contains(",this"),
            "{}",
            add.code
        );
    }

    #[test]
    fn drops_double_not_in_the_middle_of_a_boolean_chain() {
        let optimized = optimize_generated_javascript(
            "function f(a,b,c){a&&!!b&&(c=1);return c}",
        )
        .unwrap();
        assert!(
            optimized.code.contains("a&&b&&") || optimized.code.contains("a&&b&&("),
            "{}",
            optimized.code
        );
        assert!(!optimized.code.contains("!!b"), "{}", optimized.code);
    }

    fn run_node(source: &str) -> String {
        let output = std::process::Command::new("node")
            .arg("-e")
            .arg(source)
            .output()
            .expect("node must execute generated JavaScript");
        assert!(
            output.status.success(),
            "node failed:\n{}\nsource:\n{source}",
            String::from_utf8_lossy(&output.stderr)
        );
        String::from_utf8(output.stdout).expect("node stdout must be UTF-8")
    }
}
